/* ==========================================================================
   KONSEP 10 — MID-CENTURY SKEWED GRID TITLES (HAPPY NEW YEAR 2027)
   Theme: Happy New Year 2027 | Duration: 20s | Scenes: 4 | Aspect Ratio: 16:9
   Resolution: FHD / 2K / 4K (3840x2160) | Recommended Export Bitrate: 100 Mbps
   Style: Kinetic Typography — Mid-Century Film Titles, Skewed Grid & Panel Masks
   Pure Canvas 2D API — Zero Background Glow, Zero External Assets, Seamless Loop
   ========================================================================== */

const EXPORT_CONFIG = {
  width: 3840,
  height: 2160,
  aspectRatio: '16:9',
  fps: 60,
  duration: 20,
  bitrateMbps: 100,
  minBitrateMbps: 100,
  videoBitsPerSecond: 100000000
};

const K10_PALETTE = {
  creamTop: '#F8F2E6',
  creamMid: '#F5EDE0',
  creamBot: '#EFE5D3',
  black: '#14110F',
  charcoal: '#241F1B',
  tangerine: '#FF6B2B',
  tangerineDeep: '#E35216',
  gridLine: 'rgba(20, 17, 15, 0.36)',
  outerFrame: 'rgba(20, 17, 15, 0.18)',
  creamText: '#F7F0E3'
};

const K10_TAU = Math.PI * 2;
const K10_SKEW = -0.185; /* Mid-Century diagonal title shear (~-10.5 deg) */
const K10_COLS = [-0.60, -0.20, 0.20, 0.60];
const K10_ROWS = [-0.27, -0.09, 0.09, 0.27];

function k10Clamp01(v) {
  return v < 0 ? 0 : (v > 1 ? 1 : v);
}

function k10Lerp(a, b, t) {
  return a + (b - a) * t;
}

function k10SubRange(p, s, e) {
  return k10Clamp01((p - s) / (e - s));
}

function k10EaseOutCubic(t) {
  const u = 1 - k10Clamp01(t);
  return 1 - u * u * u;
}

function k10EaseInCubic(t) {
  const u = k10Clamp01(t);
  return u * u * u;
}

function k10EaseInOutCubic(t) {
  const u = k10Clamp01(t);
  return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2;
}

function k10EaseOutQuint(t) {
  const u = 1 - k10Clamp01(t);
  return 1 - u * u * u * u * u;
}

function k10EaseInQuint(t) {
  const u = k10Clamp01(t);
  return u * u * u * u * u;
}

function k10SampleCubic(p0, c1, c2, p1, steps) {
  const pts = [];
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const mt = 1 - t;
    const x = mt * mt * mt * p0[0] + 3 * mt * mt * t * c1[0] + 3 * mt * t * t * c2[0] + t * t * t * p1[0];
    const y = mt * mt * mt * p0[1] + 3 * mt * mt * t * c1[1] + 3 * mt * t * t * c2[1] + t * t * t * p1[1];
    pts.push([x, y]);
  }
  return pts;
}

function k10BuildSuperEllipseRing(cx, cy, rx, ry, power, steps) {
  const pts = [];
  for (let i = 0; i < steps; i++) {
    const a = (i / steps) * K10_TAU;
    const ca = Math.cos(a);
    const sa = Math.sin(a);
    const x = cx + Math.sign(ca) * Math.pow(Math.abs(ca), 2 / power) * rx;
    const y = cy + Math.sign(sa) * Math.pow(Math.abs(sa), 2 / power) * ry;
    pts.push([x, y]);
  }
  return pts;
}

/* Pure solid Mid-Century geometric display glyphs (non-self-intersecting rings) */
function k10BuildSolidGlyphs() {
  const glyph2 = () => {
    const outer = [];
    outer.push([0.04, 0.31]);
    outer.push(...k10SampleCubic([0.04, 0.31], [0.04, 0.09], [0.18, 0.00], [0.36, 0.00], 20));
    outer.push(...k10SampleCubic([0.36, 0.00], [0.55, 0.00], [0.66, 0.11], [0.66, 0.30], 20));
    outer.push(...k10SampleCubic([0.66, 0.30], [0.66, 0.51], [0.49, 0.65], [0.25, 0.84], 24));
    outer.push([0.66, 0.84], [0.66, 1.00], [0.02, 1.00], [0.02, 0.86]);
    outer.push(...k10SampleCubic([0.02, 0.86], [0.22, 0.63], [0.48, 0.48], [0.48, 0.29], 24));
    outer.push(...k10SampleCubic([0.48, 0.29], [0.48, 0.18], [0.43, 0.15], [0.35, 0.15], 12));
    outer.push(...k10SampleCubic([0.35, 0.15], [0.26, 0.15], [0.21, 0.20], [0.21, 0.31], 12));
    return { w: 0.68, rings: [outer] };
  };

  const glyph0 = () => {
    const outer = k10BuildSuperEllipseRing(0.35, 0.50, 0.34, 0.50, 2.5, 64);
    const inner = k10BuildSuperEllipseRing(0.35, 0.50, 0.16, 0.34, 2.4, 56);
    return { w: 0.70, rings: [outer, inner] };
  };

  const glyph7 = () => {
    const outer = [];
    outer.push([0.02, 0.00], [0.65, 0.00], [0.65, 0.155]);
    outer.push(...k10SampleCubic([0.65, 0.155], [0.51, 0.40], [0.40, 0.70], [0.36, 1.00], 24));
    outer.push([0.17, 1.00]);
    outer.push(...k10SampleCubic([0.17, 1.00], [0.22, 0.70], [0.33, 0.40], [0.45, 0.155], 24));
    outer.push([0.15, 0.155], [0.15, 0.23], [0.02, 0.23]);
    return { w: 0.67, rings: [outer] };
  };

  const glyphH = () => ({
    w: 0.68,
    rings: [[[0, 0], [0.19, 0], [0.19, 0.405], [0.49, 0.405], [0.49, 0], [0.68, 0], [0.68, 1], [0.49, 1], [0.49, 0.595], [0.19, 0.595], [0.19, 1], [0, 1]]]
  });

  const glyphA = () => ({
    w: 0.72,
    rings: [
      [[0.255, 0], [0.465, 0], [0.72, 1], [0.525, 1], [0.47, 0.77], [0.25, 0.77], [0.195, 1], [0, 1]],
      [[0.36, 0.23], [0.285, 0.59], [0.435, 0.59]]
    ]
  });

  const glyphP = () => {
    const outer = [
      [0, 0], [0.38, 0],
      ...k10SampleCubic([0.38, 0], [0.57, 0], [0.65, 0.11], [0.65, 0.29], 14),
      ...k10SampleCubic([0.65, 0.29], [0.65, 0.47], [0.57, 0.58], [0.38, 0.58], 14),
      [0.19, 0.58], [0.19, 1], [0, 1]
    ];
    const inner = [
      [0.19, 0.165], [0.35, 0.165],
      ...k10SampleCubic([0.35, 0.165], [0.44, 0.165], [0.47, 0.205], [0.47, 0.29], 10),
      ...k10SampleCubic([0.47, 0.29], [0.47, 0.375], [0.44, 0.415], [0.35, 0.415], 10),
      [0.19, 0.415]
    ];
    return { w: 0.66, rings: [outer, inner] };
  };

  const glyphY = () => ({
    w: 0.68,
    rings: [[[0, 0], [0.21, 0], [0.34, 0.36], [0.47, 0], [0.68, 0], [0.435, 0.56], [0.435, 1], [0.245, 1], [0.245, 0.56]]]
  });

  const glyphN = () => ({
    w: 0.70,
    rings: [[[0, 0], [0.20, 0], [0.51, 0.62], [0.51, 0], [0.70, 0], [0.70, 1], [0.50, 1], [0.19, 0.38], [0.19, 1], [0, 1]]]
  });

  const glyphE = () => ({
    w: 0.60,
    rings: [[[0, 0], [0.58, 0], [0.58, 0.18], [0.19, 0.18], [0.19, 0.41], [0.51, 0.41], [0.51, 0.59], [0.19, 0.59], [0.19, 0.82], [0.59, 0.82], [0.59, 1], [0, 1]]]
  });

  const glyphW = () => ({
    w: 0.94,
    rings: [[[0, 0], [0.19, 0], [0.285, 0.68], [0.405, 0], [0.535, 0], [0.655, 0.68], [0.75, 0], [0.94, 0], [0.75, 1], [0.565, 1], [0.47, 0.39], [0.375, 1], [0.19, 1]]]
  });

  const glyphR = () => {
    const outer = [
      [0, 0], [0.38, 0],
      ...k10SampleCubic([0.38, 0], [0.57, 0], [0.65, 0.11], [0.65, 0.28], 14),
      ...k10SampleCubic([0.65, 0.28], [0.65, 0.43], [0.57, 0.535], [0.46, 0.555], 12),
      [0.68, 1.00], [0.465, 1.00], [0.27, 0.565], [0.19, 0.565], [0.19, 1.00], [0, 1.00]
    ];
    const inner = [
      [0.19, 0.165], [0.35, 0.165],
      ...k10SampleCubic([0.35, 0.165], [0.44, 0.165], [0.47, 0.20], [0.47, 0.28], 10),
      ...k10SampleCubic([0.47, 0.28], [0.47, 0.365], [0.44, 0.405], [0.35, 0.405], 10),
      [0.19, 0.405]
    ];
    return { w: 0.68, rings: [outer, inner] };
  };

  return {
    '2': glyph2(),
    '0': glyph0(),
    '7': glyph7(),
    'H': glyphH(),
    'A': glyphA(),
    'P': glyphP(),
    'Y': glyphY(),
    'N': glyphN(),
    'E': glyphE(),
    'W': glyphW(),
    'R': glyphR(),
    ' ': { w: 0.64, rings: [] }
  };
}

const K10_GLYPHS = k10BuildSolidGlyphs();

function k10MeasureWordWidth(str, h, gapRatio) {
  const gap = h * gapRatio;
  let w = 0;
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    w += K10_GLYPHS[ch].w * h;
    if (i < str.length - 1 && ch !== ' ' && str[i + 1] !== ' ') {
      w += gap;
    }
  }
  return w;
}

function k10DrawWord(ctx, str, cx, cy, h, gapRatio, color, accentDigitColors) {
  const totalW = k10MeasureWordWidth(str, h, gapRatio);
  const gap = h * gapRatio;
  let cursor = cx - totalW * 0.5;
  const y0 = cy - h * 0.5;

  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    const g = K10_GLYPHS[ch];
    const gw = g.w * h;
    if (g.rings.length > 0) {
      ctx.save();
      ctx.translate(cursor, y0);
      ctx.scale(h, h);
      ctx.beginPath();
      for (let r = 0; r < g.rings.length; r++) {
        const pts = g.rings[r];
        ctx.moveTo(pts[0][0], pts[0][1]);
        for (let k = 1; k < pts.length; k++) {
          ctx.lineTo(pts[k][0], pts[k][1]);
        }
        ctx.closePath();
      }
      ctx.fillStyle = (accentDigitColors && accentDigitColors[i]) ? accentDigitColors[i] : color;
      ctx.fill('evenodd');
      ctx.restore();
    }
    cursor += gw;
    if (i < str.length - 1 && ch !== ' ' && str[i + 1] !== ' ') {
      cursor += gap;
    }
  }
}

function k10DrawCrosshair(ctx, cx, cy, r, color) {
  ctx.beginPath();
  ctx.moveTo(cx - r, cy);
  ctx.lineTo(cx + r, cy);
  ctx.moveTo(cx, cy - r);
  ctx.lineTo(cx, cy + r);
  ctx.lineWidth = 0.0022;
  ctx.strokeStyle = color;
  ctx.stroke();
}

/* Draws crisp panel wipe clipped strictly to skewed cell [u0..u1, y0..y1] */
function k10DrawMaskedPanelWipe(ctx, u0, y0, u1, y1, fromSide, openFrac, fillStyle, drawContentFn) {
  const frac = k10Clamp01(openFrac);
  if (frac <= 0.001) return;
  const cellW = u1 - u0;
  const cellH = y1 - y0;
  const visW = cellW * frac;
  const wx = fromSide < 0 ? u0 : u1 - visW;

  ctx.save();
  ctx.beginPath();
  ctx.rect(wx, y0, visW, cellH);
  ctx.clip();

  if (fillStyle) {
    ctx.fillStyle = fillStyle;
    ctx.fillRect(wx, y0, visW, cellH);
  }
  if (drawContentFn) {
    drawContentFn(cellW, cellH);
  }
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const safeLoopT = ((loopT % duration) + duration) % duration;
  const safeScene = Math.max(0, Math.min(sceneCount - 1, Math.floor(safeLoopT / sceneDuration)));
  const safeProgress = (safeLoopT % sceneDuration) / sceneDuration;

  const U = Math.min(height, width * (9 / 16));
  const halfW = (width * 0.5) / U;

  ctx.save();
  ctx.shadowBlur = 0;

  /* 1. Warm Editorial Matte Cream Paper Background (Strictly Zero Background Glow) */
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0.0, K10_PALETTE.creamTop);
  bgGrad.addColorStop(0.5, K10_PALETTE.creamMid);
  bgGrad.addColorStop(1.0, K10_PALETTE.creamBot);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(U, U);

  /* Crisp Static Outer Editorial Border & Vintage Film Registration Marks */
  const fw = Math.min(halfW - 0.040, 0.815);
  const fh = 0.432;
  ctx.beginPath();
  ctx.rect(-fw, -fh, fw * 2, fh * 2);
  ctx.lineWidth = 0.0018;
  ctx.strokeStyle = K10_PALETTE.outerFrame;
  ctx.stroke();

  ctx.save();
  ctx.font = '700 0.0145px Georgia, "Times New Roman", serif';
  ctx.fillStyle = K10_PALETTE.black;
  ctx.globalAlpha = 0.58;
  ctx.textBaseline = 'top';
  ctx.textAlign = 'left';
  ctx.fillText('TITLE SEQUENCE  •  NO. X', -fw + 0.022, -fh + 0.018);
  ctx.textBaseline = 'bottom';
  ctx.textAlign = 'right';
  ctx.fillText('MMXXVII  EDITION', fw - 0.022, fh - 0.018);
  ctx.restore();

  k10DrawCrosshair(ctx, -fw + 0.026, fh - 0.026, 0.0085, K10_PALETTE.tangerine);
  k10DrawCrosshair(ctx, fw - 0.026, -fh + 0.026, 0.0085, K10_PALETTE.tangerine);

  /* 2. Synchronized Scene Parameters (Zero Popping, Zero Line-Over-Text Intersections) */
  let outerRailFrac = 0.0;
  let midRailR2Frac = 0.0;
  let subMullionFrac = 0.0;

  let topBlockFrac = 0.0;
  let botBlockFrac = 0.0;
  let happyAlpha = 0.0;
  let happyWordXOff = 0.0;
  let newPanelFrac = 0.0;
  let newWordXOff = 0.0;
  let accentStripesFrac = 0.0;
  let yearPanelFrac = 0.0;
  let yearWordXOff = 0.0;

  let scene2HeaderFrac = 0.0;
  let scene2HeaderTextSlide = 0.0;
  /* Shutter panels grow cleanly edge->center [0..0.50] or rest parked as [-0.60,-0.50] / [+0.50,+0.60] pillars */
  let leftShutterSpan = 0.0;
  let rightShutterSpan = 0.0;
  let hero2027Visible = false;
  let hero2027SlideY = 0.0;
  let heroRuleFrac = 0.0;

  if (safeScene === 0) {
    /* SCENE 0 (0.00 - 5.00s): Angled grid tracks draw sharply in staggered architectural beats */
    outerRailFrac = k10EaseOutQuint(k10SubRange(safeProgress, 0.04, 0.54));
    midRailR2Frac = k10EaseOutQuint(k10SubRange(safeProgress, 0.16, 0.62));
    subMullionFrac = k10EaseOutQuint(k10SubRange(safeProgress, 0.36, 0.78));
    topBlockFrac = k10EaseOutQuint(k10SubRange(safeProgress, 0.64, 0.90));
    botBlockFrac = k10EaseOutQuint(k10SubRange(safeProgress, 0.72, 0.96));
  } else if (safeScene === 1) {
    /* SCENE 1 (5.00 - 10.00s): Staccato panel reveals for HAPPY, NEW, YEAR inside dedicated non-overlapping grid bays */
    outerRailFrac = 1.0;
    midRailR2Frac = 1.0;
    subMullionFrac = 1.0;
    topBlockFrac = 1.0;
    botBlockFrac = 1.0;

    const b1 = k10EaseOutQuint(k10SubRange(safeProgress, 0.04, 0.30));
    happyAlpha = b1 > 0.01 ? 1.0 : 0.0;
    happyWordXOff = k10Lerp(-0.82, 0.0, b1);

    const b2 = k10EaseOutQuint(k10SubRange(safeProgress, 0.28, 0.52));
    const b2Txt = k10EaseOutQuint(k10SubRange(safeProgress, 0.34, 0.58));
    newPanelFrac = b2;
    newWordXOff = k10Lerp(0.42, 0.0, b2Txt);
    accentStripesFrac = k10EaseOutQuint(k10SubRange(safeProgress, 0.24, 0.48));

    const b3 = k10EaseOutQuint(k10SubRange(safeProgress, 0.54, 0.78));
    const b3Txt = k10EaseOutQuint(k10SubRange(safeProgress, 0.60, 0.86));
    yearPanelFrac = b3;
    yearWordXOff = k10Lerp(-0.82, 0.0, b3Txt);
  } else if (safeScene === 2) {
    /* SCENE 2 (10.00 - 15.00s):
       0.00..0.28: Scene 1 titles & inner mullions exit cleanly
       0.29..0.42: Twin shutters slide IN from edges to meet at center (smooth 0 -> 0.60, zero overlap)
       0.42..0.72: Shutters part OUT back to [-0.60,-0.50] & [+0.50,+0.60] pillars, revealing giant "2027" + Row 0 header */
    outerRailFrac = 1.0;
    midRailR2Frac = 1.0 - k10EaseInCubic(k10SubRange(safeProgress, 0.14, 0.28));
    subMullionFrac = 1.0 - k10EaseInCubic(k10SubRange(safeProgress, 0.12, 0.28));

    const out1 = k10EaseInQuint(k10SubRange(safeProgress, 0.00, 0.20));
    const out2 = k10EaseInQuint(k10SubRange(safeProgress, 0.04, 0.24));
    const out3 = k10EaseInQuint(k10SubRange(safeProgress, 0.08, 0.28));

    happyAlpha = out1 < 0.99 ? 1.0 : 0.0;
    happyWordXOff = k10Lerp(0.0, -0.84, out1);
    topBlockFrac = 1.0 - out2;
    newPanelFrac = 1.0 - out2;
    newWordXOff = k10Lerp(0.0, 0.44, out2);
    accentStripesFrac = 1.0 - out1;
    botBlockFrac = 1.0 - out3;
    yearPanelFrac = 1.0 - out3;
    yearWordXOff = k10Lerp(0.0, 0.84, out3);

    scene2HeaderFrac = k10EaseOutQuint(k10SubRange(safeProgress, 0.30, 0.54));
    scene2HeaderTextSlide = k10Lerp(-0.90, 0.0, k10EaseOutQuint(k10SubRange(safeProgress, 0.38, 0.64)));

    if (safeProgress < 0.42) {
      const closeU = k10EaseOutQuint(k10SubRange(safeProgress, 0.29, 0.415));
      leftShutterSpan = 0.60 * closeU;
      rightShutterSpan = 0.60 * closeU;
      hero2027Visible = false;
    } else {
      const partU = k10EaseOutQuint(k10SubRange(safeProgress, 0.42, 0.68));
      leftShutterSpan = k10Lerp(0.60, 0.10, partU);
      rightShutterSpan = k10Lerp(0.60, 0.10, partU);
      hero2027Visible = true;
      hero2027SlideY = k10Lerp(0.28, 0.0, k10EaseOutQuint(k10SubRange(safeProgress, 0.43, 0.72)));
      heroRuleFrac = k10EaseOutQuint(k10SubRange(safeProgress, 0.66, 0.88));
    }
  } else {
    /* SCENE 3 (15.00 - 20.00s):
       0.00..0.32: Pillars close back inward smoothly (0.10 -> 0.60) while "2027" & Header exit inside masks
       0.32..0.58: Closed shutter curtains retract cleanly outward (0.60 -> 0.00)
       0.58..0.96: Skewed grid rails fold cleanly to 0 -> identical to t=0 */
    outerRailFrac = 1.0 - k10EaseInCubic(k10SubRange(safeProgress, 0.58, 0.96));
    midRailR2Frac = 0.0;
    subMullionFrac = 0.0;

    if (safeProgress < 0.32) {
      const closeBack = k10EaseInOutCubic(k10SubRange(safeProgress, 0.08, 0.30));
      leftShutterSpan = k10Lerp(0.10, 0.60, closeBack);
      rightShutterSpan = k10Lerp(0.10, 0.60, closeBack);
      hero2027Visible = closeBack < 0.98;
      hero2027SlideY = k10Lerp(0.0, 0.28, k10EaseInQuint(k10SubRange(safeProgress, 0.02, 0.26)));
      heroRuleFrac = 1.0 - k10EaseInQuint(k10SubRange(safeProgress, 0.00, 0.18));
    } else {
      const retractU = k10EaseInCubic(k10SubRange(safeProgress, 0.32, 0.56));
      leftShutterSpan = k10Lerp(0.60, 0.0, retractU);
      rightShutterSpan = k10Lerp(0.60, 0.0, retractU);
      hero2027Visible = false;
    }

    scene2HeaderTextSlide = k10Lerp(0.0, 0.95, k10EaseInQuint(k10SubRange(safeProgress, 0.06, 0.28)));
    scene2HeaderFrac = 1.0 - k10EaseInQuint(k10SubRange(safeProgress, 0.20, 0.44));
  }

  /* 3. Enter Skewed Architectural Coordinate System */
  ctx.save();
  ctx.transform(1, 0, K10_SKEW, 1, 0, 0);

  const gU0 = K10_COLS[0];
  const gU1 = K10_COLS[3];
  const gY0 = K10_ROWS[0];
  const gY1 = K10_ROWS[3];

  /* 3A. Scene 1 Staggered Modular Cells */
  if (topBlockFrac > 0.002) {
    k10DrawMaskedPanelWipe(ctx, K10_COLS[2], K10_ROWS[0], K10_COLS[3], K10_ROWS[1], 1, topBlockFrac, K10_PALETTE.tangerine, () => {
      ctx.fillStyle = K10_PALETTE.creamText;
      ctx.fillRect(0.37, -0.205, 0.06, 0.05);
    });
  }

  if (botBlockFrac > 0.002) {
    k10DrawMaskedPanelWipe(ctx, K10_COLS[0], K10_ROWS[2], K10_COLS[1], K10_ROWS[3], -1, botBlockFrac, K10_PALETTE.black, () => {
      ctx.fillStyle = K10_PALETTE.tangerine;
      ctx.beginPath();
      ctx.arc(-0.40, 0.18, 0.022, 0, K10_TAU);
      ctx.fill();
    });
  }

  if (happyAlpha > 0.005) {
    k10DrawMaskedPanelWipe(ctx, K10_COLS[0], K10_ROWS[0], K10_COLS[2], K10_ROWS[1], -1, 1.0, null, () => {
      k10DrawWord(ctx, 'HAPPY', -0.20 + happyWordXOff, -0.18, 0.112, 0.22, K10_PALETTE.black, null);
    });
  }

  if (accentStripesFrac > 0.005) {
