function k9PointInsideRings(rings, px, py, minEdgeDist) {
  let inside = false;
  let minDistSq = 1e9;
  for (let r = 0; r < rings.length; r++) {
    const pts = rings[r];
    const n = pts.length;
    for (let i = 0, j = n - 1; i < n; j = i++) {
      const xi = pts[i][0];
      const yi = pts[i][1];
      const xj = pts[j][0];
      const yj = pts[j][1];
      if (((yi > py) !== (yj > py)) && (px < ((xj - xi) * (py - yi)) / (yj - yi) + xi)) {
