  'A': { w: 0.58, strokes: [[[0.05, 0.94], [0.29, 0.06], [0.53, 0.94]], [[0.13, 0.64], [0.45, 0.64]]] },
  'P': { w: 0.54, strokes: [[[0.07, 0.94], [0.07, 0.06], [0.34, 0.06], [0.46, 0.14], [0.48, 0.28], [0.46, 0.42], [0.34, 0.50], [0.07, 0.50]]] },
  'Y': { w: 0.54, strokes: [[[0.05, 0.06], [0.27, 0.52], [0.49, 0.06]], [[0.27, 0.52], [0.27, 0.94]]] },
  'N': { w: 0.58, strokes: [[[0.06, 0.94], [0.06, 0.06], [0.52, 0.94], [0.52, 0.06]]] },
  'E': { w: 0.50, strokes: [[[0.45, 0.06], [0.06, 0.06], [0.06, 0.94], [0.45, 0.94]], [[0.06, 0.50], [0.38, 0.50]]] },
  'W': { w: 0.76, strokes: [[[0.05, 0.06], [0.19, 0.94], [0.38, 0.34], [0.57, 0.94], [0.71, 0.06]]] },
  'R': { w: 0.54, strokes: [[[0.07, 0.94], [0.07, 0.06], [0.34, 0.06], [0.46, 0.14], [0.48, 0.28], [0.46, 0.42], [0.34, 0.50], [0.07, 0.50]], [[0.29, 0.50], [0.49, 0.94]]] },
  ' ': { w: 0.56, strokes: [] }
};

function k9TraceEditorialLetter(ctx, ch) {
  const def = K9_LETTER_META[ch];
  if (!def || def.strokes.length === 0) return;
  ctx.beginPath();
  for (let s = 0; s < def.strokes.length; s++) {
    const pts = def.strokes[s];
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (let k = 1; k < pts.length; k++) {
      ctx.lineTo(pts[k][0], pts[k][1]);
    }
  }
}

function k9TracePartialRing(ctx, ringMeta, prog01) {
  const p = k9Clamp01(prog01);
  if (p <= 0.001) return;
  const pts = ringMeta.pts;
  const cum = ringMeta.cum;
  const total = ringMeta.total;

  if (p >= 0.999) {
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (let i = 1; i < pts.length; i++) {
      ctx.lineTo(pts[i][0], pts[i][1]);
    }
    ctx.closePath();
    return;
  }

  const targetLen = p * total;
  ctx.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i <= pts.length; i++) {
    const dPrev = cum[i - 1];
    const dCur = cum[i];
    const curPt = pts[i % pts.length];
    if (dCur <= targetLen) {
      ctx.lineTo(curPt[0], curPt[1]);
    } else {
      const segLen = dCur - dPrev;
      const frac = segLen > 1e-6 ? (targetLen - dPrev) / segLen : 0;
      const prevPt = pts[i - 1];
      ctx.lineTo(prevPt[0] + (curPt[0] - prevPt[0]) * frac, prevPt[1] + (curPt[1] - prevPt[1]) * frac);
      break;
    }
  }
}

function k9WaveY(x, baseY, cycle, amp1, amp2, dir2) {
  const ph1 = cycle * K9_TAU * 6;
  const ph2 = cycle * K9_TAU * 4 * dir2;
  return baseY + Math.sin(x * 13.0 + ph1) * amp1 + Math.cos(x * 22.0 + ph2 + 1.1) * amp2;
}

function k9BuildWaveRegionPath(ctx, baseY, cycle, amp1, amp2, dir2, yBot) {
  const xMin = -0.52;
  const xMax = 0.52;
  const steps = 110;
  ctx.beginPath();
  ctx.moveTo(xMin, k9WaveY(xMin, baseY, cycle, amp1, amp2, dir2));
  for (let i = 1; i <= steps; i++) {
    const x = k9Lerp(xMin, xMax, i / steps);
    ctx.lineTo(x, k9WaveY(x, baseY, cycle, amp1, amp2, dir2));
  }
  ctx.lineTo(xMax, yBot);
  ctx.lineTo(xMin, yBot);
  ctx.closePath();
}

function k9DrawDiamond(ctx, cx, cy, r) {
  ctx.beginPath();
  ctx.moveTo(cx, cy - r);
  ctx.lineTo(cx + r, cy);
  ctx.lineTo(cx, cy + r);
  ctx.lineTo(cx - r, cy);
  ctx.closePath();
}

function k9DrawEmergingPhrase(ctx, yCenter, glyphH, revealP, hideP, cycle) {
  const alphaWhole = k9Clamp01(revealP * 4.0) * (1 - k9EaseInCubic(k9SubRange(hideP, 0.35, 1.0)));
  if (alphaWhole <= 0.005) return;

  const phrase = 'HAPPY NEW YEAR';
  const chars = phrase.split('');
  const gap = glyphH * 0.24;
  let totalW = 0;
  const items = [];
  for (let i = 0; i < chars.length; i++) {
    const ch = chars[i];
    if (ch === ' ') {
      totalW += K9_LETTER_META[' '].w * glyphH;
      continue;
    }
    const gw = K9_LETTER_META[ch].w * glyphH;
    items.push({ ch, x: totalW, w: gw, idx: items.length });
    totalW += gw;
    if (i < chars.length - 1 && chars[i + 1] !== ' ') {
      totalW += gap;
    }
  }

  const startX = -totalW * 0.5;
  const yTop = yCenter - glyphH * 0.5;
  const clipTop = yCenter - glyphH * 0.72;
  const clipBot = yCenter + glyphH * 0.72;

  /* Clipped strictly to the lower calm surface horizon slot (disjoint from divider & "2027") */
  ctx.save();
  ctx.beginPath();
  ctx.rect(-0.56, clipTop, 1.12, clipBot - clipTop);
  ctx.clip();

  const count = items.length;
  for (let i = 0; i < count; i++) {
    const it = items[i];
    const rStag = (i / Math.max(1, count - 1)) * 0.44;
    const uIn = k9EaseOutQuart(k9SubRange(revealP, rStag, rStag + 0.56));
    const hStag = ((count - 1 - i) / Math.max(1, count - 1)) * 0.42;
    const uOut = k9EaseInCubic(k9SubRange(hideP, hStag, hStag + 0.58));

    const alpha = k9Clamp01(uIn * 1.18) * (1 - uOut);
    if (alpha <= 0.005) continue;

    /* Rises cleanly from beneath the surface line and descends gently when hiding */
    const dy = (1 - uIn) * (glyphH * 1.12) + uOut * (glyphH * 1.10);
    const waveFloat = Math.sin(cycle * K9_TAU * 3 + i * 0.55) * 0.0022 * uIn * (1 - uOut);
    const cx = startX + it.x + it.w * 0.5;
    const cy = yTop + glyphH * 0.5 + dy + waveFloat;

    ctx.save();
    ctx.globalAlpha *= alpha;
    ctx.translate(cx, cy);
    ctx.scale(glyphH, glyphH);
    ctx.translate(-K9_LETTER_META[it.ch].w * 0.5, -0.5);

    k9TraceEditorialLetter(ctx, it.ch);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.lineWidth = 0.125;
    ctx.strokeStyle = (i >= 5 && i <= 7) ? K9_PALETTE.phraseAccent : K9_PALETTE.phraseText;
    ctx.stroke();
    ctx.restore();
  }
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const safeLoopT = ((loopT % duration) + duration) % duration;
  const safeScene = Math.max(0, Math.min(sceneCount - 1, Math.floor(safeLoopT / sceneDuration)));
  const safeProgress = (safeLoopT % sceneDuration) / sceneDuration;
  const cycle = safeLoopT / duration;

  const U = Math.min(height, width * (9 / 16));
  const halfW = (width * 0.5) / U;

  ctx.save();
  ctx.shadowBlur = 0;

  /* 1. Crisp Matte Deep Plum Canvas Background (Strictly Zero Background Glow) */
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0.0, K9_PALETTE.bgTop);
  bgGrad.addColorStop(0.52, K9_PALETTE.bgMid);
  bgGrad.addColorStop(1.0, K9_PALETTE.bgBot);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(U, U);

  /* Architectural Margin Frame & Corner Diamonds */
  const fw = Math.min(halfW - 0.038, 0.815);
  const fh = 0.436;
  ctx.beginPath();
  ctx.rect(-fw, -fh, fw * 2, fh * 2);
  ctx.lineWidth = 0.0018;
  ctx.strokeStyle = K9_PALETTE.frameLine;
  ctx.stroke();

  const corners = [[-fw, -fh], [fw, -fh], [-fw, fh], [fw, fh]];
  for (let c = 0; c < 4; c++) {
    k9DrawDiamond(ctx, corners[c][0], corners[c][1], 0.0085);
    ctx.fillStyle = K9_PALETTE.outlineSoft;
    ctx.fill();
  }

  /* Subtle Editorial Framing Micro-Captions */
  ctx.save();
  ctx.font = '600 0.0145px Georgia, "Times New Roman", serif';
  ctx.fillStyle = K9_PALETTE.mutedText;
  ctx.globalAlpha = 0.65;
  ctx.textBaseline = 'top';
  ctx.textAlign = 'left';
  ctx.fillText('MMXXVII  •  SERENE EDITION', -fw + 0.022, -fh + 0.018);
  ctx.textBaseline = 'bottom';
  ctx.textAlign = 'right';
  ctx.fillText('HARMONY & FLOW', fw - 0.022, fh - 0.018);
  ctx.restore();

  /* 2. Peripheral 2-Layer Parallax Vector Dewdrops (Strictly Outside Core Area |Y| >= 0.34) */
  for (let i = 0; i < K9_AMBIENT_DEW.length; i++) {
    const p = K9_AMBIENT_DEW[i];
    const ax = p.bx + Math.sin(cycle * K9_TAU * (p.depth > 0.8 ? 1 : 2) + p.phase) * p.rx * p.depth;
    const ay = p.by + Math.cos(cycle * K9_TAU * (p.depth > 0.8 ? 2 : 1) + p.phase) * p.ry * p.depth;
    const pAlpha = 0.16 + 0.12 * (0.5 + 0.5 * Math.sin(cycle * K9_TAU * 3 + p.phase));

    ctx.save();
    ctx.globalAlpha *= pAlpha;
    ctx.beginPath();
    ctx.arc(ax, ay, p.r, 0, K9_TAU);
    if (p.ring) {
      ctx.lineWidth = 0.0017;
      ctx.strokeStyle = K9_PALETTE.outlineSoft;
      ctx.stroke();
    } else {
      ctx.fillStyle = K9_PALETTE.liquidFrontTop;
      ctx.fill();
    }
    ctx.restore();
  }

  /* 3. Synchronized Continuous Timeline Across 3 Scenes */
  let traceStart = 0.0;
  let traceEnd = 0.0;
  let outlineAlpha = 0.0;
  let fillRatio = 0.0;
  let waveAmpMul = 1.0;
  let bubbleAlpha = 0.0;
  let splashWeight = 0.0;
  let heroY = 0.0;
  let heroScale = 1.0;
  let ruleGrow = 0.0;
  let phraseReveal = 0.0;
  let phraseHide = 0.0;
  let gaugeAlpha = 0.0;

  if (safeScene === 0) {
    /* Scene 0 (0.00 - 6.67s): Vector outlines trace staggered, subtle gauge appears, bottom meniscus primes */
    traceStart = 0.0;
    traceEnd = k9Clamp01(k9SubRange(safeProgress, 0.04, 0.78));
    outlineAlpha = k9Lerp(0.15, 0.96, k9EaseOutCubic(k9SubRange(safeProgress, 0.02, 0.25)));
    gaugeAlpha = k9EaseOutCubic(k9SubRange(safeProgress, 0.12, 0.40)) * 0.78;

    const preFill = k9EaseInOutCubic(k9SubRange(safeProgress, 0.74, 1.00));
    fillRatio = preFill * 0.08;
    waveAmpMul = preFill;
    bubbleAlpha = preFill * 0.35;
    splashWeight = 0.0;
  } else if (safeScene === 1) {
    /* Scene 1 (6.67 - 13.33s): Liquid rises with layered waves, rising bubbles & surface splashes, hero elevates */
    traceStart = 0.0;
    traceEnd = 1.0;
    outlineAlpha = 0.96;
    gaugeAlpha = 0.78;

    const riseU = k9EaseInOutSine(k9SubRange(safeProgress, 0.00, 0.78));
    fillRatio = k9Lerp(0.08, 0.83, riseU);
    waveAmpMul = 1.0;
    bubbleAlpha = k9Lerp(0.35, 1.0, k9SubRange(safeProgress, 0.00, 0.22));
    splashWeight = Math.sin(Math.PI * k9Clamp01(k9SubRange(safeProgress, 0.12, 0.76)));

    const elevU = k9EaseInOutCubic(k9SubRange(safeProgress, 0.80, 0.98));
    heroY = k9Lerp(0.0, -0.095, elevU);
    heroScale = k9Lerp(1.0, 0.89, elevU);
  } else {
    /* Scene 2 (13.33 - 20.00s):
       0.00..0.38: Horizon wave rule & "HAPPY NEW YEAR" rise cleanly from liquid plane
       0.38..0.58: Ucapan recedes below surface plane; "2027" returns calmly to center
       0.55..0.86: Liquid drains cleanly back down to 0
       0.84..0.99: Outlines cleanly un-trace back to exact t=0 empty start */
    heroY = k9Lerp(-0.095, 0.0, k9EaseInOutCubic(k9SubRange(safeProgress, 0.44, 0.62)));
    heroScale = k9Lerp(0.89, 1.0, k9EaseInOutCubic(k9SubRange(safeProgress, 0.44, 0.62)));

    ruleGrow = k9EaseOutQuart(k9SubRange(safeProgress, 0.00, 0.16)) * (1 - k9EaseInCubic(k9SubRange(safeProgress, 0.42, 0.56)));
    phraseReveal = k9SubRange(safeProgress, 0.05, 0.34);
    phraseHide = k9SubRange(safeProgress, 0.37, 0.55);

    const drainU = k9EaseInOutSine(k9SubRange(safeProgress, 0.52, 0.85));
    fillRatio = 0.83 * (1 - drainU);
    waveAmpMul = k9Clamp01(1 - k9SubRange(safeProgress, 0.76, 0.86));
    bubbleAlpha = (1 - drainU) * 0.92;
    splashWeight = Math.sin(Math.PI * k9Clamp01(k9SubRange(safeProgress, 0.54, 0.78))) * 0.35;

    traceStart = k9EaseInCubic(k9SubRange(safeProgress, 0.82, 0.985));
    traceEnd = 1.0;
    outlineAlpha = 0.96 * (1 - k9EaseInCubic(k9SubRange(safeProgress, 0.90, 0.995)));
    gaugeAlpha = 0.78 * (1 - k9EaseInCubic(k9SubRange(safeProgress, 0.80, 0.97)));
  }

  /* 4. Render Hero "2027" Group + Liquid Wave Clip + Gauge Flanking Tracks */
  ctx.save();
  ctx.translate(0, heroY);
  ctx.scale(heroScale, heroScale);

  /* 4A. Flanking Minimalist Calibrated Level Scale (Strictly Disjoint at x = +/-0.53) */
  if (gaugeAlpha > 0.005) {
    ctx.save();
    ctx.globalAlpha *= gaugeAlpha;
    const gx = 0.535;
    const gTop = -0.140;
    const gBot = 0.140;
    const levelY = k9Lerp(gBot, gTop, k9Clamp01(fillRatio / 0.83));

    for (let side = -1; side <= 1; side += 2) {
      const sx = gx * side;
      ctx.beginPath();
      ctx.moveTo(sx, gTop);
      ctx.lineTo(sx, gBot);
      ctx.lineWidth = 0.0018;
      ctx.strokeStyle = 'rgba(201, 174, 255, 0.32)';
      ctx.stroke();

      for (let tk = 0; tk <= 4; tk++) {
        const ty = k9Lerp(gBot, gTop, tk / 4);
        ctx.beginPath();
        ctx.moveTo(sx, ty);
        ctx.lineTo(sx + side * 0.012, ty);
        ctx.lineWidth = 0.0016;
        ctx.strokeStyle = 'rgba(201, 174, 255, 0.42)';
        ctx.stroke();
      }

      /* Live meniscus indicator diamond strictly flanking track */
      k9DrawDiamond(ctx, sx - side * 0.016, levelY, 0.0055);
      ctx.fillStyle = K9_PALETTE.meniscus;
      ctx.fill();
    }
    ctx.restore();
  }

  /* 4B. Clipped Dual-Layer Liquid Fill + Non-Overlapping Interior Bubbles + Crest Droplets */
  if (fillRatio > 0.002) {
    const yBottom = K9_HERO_H * 0.5 + 0.012;
    const yTopFill = -K9_HERO_H * 0.5 + 0.012;
    const baseSurfaceY = k9Lerp(yBottom, yTopFill, fillRatio);
    const ampBack1 = 0.0095 * waveAmpMul;
    const ampBack2 = 0.0042 * waveAmpMul;
    const ampFront1 = 0.0110 * waveAmpMul;
    const ampFront2 = 0.0046 * waveAmpMul;

    ctx.save();
    /* Exact even-odd silhouette clip matching all 4 vector numerals */
    ctx.beginPath();
    for (let i = 0; i < K9_HERO_LAYOUT.items.length; i++) {
      const dig = K9_HERO_LAYOUT.items[i];
      for (let r = 0; r < dig.rings.length; r++) {
        const pts = dig.rings[r];
        ctx.moveTo(dig.x0 + pts[0][0] * K9_HERO_H, dig.y0 + pts[0][1] * K9_HERO_H);
        for (let k = 1; k < pts.length; k++) {
          ctx.lineTo(dig.x0 + pts[k][0] * K9_HERO_H, dig.y0 + pts[k][1] * K9_HERO_H);
        }
        ctx.closePath();
      }
    }
    ctx.clip('evenodd');

    /* Layer 1: Deeper counter-moving amethyst wave */
    k9BuildWaveRegionPath(ctx, baseSurfaceY - 0.005 * waveAmpMul, cycle, ampBack1, ampBack2, -1, yBottom + 0.02);
    ctx.save();
    ctx.globalAlpha *= 0.68;
    ctx.fillStyle = K9_PALETTE.liquidBack;
    ctx.fill();
    ctx.restore();

    /* Layer 2: Primary luminous lavender-to-plum gradient wave */
    k9BuildWaveRegionPath(ctx, baseSurfaceY, cycle, ampFront1, ampFront2, 1, yBottom + 0.02);
    const liqGrad = ctx.createLinearGradient(0, baseSurfaceY - 0.02, 0, yBottom);
    liqGrad.addColorStop(0.0, K9_PALETTE.liquidFrontTop);
    liqGrad.addColorStop(0.45, K9_PALETTE.liquidFrontMid);
    liqGrad.addColorStop(1.0, K9_PALETTE.liquidFrontBot);
    ctx.save();
    ctx.globalAlpha *= 0.90;
    ctx.fillStyle = liqGrad;
    ctx.fill();
    ctx.restore();

    /* Crisp meniscus surface highlight line hugging primary front wave */
    ctx.beginPath();
    for (let s = 0; s <= 110; s++) {
      const wx = k9Lerp(-0.52, 0.52, s / 110);
      const wy = k9WaveY(wx, baseSurfaceY, cycle, ampFront1, ampFront2, 1);
      if (s === 0) ctx.moveTo(wx, wy);
      else ctx.lineTo(wx, wy);
    }
    ctx.lineWidth = 0.0042;
    ctx.strokeStyle = K9_PALETTE.meniscus;
    ctx.stroke();

    /* Non-Overlapping Interior Bubbles Riding Fixed Interior Digit Channels */
    if (bubbleAlpha > 0.01) {
      for (let i = 0; i < K9_BUBBLE_STREAMS.length; i++) {
        const b = K9_BUBBLE_STREAMS[i];
        const u = ((cycle * 3.0 * b.speedMul + b.phaseOff) % 1.0 + 1.0) % 1.0;
        const pos = b.posAt(u);
        const bx = pos[0];
        const by = pos[1];
        const surfY = k9WaveY(bx, baseSurfaceY, cycle, ampFront1, ampFront2, 1);
        const subDepth = by - surfY;

        /* Softly emerge from bottom pool and cleanly pop before crossing meniscus */
        if (subDepth <= b.r * 1.4) continue;
        const edgeIn = k9EaseOutCubic(k9SubRange(u, 0.0, 0.14));
        const edgeSurf = k9Clamp01((subDepth - b.r * 1.4) / (b.r * 4.5));
        const topFade = k9Clamp01((1.0 - u) / 0.12);
        const bAlpha = bubbleAlpha * edgeIn * edgeSurf * topFade * 0.85;
        if (bAlpha <= 0.01) continue;

        /* Final guard keeping bubble strictly inside digit stroke wall */
        const rLocal = b.r / K9_HERO_H;
        if (!k9PointInsideRings(b.rings, pos[2], pos[3], rLocal + 0.014)) continue;

        ctx.save();
        ctx.globalAlpha *= bAlpha;
        ctx.beginPath();
        ctx.arc(bx, by, b.r, 0, K9_TAU);
        ctx.fillStyle = K9_PALETTE.bubbleFill;
        ctx.fill();
        ctx.lineWidth = 0.0012;
        ctx.strokeStyle = K9_PALETTE.bubbleRim;
        ctx.stroke();
        ctx.restore();
      }
    }

    /* Parabolic Surface Splash Pearls Confined Inside Unfilled Digit Throat */
    if (splashWeight > 0.01) {
      for (let i = 0; i < K9_SPLASH_SEEDS.length; i++) {
        const sp = K9_SPLASH_SEEDS[i];
        const u = ((cycle * 5.0 + sp.phaseOffset) % 1.0 + 1.0) % 1.0;
        const arc = 4.0 * u * (1.0 - u);
        if (arc <= 0.05) continue;

        const baseX = sp.dig.x0 + sp.lx * K9_HERO_H;
        const surfY = k9WaveY(baseX, baseSurfaceY, cycle, ampFront1, ampFront2, 1);
        const px = baseX + sp.dxFactor * (u - 0.5);
        const py = surfY - arc * sp.arcHeight * splashWeight - sp.r;

        const lxCur = (px - sp.dig.x0) / K9_HERO_H;
        const lyCur = (py - sp.dig.y0) / K9_HERO_H;
        const rLocal = sp.r / K9_HERO_H;
        if (!k9PointInsideRings(sp.dig.rings, lxCur, lyCur, rLocal + 0.012)) continue;

        ctx.save();
        ctx.globalAlpha *= splashWeight * arc * 0.90;
        ctx.beginPath();
        ctx.arc(px, py, sp.r, 0, K9_TAU);
        ctx.fillStyle = K9_PALETTE.splash;
        ctx.fill();
        ctx.restore();
      }
    }

    ctx.restore(); /* end numeral evenodd liquid clip */
  }

  /* 4C. Crisp Architectural Vector Numeral Outline Reveal & Loop-Clean Retraction */
  if (outlineAlpha > 0.005 && traceEnd > traceStart + 0.001) {
    ctx.save();
    ctx.globalAlpha *= outlineAlpha;
    const total = K9_HERO_LAYOUT.items.length;
    for (let i = 0; i < total; i++) {
      const dig = K9_HERO_LAYOUT.items[i];
      const stagIn = i * 0.075;
      const digProgIn = k9EaseOutCubic(k9SubRange(traceEnd, stagIn, 0.78 + stagIn * 0.9));
      const digProgOut = traceStart > 0 ? k9EaseInCubic(k9SubRange(traceStart, stagIn, 0.78 + stagIn * 0.9)) : 0;
      const drawSpan = digProgIn * (1 - digProgOut);
      if (drawSpan <= 0.002) continue;

      const cache = K9_RING_CACHE[dig.ch];
      ctx.save();
      ctx.translate(dig.x0, dig.y0);
      ctx.scale(K9_HERO_H, K9_HERO_H);
      ctx.beginPath();
      for (let r = 0; r < cache.length; r++) {
        const ringP = r === 0 ? drawSpan : k9Clamp01((drawSpan - 0.12) / 0.88);
        k9TracePartialRing(ctx, cache[r], ringP);
      }
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.lineWidth = 0.0145;
      ctx.strokeStyle = fillRatio > 0.05 ? K9_PALETTE.outlineBright : K9_PALETTE.outlineSoft;
      ctx.stroke();
      ctx.restore();
    }
    ctx.restore();
  }

  ctx.restore(); /* end hero "2027" group */

  /* 5. Lower Surface Divider & Liquid-Emerging "HAPPY NEW YEAR" */
  if (ruleGrow > 0.005) {
    const ruleY = 0.088;
    const halfSpan = 0.37 * ruleGrow;
    ctx.beginPath();
    const waveSegs = 48;
    for (let s = 0; s <= waveSegs; s++) {
      const rx = k9Lerp(-halfSpan, halfSpan, s / waveSegs);
      const env = Math.sin((s / waveSegs) * Math.PI);
      const ry = ruleY + Math.sin(rx * 18.0 + cycle * K9_TAU * 5) * 0.0032 * env * ruleGrow;
      if (s === 0) ctx.moveTo(rx, ry);
      else ctx.lineTo(rx, ry);
    }
    ctx.lineWidth = 0.0024;
    ctx.strokeStyle = K9_PALETTE.phraseAccent;
    ctx.stroke();

    k9DrawDiamond(ctx, 0, ruleY, 0.0085 * ruleGrow);
    ctx.fillStyle = K9_PALETTE.meniscus;
    ctx.fill();
  }

  k9DrawEmergingPhrase(ctx, 0.174, 0.054, phraseReveal, phraseHide, cycle);

  ctx.restore();
}

