function k8SampleCubic(p0, c1, c2, p1, steps) {
  const pts = [];
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const mt = 1 - t;
    const x = mt * mt * mt * p0[0] + 3 * mt * mt * t * c1[0] + 3 * mt * t * t * c2[0] + t * t * t * p1[0];
    const y = mt * mt * mt * p0[1] + 3 * mt * mt * t * c1[1] + 3 * mt * t * t * c2[1] + t * t * t * p1[1];
    pts.push([x, y]);
  }
  return pts;
}

function k8BuildSuperEllipseRing(cx, cy, rx, ry, power, steps) {
  const pts = [];
  for (let i = 0; i < steps; i++) {
    const a = (i / steps) * K8_TAU;
    const ca = Math.cos(a);
    const sa = Math.sin(a);
    const x = cx + Math.sign(ca) * Math.pow(Math.abs(ca), 2 / power) * rx;
    const y = cy + Math.sign(sa) * Math.pow(Math.abs(sa), 2 / power) * ry;
    pts.push([x, y]);
  }
  return pts;
}

