/* Even-odd point-in-polygon check + minimum distance from ring boundary */
function k8PointInsideRings(rings, px, py, minEdgeDist) {
  let inside = false;
  let minDistSq = 1e9;
  for (let r = 0; r < rings.length; r++) {
    const pts = rings[r];
    const n = pts.length;
    for (let i = 0, j = n - 1; i < n; j = i++) {
      const xi = pts[i][0];
      const yi = pts[i][1];
      const xj = pts[j][0];
      const yj = pts[j][1];

      if (((yi > py) !== (yj > py)) && (px < ((xj - xi) * (py - yi)) / (yj - yi) + xi)) {
        inside = !inside;
      }

      const dx = xj - xi;
      const dy = yj - yi;
      const lenSq = dx * dx + dy * dy;
      let t = lenSq > 0 ? ((px - xi) * dx + (py - yi) * dy) / lenSq : 0;
      if (t < 0) t = 0;
      else if (t > 1) t = 1;
      const cx = xi + t * dx;
      const cy = yi + t * dy;
      const dSq = (px - cx) * (px - cx) + (py - cy) * (py - cy);
      if (dSq < minDistSq) minDistSq = dSq;
    }
  }
  return inside && minDistSq >= minEdgeDist * minEdgeDist;
}

