      const wLimit = K8_DIGIT_META[dig.ch].w - 0.025;
      for (let lx = 0.025 + staggerX; lx <= wLimit; lx += pitchX / K8_HERO_H) {
        if (k8PointInsideRings(dig.rings, lx, ly, 0.020)) {
          const tx = dig.x0 + lx * K8_HERO_H;
          const ty = dig.y0 + ly * K8_HERO_H;
          const r1 = nextRand();
          const r2 = nextRand();
          const r3 = nextRand();

          /* Elliptical radial staging coordinate strictly outside "2027" perimeter */
          const ellipLen = Math.hypot(tx / 0.45, ty / 0.15);
          const normEX = (tx / 0.45) / (ellipLen || 1);
          const normEY = (ty / 0.15) / (ellipLen || 1);
          const stageEllip = ellipLen * 0.46 + 1.09;
          const sx = normEX * 0.45 * stageEllip;
          const sy = normEY * 0.15 * stageEllip;

          facets.push({
            tx,
            ty,
            sx,
            sy,
            r: maxR * (0.68 + 0.32 * r1),
            isStar: r2 > 0.58,
            tone: r3 < 0.38 ? 0 : (r3 < 0.72 ? 1 : 2), /* 0: platinum, 1: silver, 2: ice cyan */
