  const xL = st * 0.5;
  const xR = w - st * 0.5;
  const yT = st * 0.5;
  const yB = 1 - st * 0.5;

  ctx.beginPath();
  if (ch === 'H') {
    ctx.moveTo(xL, 0); ctx.lineTo(xL, 1);
