    ctx.moveTo(xL, 1); ctx.lineTo(xc, yT); ctx.lineTo(xR, 1);
    ctx.moveTo(k8Lerp(xL, xc, 0.34), 0.65);
    ctx.lineTo(k8Lerp(xR, xc, 0.34), 0.65);
