    ctx.moveTo(xL, yT);
    ctx.lineTo(xR - 0.14, yT);
    ctx.bezierCurveTo(xR + 0.02, yT, xR + 0.02, 0.52, xR - 0.14, 0.52);
    ctx.lineTo(xL, 0.52);
