    ctx.moveTo(xL, 0); ctx.lineTo(xc, 0.50);
    ctx.moveTo(xR, 0); ctx.lineTo(xc, 0.50);
    ctx.lineTo(xc, 1);
  } else if (ch === 'N') {
    ctx.moveTo(xL, 1); ctx.lineTo(xL, yT);
    ctx.lineTo(xR, yB);
    ctx.lineTo(xR, 0);
  } else if (ch === 'E') {
    ctx.moveTo(xL, 0); ctx.lineTo(xL, 1);
    ctx.moveTo(xL, yT); ctx.lineTo(xR, yT);
    ctx.moveTo(xL, 0.49); ctx.lineTo(xR - 0.06, 0.49);
    ctx.moveTo(xL, yB); ctx.lineTo(xR, yB);
