/* Traces a crisp 4-point faceted diamond prism */
function k8TraceDiamond(ctx, cx, cy, r) {
  const rx = r * 1.05;
  const ry = r * 1.25;
  ctx.moveTo(cx, cy - ry);
  ctx.lineTo(cx + rx, cy);
  ctx.lineTo(cx, cy + ry);
  ctx.lineTo(cx - rx, cy);
  ctx.closePath();
}

/* Draws crisp flat-vector parallax silver & ice-blue bokeh WITHOUT background glow */
function k8DrawParallaxBokeh(ctx, list, cycle, alphaMul) {
  for (let i = 0; i < list.length; i++) {
    const b = list[i];
    const px = b.x + Math.sin(cycle * K8_TAU * b.freq + b.ph) * b.ax;
    const py = b.y + Math.cos(cycle * K8_TAU * b.freq + b.ph * 1.2) * b.ay;
    const breathe = 0.88 + 0.12 * Math.sin(cycle * K8_TAU * 2 + b.ph);
    const rad = b.r * breathe;

    const fill = b.tone === 0
      ? 'rgba(220, 234, 252, ' + (0.075 * alphaMul).toFixed(4) + ')'
      : (b.tone === 1
        ? 'rgba(145, 206, 255, ' + (0.085 * alphaMul).toFixed(4) + ')'
        : 'rgba(180, 200, 232, ' + (0.065 * alphaMul).toFixed(4) + ')');
    const rim = b.tone === 2
      ? 'rgba(165, 222, 255, ' + (0.24 * alphaMul).toFixed(4) + ')'
      : 'rgba(235, 244, 255, ' + (0.22 * alphaMul).toFixed(4) + ')';

    ctx.beginPath();
    ctx.arc(px, py, rad, 0, K8_TAU);
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.lineWidth = 0.0014;
    ctx.strokeStyle = rim;
    ctx.stroke();

    if (b.r >= 0.018) {
      ctx.beginPath();
      k8TraceDiamond(ctx, px, py, rad * 0.34);
      ctx.fillStyle = 'rgba(244, 248, 255, ' + (0.14 * alphaMul).toFixed(4) + ')';
      ctx.fill();
    }
  }
}

/* Draws midnight navy-black background, architectural luxury framing & peripheral parallax bokeh */
