  const bgGrad = ctx.createLinearGradient(0, -halfH, 0, halfH);
  bgGrad.addColorStop(0.0, K8_PALETTE.bgTop);
  bgGrad.addColorStop(0.5, K8_PALETTE.bgMid);
  bgGrad.addColorStop(1.0, K8_PALETTE.bgBot);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(-halfW, -halfH, halfW * 2, halfH * 2);

  /* 2. Two Depth Layers of Crisp Parallax Bokeh in Strictly Disjoint Top/Bottom Lanes */
  k8DrawParallaxBokeh(ctx, K8_BOKEH_LAYER_BACK, cycle, 0.85);
  k8DrawParallaxBokeh(ctx, K8_BOKEH_LAYER_FRONT, cycle, 1.0);

  /* 3. Luxury Thin Metallic Framing Border & Corner Diamond Jewels */
  const fx = 0.815;
  const fy = 0.435;
  ctx.lineWidth = 0.0016;
  ctx.strokeStyle = K8_PALETTE.frameLine;
  ctx.strokeRect(-fx, -fy, fx * 2, fy * 2);

  const cornerCoords = [[-fx, -fy], [fx, -fy], [fx, fy], [-fx, fy]];
  ctx.beginPath();
  for (let i = 0; i < 4; i++) {
    k8TraceDiamond(ctx, cornerCoords[i][0], cornerCoords[i][1], 0.0085);
