  ctx.fillStyle = K8_PALETTE.iceLight;
  ctx.fill();

  /* Minimal luxury header/footer micro-typography safely clear of bokeh & center */
  ctx.save();
  ctx.scale(1 / U, 1 / U);
  ctx.font = '600 ' + (0.0155 * U).toFixed(2) + 'px "Georgia", "Times New Roman", serif';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = K8_PALETTE.mutedText;
  ctx.textAlign = 'left';
  ctx.fillText('MMXXVII  •  MIDNIGHT EDITION', -0.785 * U, -0.402 * U);
  ctx.textAlign = 'right';
  ctx.fillText('BRILLIANCE & RENEWAL', 0.785 * U, 0.402 * U);
  ctx.restore();
}

/* Draws "HAPPY NEW YEAR" letter-by-letter cleanly at yCenter with smooth rise & sheen */
function k8DrawEditorialGreeting(ctx, yCenter, glyphH, revealP, hideP, sheenPos) {
  if (revealP <= 0.005 || hideP >= 0.995) return;

  const chars = ['H', 'A', 'P', 'P', 'Y', ' ', 'N', 'E', 'W', ' ', 'Y', 'E', 'A', 'R'];
  const gap = 0.25 * glyphH;
  const spaceW = 0.62 * glyphH;
  let totalW = 0;
  const items = [];
  for (let i = 0; i < chars.length; i++) {
    const ch = chars[i];
    if (ch === ' ') {
      totalW += spaceW;
      continue;
    }
    const gw = K8_LETTER_META[ch].w * glyphH;
    items.push({ ch, x: totalW, w: gw, idx: items.length });
    totalW += gw;
    if (i < chars.length - 1 && chars[i + 1] !== ' ') {
      totalW += gap;
    }
  }

  const startX = -totalW * 0.5;
  const yTop = yCenter - glyphH * 0.5;
  const count = items.length;

  for (let i = 0; i < count; i++) {
    const it = items[i];
    const rStag = (i / Math.max(1, count - 1)) * 0.52;
    const uIn = k8EaseOutQuart(k8SubRange(revealP, rStag, rStag + 0.48));

    const hStag = ((count - 1 - i) / Math.max(1, count - 1)) * 0.42;
    const uOut = k8EaseInCubic(k8SubRange(hideP, hStag, hStag + 0.58));

    const alpha = k8Clamp01(uIn * 1.2) * (1 - uOut);
    if (alpha <= 0.005) continue;

    const dy = (1 - uIn) * 0.016 - uOut * 0.014;
    const sc = k8Lerp(0.90, 1.0, uIn) * k8Lerp(1.0, 0.92, uOut);
    const lx = startX + it.x;
    const cx = lx + it.w * 0.5;
    const cy = yTop + glyphH * 0.5 + dy;

    /* Specular sheen wave boost passing left-to-right */
    const distSheen = Math.abs(cx - sheenPos);
    const sheenBoost = k8Clamp01(1 - distSheen / 0.14);

    ctx.save();
    ctx.globalAlpha *= alpha;
    ctx.translate(cx, cy);
    ctx.scale(sc * glyphH, sc * glyphH);
    ctx.translate(-K8_LETTER_META[it.ch].w * 0.5, -0.5);

    k8TraceEditorialLetter(ctx, it.ch);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.lineWidth = 0.125;

    if (i >= 5 && i <= 7) {
      ctx.strokeStyle = sheenBoost > 0.25 ? K8_PALETTE.silverBright : K8_PALETTE.iceLight;
    } else {
      ctx.strokeStyle = sheenBoost > 0.25 ? '#FFFFFF' : K8_PALETTE.silverMid;
    }
    ctx.stroke();
    ctx.restore();
  }
}

/* Renders single faceted glitter cell with metallic palette & specular glint boost */
function k8DrawFacet(ctx, x, y, r, isStar, tone, highlight, alpha) {
  if (alpha <= 0.005 || r <= 0.0002) return;
  const hBoost = highlight * highlight;

  let fillStyle;
  if (hBoost > 0.52) {
    fillStyle = '#FFFFFF';
  } else if (tone === 0) {
    fillStyle = hBoost > 0.22 ? K8_PALETTE.silverBright : K8_PALETTE.silverMid;
  } else if (tone === 1) {
    fillStyle = hBoost > 0.22 ? K8_PALETTE.iceLight : K8_PALETTE.silverDeep;
  } else {
    fillStyle = hBoost > 0.22 ? K8_PALETTE.iceLight : K8_PALETTE.iceCyan;
  }

  ctx.save();
  ctx.globalAlpha *= alpha;
  ctx.beginPath();
  if (isStar) {
    k8TraceDiamond(ctx, x, y, r * (1.0 + 0.28 * hBoost));
  } else {
    ctx.arc(x, y, r * (1.0 + 0.20 * hBoost), 0, K8_TAU);
  }
  ctx.fillStyle = fillStyle;
  ctx.fill();
  ctx.restore();
}

/* ==========================================================================
   MANDATORY MOTION STUDIO ENTRY POINT
   ========================================================================== */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const safeLoopT = ((loopT % duration) + duration) % duration;
  const safeScene = Math.max(0, Math.min(sceneCount - 1, Math.floor(safeLoopT / sceneDuration)));
  const safeProgress = (safeLoopT % sceneDuration) / sceneDuration;
  const cycle = safeLoopT / duration;

  const U = Math.min(height, width * (9 / 16));

  ctx.save();
  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(U, U);

  /* 1. Midnight Blue-Black Background + Crisp Parallax Silver Bokeh (Zero Glow) */
  k8DrawEnvironment(ctx, width, height, U, safeLoopT, duration);

  /* 2. Compute Coordinated Choreography States Across 3 Scenes (3 x 6.667s = 20s) */
  let heroY = 0.0;
  let heroScale = 1.0;
  let outlineAlpha = 0.0;
  let plateAlpha = 0.0;
  let expandGlobal = 1.0; /* 0 = locked inside "2027", >=1 = staging constellation outside outline */
  let useStagger = 0;     /* 0 = uniform stage, 1 = collect stagger, 2 = scatter stagger */
  let progForStagger = 0;
  let sweepX = -0.85;
  let sweepAlpha = 0.0;
  let pulseWave = 0.0;

  let ruleGrow = 0.0;
  let phraseReveal = 0.0;
  let phraseHide = 0.0;
  let phraseSheenX = -0.85;

  if (safeScene === 0) {
    /* SCENE 0 (0 - 6.67s): Outline "2027" muncul halus & partikel glitter berkumpul mengisi teks */
    outlineAlpha = k8Lerp(0.18, 0.92, k8EaseOutCubic(k8SubRange(safeProgress, 0.00, 0.34)));
    plateAlpha = k8EaseInOutCubic(k8SubRange(safeProgress, 0.56, 0.92));
    useStagger = 1;
    progForStagger = safeProgress;
    expandGlobal = 1 - k8EaseInOutCubic(k8SubRange(safeProgress, 0.06, 0.74));
    sweepX = k8Lerp(-0.62, 0.62, k8EaseInOutCubic(k8SubRange(safeProgress, 0.72, 1.00)));
    sweepAlpha = k8SmoothBell(k8SubRange(safeProgress, 0.72, 1.00)) * 0.55;
  } else if (safeScene === 1) {
    /* SCENE 1 (6.67 - 13.33s): "2027" naik, sapuan kilau melintas, "HAPPY NEW YEAR" muncul per huruf */
    const elevUp = k8EaseInOutCubic(k8SubRange(safeProgress, 0.00, 0.16));
    heroY = k8Lerp(0.0, -0.092, elevUp);
    heroScale = k8Lerp(1.0, 0.90, elevUp);

    outlineAlpha = 0.95;
    plateAlpha = 1.0;
    expandGlobal = 0.0;

    /* Primary luxury light sweep across "2027" */
    const s1 = k8SubRange(safeProgress, 0.18, 0.66);
    sweepX = k8Lerp(-0.62, 0.62, k8EaseInOutCubic(s1));
    sweepAlpha = k8SmoothBell(s1) * 0.92;

    ruleGrow = k8EaseOutQuart(k8SubRange(safeProgress, 0.16, 0.28));
    phraseReveal = k8SubRange(safeProgress, 0.22, 0.60);
    phraseSheenX = k8Lerp(-0.56, 0.56, k8EaseInOutCubic(k8SubRange(safeProgress, 0.56, 0.96)));
  } else {
    /* SCENE 2 (13.33 - 20.00s):
       0.00..0.24 : Glitter berdenyut harmonis + sapuan kilau
       0.24..0.38 : "HAPPY NEW YEAR" & garis pembatas menghilang tuntas
       0.39..0.52 : "2027" turun ke pusat (0.0)
       0.52..0.78 : Glitter berhamburan keluar ke konstelasi orbit
       0.78..0.99 : Berkumpul kembali presisi ke konstelasi awal (identik dengan t=0!) */
    const elevDown = k8EaseInOutCubic(k8SubRange(safeProgress, 0.39, 0.52));
    heroY = k8Lerp(-0.092, 0.0, elevDown);
    heroScale = k8Lerp(0.90, 1.0, elevDown);

    pulseWave = k8SmoothBell(k8SubRange(safeProgress, 0.02, 0.28));
    const s2 = k8SubRange(safeProgress, 0.04, 0.34);
    sweepX = k8Lerp(0.62, -0.62, k8EaseInOutCubic(s2));
    sweepAlpha = k8SmoothBell(s2) * 0.85;

    ruleGrow = 1 - k8EaseInOutCubic(k8SubRange(safeProgress, 0.26, 0.38));
    phraseReveal = 1.0;
    phraseHide = k8SubRange(safeProgress, 0.24, 0.35);
    phraseSheenX = k8Lerp(-0.56, 0.56, k8SubRange(safeProgress, 0.02, 0.24));

    plateAlpha = 1 - k8EaseInCubic(k8SubRange(safeProgress, 0.48, 0.62));
    useStagger = 2;
    progForStagger = safeProgress;

    /* Outline fades smoothly from 0.95 at scatter start back to exact t=0 level (0.18) by p=0.97 */
    const outFade = k8EaseInOutCubic(k8SubRange(safeProgress, 0.64, 0.97));
    outlineAlpha = k8Lerp(0.95, 0.18, outFade);
  }

  /* 3. Render Elevated Hero "2027" Group */
  ctx.save();
  ctx.translate(0, heroY);
  ctx.scale(heroScale, heroScale);

  /* 3A. Metallic Satin Plate Clipped Strictly Inside "2027" + Clipped Specular Light Sweep */
  if (plateAlpha > 0.005 || sweepAlpha > 0.005) {
    ctx.save();
    ctx.beginPath();
    for (let i = 0; i < K8_HERO_LAYOUT.items.length; i++) {
      const dig = K8_HERO_LAYOUT.items[i];
      for (let r = 0; r < dig.rings.length; r++) {
        const pts = dig.rings[r];
        ctx.moveTo(dig.x0 + pts[0][0] * K8_HERO_H, dig.y0 + pts[0][1] * K8_HERO_H);
        for (let k = 1; k < pts.length; k++) {
          ctx.lineTo(dig.x0 + pts[k][0] * K8_HERO_H, dig.y0 + pts[k][1] * K8_HERO_H);
        }
        ctx.closePath();
      }
    }
    ctx.clip('evenodd');

    if (plateAlpha > 0.005) {
      const baseGrad = ctx.createLinearGradient(0, -K8_HERO_H * 0.5, 0, K8_HERO_H * 0.5);
      baseGrad.addColorStop(0.0, 'rgba(38, 56, 98, 0.92)');
      baseGrad.addColorStop(0.5, 'rgba(26, 40, 74, 0.95)');
      baseGrad.addColorStop(1.0, 'rgba(18, 28, 56, 0.95)');
      ctx.save();
      ctx.globalAlpha *= plateAlpha;
      ctx.fillStyle = baseGrad;
      ctx.fillRect(-0.50, -0.16, 1.00, 0.32);
      ctx.restore();
    }

    if (sweepAlpha > 0.005) {
      const bandW = 0.22;
      const sheenGrad = ctx.createLinearGradient(sweepX - bandW, -0.15, sweepX + bandW, 0.15);
      sheenGrad.addColorStop(0.0, 'rgba(255, 255, 255, 0.0)');
      sheenGrad.addColorStop(0.35, 'rgba(145, 212, 255, 0.26)');
      sheenGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.62)');
      sheenGrad.addColorStop(0.65, 'rgba(145, 212, 255, 0.26)');
      sheenGrad.addColorStop(1.0, 'rgba(255, 255, 255, 0.0)');
      ctx.save();
      ctx.globalAlpha *= sweepAlpha;
      ctx.fillStyle = sheenGrad;
      ctx.fillRect(-0.55, -0.16, 1.10, 0.32);
      ctx.restore();
    }
    ctx.restore();
  }

  /* 3B. Non-Overlapping Honeycomb Glitter Facets (Zero Random Flicker, Periodic Shimmer) */
  for (let i = 0; i < K8_FACETS.length; i++) {
    const f = K8_FACETS[i];
    let localExp = expandGlobal;

    if (useStagger === 1) {
      /* Scene 0 inward collect along strictly non-crossing elliptical radial tracks */
      const collectU = k8EaseInOutCubic(k8SubRange(progForStagger, f.collectLag, f.collectLag + 0.42));
      localExp = 1 - collectU;
    } else if (useStagger === 2) {
      /* Scene 2 continuous scatter (0.52..0.78) -> calm re-gather back to exact start ring (0.78..0.99) */
      const sStart = 0.52 + f.scatterLag;
      const sPeak = 0.70 + f.scatterLag;
      const uBurst = k8EaseOutCubic(k8SubRange(progForStagger, sStart, sPeak));
      const uGather = k8EaseInOutCubic(k8SubRange(progForStagger, 0.78, 0.99));
      localExp = k8Lerp(uBurst * 1.15, 1.0, uGather);
    }

    const px = k8Lerp(f.tx, f.sx, localExp);
    const py = k8Lerp(f.ty, f.sy, localExp);

    /* Smooth periodic luxury twinkle (zero 1-frame flicker; identical at cycle=0 and cycle=1) */
    const baseTwinkle = 0.5 + 0.5 * Math.cos(cycle * K8_TAU * 5 + f.phase);
    const sweepDist = Math.abs(px - sweepX - py * 0.35);
    const sweepHit = sweepAlpha > 0.01 ? k8Clamp01(1 - sweepDist / 0.14) * sweepAlpha : 0;
    const pulseBoost = pulseWave * (0.45 + 0.55 * Math.cos(f.phase * 2));
    const highlight = k8Clamp01(0.28 + 0.42 * baseTwinkle + 0.85 * sweepHit + 0.45 * pulseBoost);

    const sizeMul = (1.0 - 0.18 * k8Clamp01(localExp)) * (0.85 + 0.25 * baseTwinkle + 0.35 * sweepHit);
    const facetAlpha = (0.68 + 0.32 * highlight) * (1.0 - 0.12 * k8Clamp01(localExp));

    k8DrawFacet(ctx, px, py, f.r * sizeMul, f.isStar, f.tone, highlight, facetAlpha);
  }

  /* 3C. Razor-Sharp Outer Metallic Vector Trim Around Each Numeral of "2027" */
  if (outlineAlpha > 0.005) {
    ctx.save();
    ctx.globalAlpha *= outlineAlpha;
    for (let i = 0; i < K8_HERO_LAYOUT.items.length; i++) {
      const dig = K8_HERO_LAYOUT.items[i];
      ctx.save();
      ctx.translate(dig.x0, dig.y0);
      ctx.scale(K8_HERO_H, K8_HERO_H);
      k8TraceRings(ctx, dig.rings);

      const rimGrad = ctx.createLinearGradient(0, 0, K8_DIGIT_META[dig.ch].w, 1);
      rimGrad.addColorStop(0.0, K8_PALETTE.silverBright);
      rimGrad.addColorStop(0.5, K8_PALETTE.iceLight);
      rimGrad.addColorStop(1.0, K8_PALETTE.silverMid);

      ctx.lineWidth = 0.014;
      ctx.lineJoin = 'round';
      ctx.strokeStyle = rimGrad;
      ctx.stroke();
      ctx.restore();
    }
    ctx.restore();
  }

  ctx.restore(); /* end elevated hero group */

  /* 4. Divider Rule & Letter-by-Letter "HAPPY NEW YEAR" (Strictly Disjoint Vertical Lanes) */
  if (ruleGrow > 0.005) {
    const ruleY = 0.088;
    const halfSpan = 0.38 * ruleGrow;
    ctx.beginPath();
    ctx.moveTo(-halfSpan, ruleY);
    ctx.lineTo(halfSpan, ruleY);
    ctx.lineWidth = 0.0022;
    ctx.strokeStyle = K8_PALETTE.iceLight;
    ctx.stroke();

    ctx.beginPath();
    k8TraceDiamond(ctx, 0, ruleY, 0.009 * ruleGrow);
    k8TraceDiamond(ctx, -halfSpan - 0.014 * ruleGrow, ruleY, 0.0055 * ruleGrow);
    k8TraceDiamond(ctx, halfSpan + 0.014 * ruleGrow, ruleY, 0.0055 * ruleGrow);
    ctx.fillStyle = K8_PALETTE.silverBright;
    ctx.fill();
  }

  k8DrawEditorialGreeting(ctx, 0.176, 0.056, phraseReveal, phraseHide, phraseSheenX);

  ctx.restore();
}

/* ==========================================================================
   KONSEP 7 — GLITCH YEAR SHIFT 2026->2027 (HAPPY NEW YEAR 2027)
   Theme: Happy New Year 2027 | Duration: 20s | Scenes: 4 | Aspect Ratio: 16:9
   Resolution: FHD / 2K / 4K (3840x2160) | Recommended Export Bitrate: 100 Mbps
   Style: Kinetic Typography — Precision Cyber Scanline Slice-Shift & RGB Split
   Pure Canvas 2D API — Zero Background Glow, Zero External Assets, Seamless Loop
   ========================================================================== */

const EXPORT_CONFIG = {
  width: 3840,
  height: 2160,
  aspectRatio: '16:9',
  fps: 60,
  duration: 20,
  bitrateMbps: 100,
  minBitrateMbps: 100,
  videoBitsPerSecond: 100000000
};

const K7_PALETTE = {
  bgTop: '#0B0D14',
  bgMid: '#121420',
  bgBot: '#090A10',
  gridMinor: 'rgba(159, 103, 255, 0.045)',
  gridMajor: 'rgba(159, 103, 255, 0.11)',
  frameStroke: 'rgba(159, 103, 255, 0.36)',
  bracket: '#FF2E93',
  violet: '#8B5CF6',
  violetBright: '#A678FF',
  magenta: '#FF2E93',
  cyan: '#2DE2FF',
  lavenderWhite: '#F4F0FF',
  textMuted: '#8883A4',
  surfaceBar: '#1A1C2C'
};

const K7_TAU = Math.PI * 2;
const K7_BAND_COUNT = 14;

/* Deterministic non-colliding row parameters across the 14 horizontal scanline bands */
const K7_BAND_ROWS = [
  { dir: -1, amp: 0.72, delay: 0.00, packetSeed: 0.18 },
  { dir: 1,  amp: 1.00, delay: 0.14, packetSeed: 0.62 },
  { dir: -1, amp: 0.56, delay: 0.06, packetSeed: 0.40 },
  { dir: 1,  amp: 0.88, delay: 0.22, packetSeed: 0.84 },
  { dir: -1, amp: 1.12, delay: 0.10, packetSeed: 0.28 },
  { dir: 1,  amp: 0.64, delay: 0.28, packetSeed: 0.70 },
  { dir: -1, amp: 0.94, delay: 0.18, packetSeed: 0.12 },
  { dir: 1,  amp: 1.08, delay: 0.04, packetSeed: 0.54 },
  { dir: -1, amp: 0.68, delay: 0.24, packetSeed: 0.90 },
  { dir: 1,  amp: 0.96, delay: 0.12, packetSeed: 0.34 },
  { dir: -1, amp: 0.82, delay: 0.20, packetSeed: 0.76 },
  { dir: 1,  amp: 1.04, delay: 0.08, packetSeed: 0.22 },
  { dir: -1, amp: 0.60, delay: 0.26, packetSeed: 0.58 },
  { dir: 1,  amp: 0.86, delay: 0.16, packetSeed: 0.44 }
];

function k7Clamp01(v) {
  return v < 0 ? 0 : (v > 1 ? 1 : v);
}

function k7Lerp(a, b, t) {
  return a + (b - a) * t;
}

function k7SubRange(p, s, e) {
  return k7Clamp01((p - s) / (e - s));
}

function k7EaseInOutCubic(t) {
  const u = k7Clamp01(t);
  return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2;
}

function k7EaseOutQuart(t) {
  const u = k7Clamp01(t);
  return 1 - Math.pow(1 - u, 4);
}

function k7EaseInCubic(t) {
  const u = k7Clamp01(t);
  return u * u * u;
}

function k7EaseOutCubic(t) {
  const u = k7Clamp01(t);
  return 1 - Math.pow(1 - u, 3);
}

/* Smooth bell curve over [0..1] returning 0 at both endpoints */
function k7SmoothBell(u) {
  const x = k7Clamp01(u);
  return Math.sin(x * Math.PI);
}

/* ---------- RAZOR-SHARP CYBER-GEOMETRIC GLYPHS IN [0..w] x [0..1] ---------- */
const K7_GLYPH_W = {
  '2': 0.66,
  '0': 0.66,
  '6': 0.66,
  '7': 0.66,
  'H': 0.66,
  'A': 0.68,
  'P': 0.64,
  'Y': 0.68,
  'N': 0.68,
  'E': 0.62,
  'W': 0.86,
  'R': 0.66
};

function k7TracePoly(ctx, pts) {
  ctx.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length; i++) {
    ctx.lineTo(pts[i][0], pts[i][1]);
  }
  ctx.closePath();
}

/* Builds deterministic clockwise/evenodd paths inside [0..w] x [0..1] */
function k7TraceGlyph(ctx, ch) {
  const w = K7_GLYPH_W[ch];
  const st = 0.168;
  const c = 0.115;
  const ci = 0.042;
  ctx.beginPath();

  if (ch === '0') {
    k7TracePoly(ctx, [
      [c, 0], [w - c, 0], [w, c], [w, 1 - c],
      [w - c, 1], [c, 1], [0, 1 - c], [0, c]
    ]);
    k7TracePoly(ctx, [
      [st + ci, st], [w - st - ci, st], [w - st, st + ci], [w - st, 1 - st - ci],
      [w - st - ci, 1 - st], [st + ci, 1 - st], [st, 1 - st - ci], [st, st + ci]
    ]);
  } else if (ch === '2') {
    const mTop = 0.42;
    const mBot = mTop + st;
    k7TracePoly(ctx, [
      [c, 0], [w - c, 0], [w, c], [w, mBot - c * 0.7], [w - c * 0.7, mBot],
      [st, mBot], [st, 1 - st], [w, 1 - st], [w, 1], [0, 1],
      [0, mTop + c * 0.7], [c * 0.7, mTop], [w - st, mTop], [w - st, st],
      [st, st], [st, 0.28], [0, 0.28], [0, c]
    ]);
  } else if (ch === '6') {
    const mTop = 0.43;
    const hTop = mTop + st;
    k7TracePoly(ctx, [
      [c, 0], [w - c, 0], [w, c], [w, 0.27], [w - st, 0.27], [w - st, st],
      [st, st], [st, mTop], [w - c * 0.7, mTop], [w, mTop + c * 0.7],
      [w, 1 - c], [w - c, 1], [c, 1], [0, 1 - c], [0, c]
    ]);
    k7TracePoly(ctx, [
      [st + ci, hTop], [w - st - ci, hTop], [w - st, hTop + ci], [w - st, 1 - st - ci],
      [w - st - ci, 1 - st], [st + ci, 1 - st], [st, 1 - st - ci], [st, hTop + ci]
    ]);
  } else if (ch === '7') {
    k7TracePoly(ctx, [
      [0, 0], [w, 0], [w, 0.19], [0.36, 1],
      [0.17, 1], [w - 0.19, st], [0.13, st], [0.13, 0.25], [0, 0.25]
    ]);
  } else if (ch === 'H') {
    k7TracePoly(ctx, [
      [0, 0], [st, 0], [st, 0.415], [w - st, 0.415], [w - st, 0], [w, 0],
      [w, 1], [w - st, 1], [w - st, 0.585], [st, 0.585], [st, 1], [0, 1]
    ]);
  } else if (ch === 'A') {
    k7TracePoly(ctx, [
      [c, 0], [w - c, 0], [w, c], [w, 1], [w - st, 1],
      [w - st, 0.68], [st, 0.68], [st, 1], [0, 1], [0, c]
    ]);
    k7TracePoly(ctx, [
      [st + ci, st], [w - st - ci, st], [w - st, st + ci],
      [w - st, 0.51], [st, 0.51], [st, st + ci]
    ]);
  } else if (ch === 'P') {
    k7TracePoly(ctx, [
      [0, 0], [w - c, 0], [w, c], [w, 0.58 - c * 0.65], [w - c * 0.65, 0.58],
      [st, 0.58], [st, 1], [0, 1]
    ]);
    k7TracePoly(ctx, [
      [st, st], [w - st - ci, st], [w - st, st + ci],
      [w - st, 0.412 - ci], [w - st - ci, 0.412], [st, 0.412]
    ]);
  } else if (ch === 'Y') {
    const xc = w * 0.5;
    const hs = st * 0.5;
    k7TracePoly(ctx, [
      [0, 0], [st + 0.02, 0], [xc, 0.42], [w - st - 0.02, 0], [w, 0],
      [w, 0.10], [xc + hs, 0.58], [xc + hs, 1], [xc - hs, 1], [xc - hs, 0.58], [0, 0.10]
    ]);
  } else if (ch === 'N') {
    k7TracePoly(ctx, [
      [0, 0], [st + 0.02, 0], [w - st, 0.68], [w - st, 0], [w, 0],
      [w, 1], [w - st - 0.02, 1], [st, 0.32], [st, 1], [0, 1]
    ]);
  } else if (ch === 'E') {
    k7TracePoly(ctx, [
      [0, 0], [w, 0], [w, st], [st, st], [st, 0.415], [w - 0.07, 0.415],
      [w - 0.07, 0.585], [st, 0.585], [st, 1 - st], [w, 1 - st], [w, 1], [0, 1]
    ]);
  } else if (ch === 'W') {
    const xc = w * 0.5;
    k7TracePoly(ctx, [
      [0, 0], [st, 0], [0.27, 0.72], [xc - st * 0.48, 0.18], [xc + st * 0.48, 0.18],
      [w - 0.27, 0.72], [w - st, 0], [w, 0], [w - 0.19, 1], [w - 0.34, 1],
      [xc, 0.46], [0.34, 1], [0.19, 1]
    ]);
  } else if (ch === 'R') {
    k7TracePoly(ctx, [
      [0, 0], [w - c, 0], [w, c], [w, 0.56 - c * 0.65], [w - c * 0.65, 0.56],
      [w * 0.62, 0.56], [w, 1], [w - st - 0.02, 1], [w * 0.40, 0.58],
      [st, 0.58], [st, 1], [0, 1]
    ]);
    k7TracePoly(ctx, [
      [st, st], [w - st - ci, st], [w - st, st + ci],
      [w - st, 0.395 - ci], [w - st - ci, 0.395], [st, 0.395]
    ]);
  }
}

/* Computes exact glyph positions so strings stay centered mathematically */
function k7LayoutWord(chars, glyphH, gapFactor, spaceFactor) {
  let totalW = 0;
  const items = [];
  for (let i = 0; i < chars.length; i++) {
    const ch = chars[i];
    if (ch === ' ') {
      totalW += spaceFactor * glyphH;
      continue;
    }
    const gw = K7_GLYPH_W[ch] * glyphH;
    items.push({ ch, x: totalW, w: gw, idx: items.length });
    totalW += gw;
    if (i < chars.length - 1 && chars[i + 1] !== ' ') {
      totalW += gapFactor * glyphH;
    }
  }
  for (let i = 0; i < items.length; i++) {
    items[i].x -= totalW * 0.5;
  }
  return { items, totalW };
}

/* Renders a full hero word ("2026" or "2027") at a horizontal displacement */
function k7DrawYearGlyphs(ctx, layout, yTop, glyphH, overrideColor, isHeroAccent, alphaScale) {
  if (alphaScale <= 0.005) return;
  ctx.save();
  ctx.globalAlpha *= alphaScale;
  for (let i = 0; i < layout.items.length; i++) {
    const it = layout.items[i];
    ctx.save();
    ctx.translate(it.x, yTop);
    ctx.scale(glyphH, glyphH);
    k7TraceGlyph(ctx, it.ch);
    if (overrideColor) {
      ctx.fillStyle = overrideColor;
    } else if (i === 3) {
      if (isHeroAccent === '2027') {
        const accentGrad = ctx.createLinearGradient(0, 0, K7_GLYPH_W[it.ch], 1);
        accentGrad.addColorStop(0.0, K7_PALETTE.violetBright);
        accentGrad.addColorStop(0.55, K7_PALETTE.violet);
        accentGrad.addColorStop(1.0, K7_PALETTE.magenta);
        ctx.fillStyle = accentGrad;
      } else {
        ctx.fillStyle = K7_PALETTE.violetBright;
      }
    } else {
      ctx.fillStyle = K7_PALETTE.lavenderWhite;
    }
    ctx.fill('evenodd');
    ctx.restore();
  }
  ctx.restore();
}

/* Draws crisp charcoal architectural canvas, technical grid & perimeter HUD rails */
function k7DrawEnvironment(ctx, width, height, U, loopT, duration, safeScene, safeProgress) {
  const halfW = (width * 0.5) / U;
  const halfH = (height * 0.5) / U;
  const cycle = loopT / duration;

  /* 1. Clean Charcoal Background (NO background glow) */
  const bgGrad = ctx.createLinearGradient(0, -halfH, 0, halfH);
  bgGrad.addColorStop(0.0, K7_PALETTE.bgTop);
  bgGrad.addColorStop(0.5, K7_PALETTE.bgMid);
  bgGrad.addColorStop(1.0, K7_PALETTE.bgBot);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(-halfW, -halfH, halfW * 2, halfH * 2);

  /* 2. Crisp Precision Micro-Grid */
  const stepMinor = 0.08;
  const stepMajor = 0.24;
  ctx.lineWidth = 0.0012;
  ctx.strokeStyle = K7_PALETTE.gridMinor;
  ctx.beginPath();
  for (let gx = -0.80; gx <= 0.8001; gx += stepMinor) {
    ctx.moveTo(gx, -0.43);
    ctx.lineTo(gx, 0.43);
  }
  for (let gy = -0.40; gy <= 0.4001; gy += stepMinor) {
    ctx.moveTo(-0.82, gy);
    ctx.lineTo(0.82, gy);
  }
  ctx.stroke();

  ctx.lineWidth = 0.0016;
  ctx.strokeStyle = K7_PALETTE.gridMajor;
  ctx.beginPath();
  for (let gx = -0.72; gx <= 0.7201; gx += stepMajor) {
    ctx.moveTo(gx, -0.43);
    ctx.lineTo(gx, 0.43);
  }
  for (let gy = -0.24; gy <= 0.2401; gy += stepMajor) {
    ctx.moveTo(-0.82, gy);
    ctx.lineTo(0.82, gy);
  }
  ctx.stroke();

  /* 3. Outer Technical Margin Border & Corner Registration Brackets */
  const fx = 0.805;
  const fy = 0.425;
  ctx.lineWidth = 0.0022;
  ctx.strokeStyle = K7_PALETTE.frameStroke;
  ctx.strokeRect(-fx, -fy, fx * 2, fy * 2);

  const brk = 0.026;
  const bOff = 0.010;
  ctx.lineWidth = 0.0034;
  ctx.strokeStyle = K7_PALETTE.magenta;
  ctx.beginPath();
  const signs = [[-1, -1], [1, -1], [1, 1], [-1, 1]];
  for (let i = 0; i < 4; i++) {
    const sx = signs[i][0];
    const sy = signs[i][1];
    const cx = sx * (fx - bOff);
    const cy = sy * (fy - bOff);
    ctx.moveTo(cx - sx * brk, cy);
    ctx.lineTo(cx, cy);
    ctx.lineTo(cx, cy - sy * brk);
  }
  ctx.stroke();

  /* 4. Top Telemetry Header Rail (strictly outside center stage: y = -0.382) */
  ctx.save();
  ctx.scale(1 / U, 1 / U);
  ctx.font = '700 ' + (0.017 * U).toFixed(2) + 'px "Consolas", "Courier New", monospace';
  ctx.textBaseline = 'middle';
  ctx.textAlign = 'left';
  ctx.fillStyle = K7_PALETTE.textMuted;
  ctx.fillText('CHRONO.SHIFT // 2026 -> 2027', -0.77 * U, -0.382 * U);
  ctx.restore();

  /* Scene Indicator Dots (4 non-overlapping telemetry nodes at top-right rail) */
  for (let s = 0; s < 4; s++) {
    const nx = 0.645 + s * 0.036;
    const ny = -0.382;
    const active = s === safeScene;
    ctx.fillStyle = active ? K7_PALETTE.magenta : K7_PALETTE.surfaceBar;
    ctx.fillRect(nx - 0.010, ny - 0.0045, 0.020, 0.009);
    if (active) {
      ctx.fillStyle = K7_PALETTE.cyan;
      ctx.fillRect(nx - 0.010, ny - 0.0045, 0.020 * safeProgress, 0.009);
    }
  }

  /* 5. Bottom-Left Equalizer Phase Bars (100% periodic at cycle=0 & cycle=1, y = +0.382) */
  const barCount = 12;
  for (let i = 0; i < barCount; i++) {
    const bx = -0.77 + i * 0.018;
    const wave = 0.5 + 0.5 * Math.sin(K7_TAU * cycle * 4 - i * 0.52);
    const bh = 0.007 + wave * 0.016;
    ctx.fillStyle = i % 3 === 0 ? K7_PALETTE.magenta : (i % 3 === 1 ? K7_PALETTE.violet : K7_PALETTE.cyan);
    ctx.fillRect(bx, 0.382 - bh * 0.5, 0.0085, bh);
  }

  /* 6. Bottom-Right Status Label (smooth crossfade back to initial state at Scene 3 end) */
  const labels = [
    'SYNC_STATE : YEAR_2026_LOCKED',
    'SHIFT_MODE : SCANLINE_SLICE_26',
    'BUILD_STATE : MATRIX_LOCK_2027',
    'GREET_MODE : HAPPY_NEW_YEAR'
  ];
  let activeIdx = safeScene;
  let labelA = 1;
  if (safeScene === 3 && safeProgress > 0.72) {
    /* Seamless return to Scene 0 status text before t = 20s */
    const backU = k7SubRange(safeProgress, 0.72, 0.94);
    if (backU < 0.5) {
      labelA = 1 - backU * 2;
    } else {
      activeIdx = 0;
      labelA = (backU - 0.5) * 2;
    }
  } else if (safeProgress < 0.08 && safeScene !== 0) {
    labelA = safeProgress / 0.08;
  } else if (safeProgress > 0.94 && safeScene !== 3) {
    labelA = (1 - safeProgress) / 0.06;
  }

  ctx.save();
  ctx.globalAlpha = k7Clamp01(labelA) * 0.92;
  ctx.scale(1 / U, 1 / U);
  ctx.font = '700 ' + (0.017 * U).toFixed(2) + 'px "Consolas", "Courier New", monospace';
  ctx.textBaseline = 'middle';
  ctx.textAlign = 'right';
  ctx.fillStyle = safeScene === 2 ? K7_PALETTE.cyan : K7_PALETTE.textMuted;
  ctx.fillText(labels[activeIdx], 0.77 * U, 0.382 * U);
  ctx.restore();
}

/* Snaps a local Y coordinate strictly to integer screen pixels to prevent clip seam hairlines */
function k7SnapY(localY, originPx, scalePx) {
  return (Math.round(originPx + localY * scalePx) - originPx) / scalePx;
}

/* Draws cleanly separated horizontal packet fragments inside band b's lane */
function k7DrawBandPacketBars(ctx, bandCenterY, bandH, bandRow, dxOffset, packetMix, shiftPolarity) {
  if (packetMix <= 0.01) return;
  const barH = bandH * 0.44 * Math.min(1, packetMix * 1.15);
  const yBar = bandCenterY - barH * 0.5;
  const spread = 0.27 + bandRow.packetSeed * 0.09;

  /* 3 strictly separated horizontal slots inside band lane: left, center, right */
  const leftW = (0.068 + bandRow.packetSeed * 0.045) * packetMix;
  const midW = (0.135 + (1 - bandRow.packetSeed) * 0.055) * packetMix;
  const rightW = (0.062 + bandRow.packetSeed * 0.045) * packetMix;

  const cx = dxOffset * 0.72;
  const lx = cx - spread - leftW * 0.5;
  const mx = cx - midW * 0.5;
  const rx = cx + spread - rightW * 0.5;

  ctx.save();
  ctx.globalAlpha *= k7Clamp01(packetMix);

  ctx.fillStyle = shiftPolarity > 0 ? K7_PALETTE.cyan : K7_PALETTE.violetBright;
  ctx.fillRect(lx, yBar, leftW, barH);

  ctx.fillStyle = K7_PALETTE.lavenderWhite;
  ctx.fillRect(mx, yBar, midW, barH);

  ctx.fillStyle = K7_PALETTE.magenta;
  ctx.fillRect(rx, yBar, rightW, barH);
  ctx.restore();
}

/* Renders both hero year numerals and/or digital packets cleanly per non-overlapping scanline band */
function k7DrawSlicedYearComposite(ctx, layout26, layout27, glyphH, bandStates, originPx, scalePx) {
  let maxSlice = 0;
  let maxChroma = 0;
  let maxPack = 0;
  let minA26 = 1;
  let maxA26 = 0;
  let minA27 = 1;
  let maxA27 = 0;

  for (let b = 0; b < K7_BAND_COUNT; b++) {
    const st = bandStates[b];
    if (Math.abs(st.dx) > maxSlice) maxSlice = Math.abs(st.dx);
    if (Math.abs(st.chroma) > maxChroma) maxChroma = Math.abs(st.chroma);
    if (st.pack > maxPack) maxPack = st.pack;
    if (st.a26 < minA26) minA26 = st.a26;
    if (st.a26 > maxA26) maxA26 = st.a26;
    if (st.a27 < minA27) minA27 = st.a27;
    if (st.a27 > maxA27) maxA27 = st.a27;
  }

  const yTop = -glyphH * 0.5;
  const bandSpanH = glyphH + 0.016;
  const bandTopEdge = -bandSpanH * 0.5;
  const bandH = bandSpanH / K7_BAND_COUNT;

  /* Crisp unclipped single-pass render when slices are locked uniformly across all bands */
  if (
    maxSlice < 0.0002 &&
    maxChroma < 0.0002 &&
    maxPack < 0.005 &&
    Math.abs(maxA26 - minA26) < 0.001 &&
    Math.abs(maxA27 - minA27) < 0.001
  ) {
    if (maxA26 > 0.005) {
      k7DrawYearGlyphs(ctx, layout26, yTop, glyphH, null, '2026', maxA26);
    }
    if (maxA27 > 0.005) {
      k7DrawYearGlyphs(ctx, layout27, yTop, glyphH, null, '2027', maxA27);
    }
    return;
  }

  for (let b = 0; b < K7_BAND_COUNT; b++) {
    const st = bandStates[b];
    if (st.a26 <= 0.005 && st.a27 <= 0.005 && st.pack <= 0.005) continue;

    const bY0 = k7SnapY(bandTopEdge + b * bandH, originPx, scalePx);
    const bY1 = k7SnapY(bandTopEdge + (b + 1) * bandH, originPx, scalePx);
    const snapH = bY1 - bY0;
    if (snapH <= 0) continue;
    const bCenterY = bY0 + snapH * 0.5;

    ctx.save();
    ctx.beginPath();
    ctx.rect(-0.78, bY0, 1.56, snapH);
    ctx.clip();

    if (st.a26 > 0.005) {
      if (Math.abs(st.chroma) > 0.0002) {
        ctx.save();
        ctx.translate(st.dx - st.chroma, 0);
        k7DrawYearGlyphs(ctx, layout26, yTop, glyphH, K7_PALETTE.cyan, false, st.a26 * 0.78);
        ctx.restore();

        ctx.save();
        ctx.translate(st.dx + st.chroma, 0);
        k7DrawYearGlyphs(ctx, layout26, yTop, glyphH, K7_PALETTE.magenta, false, st.a26 * 0.78);
        ctx.restore();
      }
      ctx.save();
      ctx.translate(st.dx, 0);
      k7DrawYearGlyphs(ctx, layout26, yTop, glyphH, null, '2026', st.a26);
      ctx.restore();
    }

    if (st.a27 > 0.005) {
      if (Math.abs(st.chroma) > 0.0002) {
        ctx.save();
        ctx.translate(st.dx - st.chroma, 0);
        k7DrawYearGlyphs(ctx, layout27, yTop, glyphH, K7_PALETTE.cyan, false, st.a27 * 0.78);
        ctx.restore();

        ctx.save();
        ctx.translate(st.dx + st.chroma, 0);
        k7DrawYearGlyphs(ctx, layout27, yTop, glyphH, K7_PALETTE.magenta, false, st.a27 * 0.78);
        ctx.restore();
      }
      ctx.save();
      ctx.translate(st.dx, 0);
      k7DrawYearGlyphs(ctx, layout27, yTop, glyphH, null, '2027', st.a27);
      ctx.restore();
    }

    if (st.pack > 0.005) {
      k7DrawBandPacketBars(ctx, bCenterY, bandH, K7_BAND_ROWS[b], st.dx, st.pack, K7_BAND_ROWS[b].dir);
    }

    ctx.restore();
  }
}

/* Draws sleek calibration framing brackets strictly outside active hero slices & packets */
function k7DrawHeroFrameAccents(ctx, glyphH, wordW, maxSpreadX, scanRelY, scanAlpha, lockFlash) {
  const halfSpanX = Math.min(0.75, wordW * 0.5 + 0.055 + maxSpreadX);
  const halfSpanY = glyphH * 0.5 + 0.034;

  /* Subtle clean corner calibration brackets around hero numerals */
  const bLen = 0.022;
  ctx.lineWidth = 0.0028;
  ctx.strokeStyle = lockFlash > 0.01 ? K7_PALETTE.cyan : 'rgba(139, 92, 246, 0.55)';
  ctx.beginPath();
  const corners = [[-1, -1], [1, -1], [1, 1], [-1, 1]];
  for (let i = 0; i < 4; i++) {
    const sx = corners[i][0];
    const sy = corners[i][1];
    const px = sx * (halfSpanX + lockFlash * 0.018);
    const py = sy * (halfSpanY + lockFlash * 0.010);
    ctx.moveTo(px - sx * bLen, py);
    ctx.lineTo(px, py);
    ctx.lineTo(px, py - sy * bLen);
  }
  ctx.stroke();

  /* Smooth horizontal laser scanline edge ticks (draws outside numerals + hairline across band) */
  if (scanAlpha > 0.01) {
    const sy = scanRelY;
    ctx.save();
    ctx.globalAlpha *= scanAlpha;

    ctx.lineWidth = 0.0018;
    ctx.strokeStyle = K7_PALETTE.cyan;
    ctx.beginPath();
    ctx.moveTo(-halfSpanX, sy);
    ctx.lineTo(halfSpanX, sy);
    ctx.stroke();

    ctx.fillStyle = K7_PALETTE.magenta;
    ctx.fillRect(-halfSpanX - 0.024, sy - 0.004, 0.014, 0.008);
    ctx.fillRect(halfSpanX + 0.010, sy - 0.004, 0.014, 0.008);
    ctx.restore();
  }
}

/* Draws "HAPPY NEW YEAR" with clean staggered scanline unlock and controlled periodic wave glitch */
function k7DrawGreetingPhrase(ctx, layout, yCenter, glyphH, revealP, glitchWaveU, hideP, originPx, scalePx) {
  if (revealP <= 0.005 || hideP >= 0.995) return;

  const yTop = yCenter - glyphH * 0.5;
  const bandCount = 6;
  const bandH = (glyphH + 0.008) / bandCount;
  const bandTop0 = yTop - 0.004;

  const envWave = k7SmoothBell(glitchWaveU);
  const envHide = k7EaseInCubic(hideP);

  /* Crisp unclipped single pass whenever all greeting bands are fully settled */
  if (revealP >= 0.999 && hideP <= 0.001 && envWave < 0.002) {
    for (let i = 0; i < layout.items.length; i++) {
      const it = layout.items[i];
      ctx.save();
      ctx.translate(it.x, yTop);
      ctx.scale(glyphH, glyphH);
      k7TraceGlyph(ctx, it.ch);
      ctx.fillStyle = (i >= 5 && i <= 7) ? K7_PALETTE.violetBright : K7_PALETTE.lavenderWhite;
      ctx.fill('evenodd');
      ctx.restore();
    }
    return;
  }

  for (let b = 0; b < bandCount; b++) {
    const bY0 = k7SnapY(bandTop0 + b * bandH, originPx, scalePx);
    const bY1 = k7SnapY(bandTop0 + (b + 1) * bandH, originPx, scalePx);
    const snapH = bY1 - bY0;
    if (snapH <= 0) continue;
    const dir = (b % 2 === 0 ? -1 : 1);

    /* Controlled staggered reveal slide */
    const rStag = b * 0.065;
    const rU = k7EaseOutQuart(k7SubRange(revealP, rStag, Math.min(1, rStag + 0.54)));
    const revealDx = (1 - rU) * dir * 0.065;
    const revealAlpha = k7Clamp01(rU * 1.45);

    /* Periodic clean harmonic glitch wave across bands during Scene 3 showcase */
    const wavePhase = b * 1.15 - glitchWaveU * K7_TAU * 2.0;
    const waveDx = envWave * Math.sin(wavePhase) * 0.014;
    const waveChroma = envWave * (0.009 + 0.004 * Math.abs(Math.cos(wavePhase)));

    /* Clean slice retraction before hero numeral descends */
    const hStag = (bandCount - 1 - b) * 0.05;
    const hU = k7EaseInCubic(k7SubRange(envHide, hStag, Math.min(1, hStag + 0.68)));
    const hideDx = hU * dir * 0.095;
    const hideAlpha = 1 - hU;

    const totalDx = revealDx + waveDx + hideDx;
    const totalChroma = (1 - rU) * 0.012 + waveChroma + hU * 0.014;
    const bandAlpha = revealAlpha * hideAlpha;
    if (bandAlpha <= 0.005) continue;

    ctx.save();
    ctx.beginPath();
    ctx.rect(-0.78, bY0, 1.56, snapH);
    ctx.clip();
    ctx.globalAlpha *= bandAlpha;

    if (totalChroma > 0.0003) {
      ctx.save();
      ctx.translate(totalDx - totalChroma, 0);
      k7DrawYearGlyphs(ctx, layout, yTop, glyphH, K7_PALETTE.cyan, false, 0.72);
      ctx.restore();

      ctx.save();
      ctx.translate(totalDx + totalChroma, 0);
      k7DrawYearGlyphs(ctx, layout, yTop, glyphH, K7_PALETTE.magenta, false, 0.72);
      ctx.restore();
    }

    ctx.save();
    ctx.translate(totalDx, 0);
    for (let i = 0; i < layout.items.length; i++) {
      const it = layout.items[i];
      ctx.save();
      ctx.translate(it.x, yTop);
      ctx.scale(glyphH, glyphH);
      k7TraceGlyph(ctx, it.ch);
      /* Subtle word distinction: "HAPPY" & "YEAR" bright white, "NEW" luminous violet */
      ctx.fillStyle = (i >= 5 && i <= 7) ? K7_PALETTE.violetBright : K7_PALETTE.lavenderWhite;
      ctx.fill('evenodd');
      ctx.restore();
    }
    ctx.restore();

    ctx.restore();
  }
}

/* ==========================================================================
   MANDATORY MOTION STUDIO ENTRY POINT
   ========================================================================== */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const safeLoopT = ((loopT % duration) + duration) % duration;
  const safeScene = Math.max(0, Math.min(sceneCount - 1, Math.floor(safeLoopT / sceneDuration)));
  const safeProgress = (safeLoopT % sceneDuration) / sceneDuration;

  const U = Math.min(height, width * (9 / 16));

  ctx.save();
  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(U, U);

  /* 1. Background Charcoal, Grid & Non-Colliding Perimeter Telemetry */
  k7DrawEnvironment(ctx, width, height, U, safeLoopT, duration, safeScene, safeProgress);

  /* 2. Compute Coordinated Choreography States Across All 4 Scenes */
  const digHBase = 0.275;
  const layout2026 = k7LayoutWord(['2', '0', '2', '6'], digHBase, 0.16, 0.5);
  const layout2027 = k7LayoutWord(['2', '0', '2', '7'], digHBase, 0.16, 0.5);

  let heroY = 0.0;
  let heroScale = 1.0;
  let scanRelY = 0.0;
  let scanAlpha = 0.0;
  let lockFlash = 0.0;
  let maxSliceX = 0.0;
  let maxPackEnv = 0.0;
  let use2027Layout = false;

  const bandStates = new Array(K7_BAND_COUNT);
  for (let b = 0; b < K7_BAND_COUNT; b++) {
    bandStates[b] = { dx: 0, chroma: 0, a26: 0, a27: 0, pack: 0 };
  }

  /* Staging lane offsets for Scene 1->2 digital packet matrix handoff */
  const stageOffset = (b) => {
    const row = K7_BAND_ROWS[b];
    return row.dir * (0.075 + row.amp * 0.135);
  };

  if (safeScene === 0) {
    /* SCENE 0 (0-5s): "2026" stabil + getaran micro-scanline halus & terkendali */
    const sweep1 = k7SubRange(safeProgress, 0.12, 0.48);
    const sweep2 = k7SubRange(safeProgress, 0.54, 0.88);
    const activeSweep = sweep1 > 0 && sweep1 < 1 ? sweep1 : sweep2;
    const sweepEnv = sweep1 > 0 && sweep1 < 1 ? k7SmoothBell(sweep1) : k7SmoothBell(sweep2) * 1.2;

    scanRelY = k7Lerp(-0.18, 0.18, k7EaseInOutCubic(activeSweep));
    scanAlpha = k7Clamp01(sweepEnv * 0.9);

    for (let b = 0; b < K7_BAND_COUNT; b++) {
      const bandRelY = -0.14 + (b + 0.5) / K7_BAND_COUNT * 0.28;
      const dist = Math.abs(bandRelY - scanRelY);
      const localFocus = k7Clamp01(1 - dist / 0.068);
      const wave = Math.sin(b * 1.7 + activeSweep * K7_TAU * 2.5);
      bandStates[b].dx = wave * localFocus * sweepEnv * 0.011;
      bandStates[b].chroma = Math.abs(localFocus) * sweepEnv * 0.0085;
      bandStates[b].a26 = 1.0;
    }
  } else if (safeScene === 1) {
    /* SCENE 1 (5-10s): Irisan horizontal bergeser keluar -> terurai jadi derau paket digital */
    scanRelY = k7Lerp(-0.18, 0.18, k7EaseInOutCubic(k7SubRange(safeProgress, 0.05, 0.65)));
    scanAlpha = k7SmoothBell(k7SubRange(safeProgress, 0.05, 0.75)) * 0.75;

    for (let b = 0; b < K7_BAND_COUNT; b++) {
      const row = K7_BAND_ROWS[b];
      const uSlice = k7EaseInOutCubic(k7SubRange(safeProgress, row.delay * 0.55, 0.56 + row.delay * 0.35));
      const uStage = k7EaseInOutCubic(k7SubRange(safeProgress, 0.54, 0.96));
      const targetDx = stageOffset(b);

      bandStates[b].dx = k7Lerp(0, targetDx, k7Clamp01(uSlice * 0.78 + uStage * 0.22));
      bandStates[b].chroma = k7SmoothBell(k7SubRange(safeProgress, row.delay * 0.55, 0.58)) * 0.017;
      bandStates[b].a26 = 1 - k7EaseInCubic(k7SubRange(safeProgress, 0.36 + row.delay * 0.22, 0.56 + row.delay * 0.22));
      bandStates[b].pack = k7EaseOutQuart(k7SubRange(safeProgress, 0.52 + row.delay * 0.22, 0.72 + row.delay * 0.22));
    }
  } else if (safeScene === 2) {
    /* SCENE 2 (10-15s): Serpihan digital terkunci kembali menjadi "2027" yang solid */
    use2027Layout = true;
    for (let b = 0; b < K7_BAND_COUNT; b++) {
      const row = K7_BAND_ROWS[b];
      const stag = row.delay * 0.48;
      const uLock = k7EaseOutQuart(k7SubRange(safeProgress, stag + 0.10, stag + 0.56));

      bandStates[b].dx = k7Lerp(stageOffset(b), 0, uLock);
      bandStates[b].chroma = k7SmoothBell(k7SubRange(safeProgress, stag + 0.14, stag + 0.56)) * 0.016;
      bandStates[b].pack = 1 - k7EaseInCubic(k7SubRange(safeProgress, stag + 0.04, stag + 0.22));
      bandStates[b].a27 = k7EaseOutCubic(k7SubRange(safeProgress, stag + 0.14, stag + 0.28));
    }

    lockFlash = k7SmoothBell(k7SubRange(safeProgress, 0.58, 0.78)) * 0.85;
    scanRelY = k7Lerp(0.18, -0.18, k7EaseInOutCubic(k7SubRange(safeProgress, 0.60, 0.90)));
    scanAlpha = k7SmoothBell(k7SubRange(safeProgress, 0.60, 0.90)) * 0.65;

    /* Subtle telemetry confirmation caption cleanly above hero & gone by 0.94 */
    const badgeU = k7SmoothBell(k7SubRange(safeProgress, 0.58, 0.94));
    if (badgeU > 0.02) {
      ctx.save();
      ctx.globalAlpha = badgeU * 0.88;
      ctx.scale(1 / U, 1 / U);
      ctx.font = '700 ' + (0.019 * U).toFixed(2) + 'px "Consolas", "Courier New", monospace';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = K7_PALETTE.cyan;
      ctx.fillText('SYSTEM_SYNC // TARGET_YEAR_2027', 0, -0.255 * U);
      ctx.restore();
    }
  } else if (safeScene === 3) {
    /* SCENE 3 (15-20s):
       0.00..0.14 : "2027" naik mulus ke posisi atas (-0.095)
       0.15..0.67 : Garis pembatas (+0.082) & "HAPPY NEW YEAR" (+0.172) tampil + glitch berkala,
                    lalu KEDUANYA hilang tuntas sebelum 0.67!
       0.68..0.80 : "2027" turun kembali ke pusat (0.0) melewati ruang kosong
       0.76..0.985: Morph scanline mulus "2027" -> paket digital -> "2026" tepat terkunci di t=20s */
    const elevUp = k7EaseInOutCubic(k7SubRange(safeProgress, 0.00, 0.14));
    const elevDown = k7EaseInOutCubic(k7SubRange(safeProgress, 0.68, 0.80));
    const lift = elevUp * (1 - elevDown);

    heroY = k7Lerp(0.0, -0.095, lift);
    heroScale = k7Lerp(1.0, 0.92, lift);
    use2027Layout = safeProgress < 0.89;

    /* Subtle synchronized periodic glitch accent on "2027" while elevated */
    const phraseGlitchU = k7SubRange(safeProgress, 0.36, 0.56);
    const phraseGlitchEnv = k7SmoothBell(phraseGlitchU);

    /* Reverse morph window: 0.76..0.985 back to crisp locked "2026" at t=20s */
    const morphOutU = k7EaseInOutCubic(k7SubRange(safeProgress, 0.76, 0.88));
    const morphInU = k7EaseOutQuart(k7SubRange(safeProgress, 0.88, 0.985));

    const bandA27 = 1 - k7EaseInCubic(k7SubRange(safeProgress, 0.78, 0.845));
    const bandPack = k7SubRange(safeProgress, 0.84, 0.885) < 1
      ? k7EaseOutCubic(k7SubRange(safeProgress, 0.84, 0.885))
      : 1 - k7EaseInCubic(k7SubRange(safeProgress, 0.885, 0.925));
    const bandA26 = k7EaseOutCubic(k7SubRange(safeProgress, 0.92, 0.98));

    for (let b = 0; b < K7_BAND_COUNT; b++) {
      const returnDx = safeProgress < 0.88
        ? k7Lerp(0, stageOffset(b) * 0.72, morphOutU)
        : k7Lerp(stageOffset(b) * 0.72, 0, morphInU);

      const waveDx = phraseGlitchEnv * Math.sin(b * 1.4 - phraseGlitchU * K7_TAU * 2) * 0.011;
      const waveChroma = phraseGlitchEnv * 0.008;
      const morphChroma = k7SmoothBell(k7SubRange(safeProgress, 0.76, 0.985)) * 0.016;

      bandStates[b].dx = returnDx + waveDx;
      bandStates[b].chroma = waveChroma + morphChroma;
      bandStates[b].a27 = bandA27;
      bandStates[b].pack = bandPack;
      bandStates[b].a26 = bandA26;
    }

    /* Divider Bar at y = +0.082 (draws 0.15..0.24, vanishes completely by 0.67 ahead of descent!) */
    let ruleGrow = 0;
    if (safeProgress < 0.50) {
      ruleGrow = k7EaseOutQuart(k7SubRange(safeProgress, 0.15, 0.24));
    } else {
      ruleGrow = 1 - k7EaseInOutCubic(k7SubRange(safeProgress, 0.59, 0.67));
    }

    if (ruleGrow > 0.005) {
      const ruleY = 0.082;
      const halfSpan = 0.39 * ruleGrow;
      ctx.beginPath();
      ctx.moveTo(-halfSpan, ruleY);
      ctx.lineTo(halfSpan, ruleY);
      ctx.lineWidth = 0.0032;
      ctx.strokeStyle = K7_PALETTE.violet;
      ctx.stroke();

      const tok = 0.011 * ruleGrow;
      ctx.fillStyle = K7_PALETTE.magenta;
      ctx.fillRect(-halfSpan - tok * 2.1, ruleY - tok * 0.5, tok, tok);
      ctx.fillStyle = K7_PALETTE.cyan;
      ctx.fillRect(halfSpan + tok * 1.1, ruleY - tok * 0.5, tok, tok);
    }

    /* "HAPPY NEW YEAR" at y = +0.172 (completely gone by 0.66) */
    const phraseReveal = k7SubRange(safeProgress, 0.16, 0.25);
    const phraseHide = k7SubRange(safeProgress, 0.58, 0.66);
    const greetingLayout = k7LayoutWord(
      ['H', 'A', 'P', 'P', 'Y', ' ', 'N', 'E', 'W', ' ', 'Y', 'E', 'A', 'R'],
      0.064,
      0.22,
      0.56
    );
    k7DrawGreetingPhrase(ctx, greetingLayout, 0.172, 0.064, phraseReveal, phraseGlitchU, phraseHide, height * 0.5, U);
  }

  for (let b = 0; b < K7_BAND_COUNT; b++) {
    if (Math.abs(bandStates[b].dx) > maxSliceX) maxSliceX = Math.abs(bandStates[b].dx);
    if (bandStates[b].pack > maxPackEnv) maxPackEnv = bandStates[b].pack;
  }

  /* 3. Render Hero Numerals ("2026" and/or "2027") inside Clean Hero Transform */
  ctx.save();
  ctx.translate(0, heroY);
  ctx.scale(heroScale, heroScale);

  const curLayout = use2027Layout ? layout2027 : layout2026;
  const maxSpreadX = Math.max(maxSliceX * 1.05, maxPackEnv * 0.24);
  k7DrawHeroFrameAccents(ctx, digHBase, curLayout.totalW, maxSpreadX, scanRelY, scanAlpha, lockFlash);
  k7DrawSlicedYearComposite(ctx, layout2026, layout2027, digHBase, bandStates, height * 0.5 + heroY * U, U * heroScale);

  ctx.restore();
  ctx.restore();
}

/* ==========================================================================
   KONSEP 6 — BAUHAUS SHAPE ASSEMBLY (HAPPY NEW YEAR 2027)
   Theme: Happy New Year 2027 | Duration: 20s | Scenes: 4 | Aspect Ratio: 16:9
   Resolution: FHD / 2K / 4K (3840x2160) | Recommended Export Bitrate: 100 Mbps
   Style: Kinetic Typography — Bauhaus Modular Grid & Non-Colliding Primitives
   Pure Canvas 2D API — Zero Background Glow, Zero External Assets, Seamless Loop
   ========================================================================== */

const EXPORT_CONFIG = {
