const K6_PALETTE = {
  ivoryTop: '#F8F4EA',
  ivoryBot: '#EEE8D8',
  red: '#D93829',
  blue: '#1C4EB8',
  yellow: '#F0B400',
  black: '#181818',
  gridLine: 'rgba(24, 24, 24, 0.095)',
  axisLine: 'rgba(24, 24, 24, 0.34)',
  inkMuted: '#4A463F'
};

const K6_TAU = Math.PI * 2;

function k6Clamp01(v) {
  return v < 0 ? 0 : (v > 1 ? 1 : v);
}

function k6Lerp(a, b, t) {
  return a + (b - a) * t;
}

function k6SubRange(p, s, e) {
  return k6Clamp01((p - s) / (e - s));
}

function k6EaseOutCubic(t) {
  const u = k6Clamp01(t);
  return 1 - Math.pow(1 - u, 3);
}

function k6EaseInCubic(t) {
  const u = k6Clamp01(t);
  return u * u * u;
}

function k6EaseInOutCubic(t) {
  const u = k6Clamp01(t);
  return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2;
}

function k6EaseOutQuart(t) {
  const u = k6Clamp01(t);
  return 1 - Math.pow(1 - u, 4);
}

/* Strictly inward mechanical lock settle (1.0 -> 0.955 -> 1.0), prevents neighbor overlap */
function k6LockInwardPulse(u) {
  if (u <= 0 || u >= 1) return 1;
  return 1 - 0.045 * Math.sin(u * Math.PI);
}

/* ---------- COLLISION-FREE BAUHAUS "2027" PRIMITIVES IN [0..1] x [0..1.5] ---------- */
