];

function k6TracePieceLocal(ctx, piece, cellW, cellH) {
  const sx = cellW;
  const sy = cellH / 1.5;
  const cx = piece.cent[0] * sx;
  const cy = piece.cent[1] * sy;

  ctx.beginPath();
  if (piece.kind === 'rect') {
    ctx.rect(piece.x * sx - cx, piece.y * sy - cy, piece.w * sx, piece.h * sy);
  } else if (piece.kind === 'poly') {
    const p0 = piece.pts[0];
    ctx.moveTo(p0[0] * sx - cx, p0[1] * sy - cy);
    for (let i = 1; i < piece.pts.length; i++) {
      ctx.lineTo(piece.pts[i][0] * sx - cx, piece.pts[i][1] * sy - cy);
    }
    ctx.closePath();
  } else if (piece.kind === 'archTop') {
    const ax = piece.cx * sx - cx;
    const ay = piece.cy * sy - cy;
    const rOut = piece.rOut * sx;
    const rIn = piece.rIn * sx;
    ctx.arc(ax, ay, rOut, Math.PI, 0, false);
    ctx.arc(ax, ay, rIn, 0, Math.PI, true);
    ctx.closePath();
  } else if (piece.kind === 'archBot') {
    const ax = piece.cx * sx - cx;
    const ay = piece.cy * sy - cy;
    const rOut = piece.rOut * sx;
    const rIn = piece.rIn * sx;
    ctx.arc(ax, ay, rOut, 0, Math.PI, false);
    ctx.arc(ax, ay, rIn, Math.PI, 0, true);
    ctx.closePath();
  }
}

/* ---------- BAUHAUS GEOMETRIC SANS VECTOR LETTERS IN [0..w] x [0..1] ---------- */
const K6_SANS_META = {
  'H': { w: 0.72 },
  'A': { w: 0.76 },
  'P': { w: 0.68 },
  'Y': { w: 0.72 },
  'N': { w: 0.74 },
  'E': { w: 0.64 },
  'W': { w: 0.94 },
  'R': { w: 0.70 }
};

function k6DrawGeometricChar(ctx, ch, x, y, h) {
  const w = K6_SANS_META[ch].w;
  const pad = 0.08;
  const xL = pad;
  const xR = w - pad;
  const yT = pad;
  const yM = 0.50;
  const yB = 1.0 - pad;

  ctx.save();
  ctx.translate(x, y);
  ctx.scale(h, h);
  ctx.lineWidth = 0.14;
  ctx.lineCap = 'square';
  ctx.lineJoin = 'bevel';
  ctx.strokeStyle = K6_PALETTE.black;

  ctx.beginPath();
  if (ch === 'H') {
    ctx.moveTo(xL, yT); ctx.lineTo(xL, yB);
    ctx.moveTo(xR, yT); ctx.lineTo(xR, yB);
    ctx.moveTo(xL, yM); ctx.lineTo(xR, yM);
  } else if (ch === 'A') {
    const xC = w * 0.5;
    ctx.moveTo(xL, yB); ctx.lineTo(xC, yT); ctx.lineTo(xR, yB);
    ctx.moveTo(k6Lerp(xL, xC, 0.36), 0.65);
    ctx.lineTo(k6Lerp(xR, xC, 0.36), 0.65);
  } else if (ch === 'P') {
    ctx.moveTo(xL, yT); ctx.lineTo(xL, yB);
    ctx.moveTo(xL, yT); ctx.lineTo(w * 0.52, yT);
    ctx.arc(w * 0.52, 0.30, 0.22, -Math.PI * 0.5, Math.PI * 0.5, false);
    ctx.lineTo(xL, 0.52);
  } else if (ch === 'Y') {
    const xC = w * 0.5;
    ctx.moveTo(xL, yT); ctx.lineTo(xC, 0.50);
    ctx.moveTo(xR, yT); ctx.lineTo(xC, 0.50);
    ctx.lineTo(xC, yB);
  } else if (ch === 'N') {
    ctx.moveTo(xL, yB); ctx.lineTo(xL, yT);
    ctx.lineTo(xR, yB); ctx.lineTo(xR, yT);
  } else if (ch === 'E') {
    ctx.moveTo(xR, yT); ctx.lineTo(xL, yT);
    ctx.lineTo(xL, yB); ctx.lineTo(xR, yB);
    ctx.moveTo(xL, yM); ctx.lineTo(xR - 0.06, yM);
  } else if (ch === 'W') {
    ctx.moveTo(xL, yT);
    ctx.lineTo(k6Lerp(xL, xR, 0.23), yB);
    ctx.lineTo(w * 0.50, 0.28);
    ctx.lineTo(k6Lerp(xL, xR, 0.77), yB);
    ctx.lineTo(xR, yT);
  } else if (ch === 'R') {
    ctx.moveTo(xL, yT); ctx.lineTo(xL, yB);
    ctx.moveTo(xL, yT); ctx.lineTo(w * 0.52, yT);
    ctx.arc(w * 0.52, 0.295, 0.215, -Math.PI * 0.5, Math.PI * 0.5, false);
    ctx.lineTo(xL, 0.51);
    ctx.moveTo(w * 0.48, 0.51); ctx.lineTo(xR, yB);
  }
  ctx.stroke();
  ctx.restore();
}

/* Crisp Bauhaus geometric registration crosshair */
function k6DrawCrosshair(ctx, x, y, r, lw) {
  ctx.beginPath();
  ctx.moveTo(x - r, y); ctx.lineTo(x + r, y);
  ctx.moveTo(x, y - r); ctx.lineTo(x, y + r);
  ctx.lineWidth = lw;
  ctx.strokeStyle = K6_PALETTE.axisLine;
  ctx.stroke();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const safeLoopT = loopT < 0 ? loopT + duration : loopT;
  const safeScene = currentScene < 0 ? ((currentScene % sceneCount) + sceneCount) % sceneCount : currentScene;
  const safeProgress = sceneProgress < 0 ? sceneProgress + 1 : sceneProgress;

  const minSide = Math.min(width, height);
  const U = Math.min(minSide, width / (16 / 9));
  const cx = width * 0.5;
  const cy = height * 0.5;

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowColor = 'transparent';
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';

  /* ---------- 1. IVORY PAPER BACKDROP (ZERO BACKGROUND GLOW) ---------- */
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0.0, K6_PALETTE.ivoryTop);
  bgGrad.addColorStop(1.0, K6_PALETTE.ivoryBot);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(U, U);

  /* ---------- 2. SHIFTING MODULAR SWISS GRID & FRAME ---------- */
  const fw = 0.785;
  const fh = 0.415;
  const gridStep = 0.095;

  /* Grid shifts cleanly 1 full gridStep during Scene 2->3 so t=0 === t=20 modulo periodicity */
  let gridShiftFrac = 0;
  if (safeScene === 2) {
    gridShiftFrac = k6EaseInOutCubic(k6SubRange(safeProgress, 0.02, 0.36)) * 0.5;
  } else if (safeScene === 3) {
    gridShiftFrac = 0.5 + k6EaseInOutCubic(k6SubRange(safeProgress, 0.05, 0.45)) * 0.5;
  }
  const shiftX = (gridShiftFrac * gridStep) % gridStep;

  ctx.save();
  ctx.beginPath();
  ctx.rect(-fw, -fh, fw * 2, fh * 2);
  ctx.clip();

  ctx.lineWidth = 0.0014;
  ctx.strokeStyle = K6_PALETTE.gridLine;
  ctx.beginPath();
  for (let gx = -fw - gridStep + shiftX; gx <= fw + gridStep; gx += gridStep) {
    ctx.moveTo(gx, -fh);
    ctx.lineTo(gx, fh);
  }
  for (let gy = -4 * gridStep; gy <= 4 * gridStep + 0.001; gy += gridStep) {
    ctx.moveTo(-fw, gy);
    ctx.lineTo(fw, gy);
  }
  ctx.stroke();
  ctx.restore();

  /* Primary Bauhaus outer frame & 4 corner crosshairs */
  ctx.lineWidth = 0.0026;
  ctx.strokeStyle = K6_PALETTE.black;
  ctx.strokeRect(-fw, -fh, fw * 2, fh * 2);

  for (let sx = -1; sx <= 1; sx += 2) {
    for (let sy = -1; sy <= 1; sy += 2) {
      k6DrawCrosshair(ctx, sx * (fw - 0.026), sy * (fh - 0.026), 0.011, 0.002);
    }
  }

  /* Synchronized corner Bauhaus primary accents gliding along top/bottom tracks cleanly outside hero zone */
  let frameAccentP = 0;
  if (safeScene === 0) frameAccentP = k6EaseOutCubic(k6SubRange(safeProgress, 0.08, 0.52));
  else if (safeScene === 1 || safeScene === 2) frameAccentP = 1;
  else frameAccentP = 1 - k6EaseInCubic(k6SubRange(safeProgress, 0.42, 0.88));

  if (frameAccentP > 0.01) {
    const barTravel = 0.14 * frameAccentP;
    /* Top-left Red bar + Top-right Blue circle + Bottom-left Yellow triangle + Bottom-right Black square */
    ctx.fillStyle = K6_PALETTE.red;
    ctx.fillRect(-fw + 0.055, -fh + 0.020, barTravel, 0.012);

    ctx.beginPath();
    ctx.arc(fw - 0.055 - barTravel * 0.5, -fh + 0.026, 0.011 * frameAccentP, 0, K6_TAU);
    ctx.fillStyle = K6_PALETTE.blue;
    ctx.fill();

    ctx.fillStyle = K6_PALETTE.yellow;
    const tx = -fw + 0.055 + barTravel;
    const ty = fh - 0.020;
    const ts = 0.018 * frameAccentP;
    ctx.beginPath();
    ctx.moveTo(tx, ty - ts);
    ctx.lineTo(tx - ts * 0.85, ty);
    ctx.lineTo(tx + ts * 0.85, ty);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = K6_PALETTE.black;
    ctx.fillRect(fw - 0.055 - barTravel, fh - 0.032, barTravel, 0.012);
  }

  /* ---------- 3. BAUHAUS MODULAR "2027" ASSEMBLY / STAGING / DISASSEMBLY ---------- */
  const chars = ['2', '0', '2', '7'];
  const digW = 0.144;
  const digH = 0.216;
  const digGap = 0.062;
  const assembledColStep = digW + digGap; /* 0.206 U */
  const stagedColStep = 0.355;            /* Spacious non-overlapping staging columns */

  /* Hero block shifts gracefully upward in Scene 2; returns down in Scene 3 ONLY AFTER divider bar & text vanish */
  let layoutShiftUp = 0;
  if (safeScene === 2) {
    layoutShiftUp = k6EaseInOutCubic(k6SubRange(safeProgress, 0.02, 0.30));
  } else if (safeScene === 3) {
    layoutShiftUp = 1 - k6EaseInOutCubic(k6SubRange(safeProgress, 0.18, 0.32));
  }
  const assembledY = k6Lerp(0.0, -0.078, layoutShiftUp);

  /* Global envelope controlling clean staging <-> assembly <-> disassembly transitions */
  for (let d = 0; d < 4; d++) {
    const pieces = K6_DIGIT_PIECES[chars[d]];
    const colors = K6_DIGIT_COLORS[d];
    const colCentered = d - 1.5;

    for (let p = 0; p < pieces.length; p++) {
      const piece = pieces[p];
      const idx = d * 4 + p;

      /* Target world center of piece when assembled in "2027" */
      const targetDigitOriginX = colCentered * assembledColStep - digW * 0.5;
      const targetDigitOriginY = assembledY - digH * 0.5;
      const targetWX = targetDigitOriginX + piece.cent[0] * digW;
      const targetWY = targetDigitOriginY + piece.cent[1] * (digH / 1.5);

      /* Spacious non-overlapping Scene 0 staging coordinate in own column */
      const stageWX = colCentered * stagedColStep + piece.stage[0];
      const stageWY = piece.stage[1];

      let wx = stageWX;
      let wy = stageWY;
      let rot = piece.rot;
      let sc = 1;
      let alpha = 1;

      if (safeScene === 0) {
        const stag = d * 0.09 + p * 0.045;
        const enterU = k6EaseOutCubic(k6SubRange(safeProgress, stag, stag + 0.52));
        wx = k6Lerp(stageWX + piece.enter[0], stageWX, enterU);
        wy = k6Lerp(stageWY + piece.enter[1], stageWY, enterU);
        rot = k6Lerp(piece.rot * 2.1, piece.rot * 0.45, enterU);
        sc = k6EaseOutQuart(k6Clamp01(enterU * 1.15));
        alpha = k6Clamp01(enterU * 3);
      } else if (safeScene === 1) {
        const stag = d * 0.11 + p * 0.045;
        const lockU = k6EaseInOutCubic(k6SubRange(safeProgress, stag, stag + 0.42));
        const settleU = k6SubRange(safeProgress, stag + 0.42, stag + 0.58);
        const rotU = k6EaseInOutCubic(k6Clamp01(lockU / 0.72));
        wx = k6Lerp(stageWX, targetWX, lockU);
        wy = k6Lerp(stageWY, targetWY, lockU);
        rot = k6Lerp(piece.rot * 0.45, 0, rotU);
        sc = lockU >= 1 ? k6LockInwardPulse(settleU) : 1;
      } else if (safeScene === 2) {
        wx = targetWX;
        wy = targetWY;
        rot = 0;
        sc = 1;
      } else if (safeScene === 3) {
        /* Outer digits & outer top/bottom pieces release first AFTER center settles at 0.32; separate straight before rotating */
        const outerFirst = 1.5 - Math.abs(d - 1.5);
        const midDelay = (p === 0 || p === 3) ? 0 : 0.055;
        const stagOut = 0.32 + outerFirst * 0.09 + midDelay;
        const releaseU = k6EaseInOutCubic(k6SubRange(safeProgress, stagOut, stagOut + 0.28));
        const vanishU = k6EaseInCubic(k6SubRange(safeProgress, stagOut + 0.24, Math.min(0.97, stagOut + 0.46)));
        const rotU = k6EaseInOutCubic(k6SubRange(releaseU, 0.22, 1.0));
        wx = k6Lerp(targetWX, stageWX + piece.enter[0] * 1.1, releaseU);
        wy = k6Lerp(targetWY, stageWY + piece.enter[1] * 1.1, releaseU);
        rot = k6Lerp(0, -piece.rot * 1.6, rotU);
        sc = 1 - vanishU;
        alpha = 1 - vanishU;
      }

      if (sc > 0.01 && alpha > 0.01) {
        ctx.save();
        ctx.globalAlpha *= alpha;
        ctx.translate(wx, wy);
        ctx.rotate(rot);
        ctx.scale(sc, sc);
        k6TracePieceLocal(ctx, piece, digW, digH);
        ctx.fillStyle = colors[p];
        ctx.fill();
        ctx.restore();
      }
    }
  }

  /* ---------- 4. SCENE 1 TOP SUBTLE HEADER + SCENE 2/3 DIVIDER & "HAPPY NEW YEAR" ---------- */
  let topHeaderA = 0;
  if (safeScene === 1) topHeaderA = k6EaseOutCubic(k6SubRange(safeProgress, 0.55, 0.85));
  else if (safeScene === 2) topHeaderA = 1;
  else if (safeScene === 3) topHeaderA = 1 - k6EaseInCubic(k6SubRange(safeProgress, 0.04, 0.28));

  if (topHeaderA > 0.02) {
    ctx.save();
    ctx.globalAlpha = topHeaderA * 0.82;
    ctx.font = '700 ' + (0.022 * U).toFixed(2) + 'px "Arial", "Helvetica Neue", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.scale(1 / U, 1 / U);
    ctx.fillStyle = K6_PALETTE.inkMuted;
    ctx.fillText('BAUHAUS   •   MODULAR   2027', 0, -0.268 * U);
    ctx.restore();
  }

  /* Scene 2 & early Scene 3 lower geometric bar + geometric sans "HAPPY NEW YEAR" */
  /* In Scene 3 both disappear completely by safeProgress=0.17 (t=15.85s) BEFORE "2027" descends at 0.18 (t=15.9s) */
  let ruleGrow = 0;
  let phraseP = 0;
  if (safeScene === 2) {
    ruleGrow = k6EaseOutQuart(k6SubRange(safeProgress, 0.26, 0.52));
    phraseP = k6SubRange(safeProgress, 0.34, 0.74);
  } else if (safeScene === 3) {
    ruleGrow = 1 - k6EaseInOutCubic(k6SubRange(safeProgress, 0.03, 0.17));
    phraseP = 1 - k6EaseInCubic(k6SubRange(safeProgress, 0.00, 0.14));
  }

  if (ruleGrow > 0.005) {
    const ruleY = 0.095;
    const ruleHalfW = 0.44 * ruleGrow;

    /* Solid Bauhaus rule + 2 end tokens cleanly collapsing ahead of 2027 descent */
    ctx.beginPath();
    ctx.moveTo(-ruleHalfW, ruleY);
    ctx.lineTo(ruleHalfW, ruleY);
    ctx.lineWidth = 0.0042;
    ctx.strokeStyle = K6_PALETTE.black;
    ctx.stroke();

    const badgeR = 0.012 * ruleGrow;
    ctx.fillStyle = K6_PALETTE.red;
    ctx.beginPath();
    ctx.arc(-ruleHalfW - 0.026 * ruleGrow, ruleY, badgeR, 0, K6_TAU);
    ctx.fill();

    ctx.fillStyle = K6_PALETTE.blue;
    ctx.fillRect(ruleHalfW + 0.014 * ruleGrow, ruleY - badgeR, badgeR * 2, badgeR * 2);
  }

  if (phraseP > 0.005) {
    /* Custom Geometric Bauhaus "HAPPY NEW YEAR" centered at y = +0.185 */
    const words = ['HAPPY', 'NEW', 'YEAR'];
    const chH = 0.056;
    const kern = chH * 0.22;
    const spaceW = chH * 0.62;

    let totalPhraseW = 0;
    let totalLetters = 0;
    for (let w = 0; w < words.length; w++) {
      const wd = words[w];
      totalLetters += wd.length;
      for (let i = 0; i < wd.length; i++) {
        totalPhraseW += K6_SANS_META[wd[i]].w * chH + (i < wd.length - 1 ? kern : 0);
      }
      if (w < words.length - 1) totalPhraseW += spaceW;
    }

    let cursorX = -totalPhraseW * 0.5;
    const textY = 0.162;
    let chIdx = 0;
    for (let w = 0; w < words.length; w++) {
      const wd = words[w];
      for (let i = 0; i < wd.length; i++) {
        const ch = wd[i];
        const cw = K6_SANS_META[ch].w * chH;
        const off = (chIdx / Math.max(1, totalLetters)) * 0.42;
        const charU = k6EaseOutCubic(k6Clamp01((phraseP - off) / 0.58));

        if (charU > 0.01) {
          const cxChar = cursorX + cw * 0.5;
          const cyChar = textY + chH * 0.5;
          ctx.save();
          ctx.globalAlpha *= k6Clamp01(charU * 2.5);
          ctx.translate(cxChar, cyChar + (1 - charU) * 0.024);
          ctx.scale(charU, charU);
          k6DrawGeometricChar(ctx, ch, -cw * 0.5, -chH * 0.5, chH);
          ctx.restore();
        }

        cursorX += cw + (i < wd.length - 1 ? kern : 0);
        chIdx++;
      }
      if (w < words.length - 1) cursorX += spaceW;
    }

    /* Flanking Yellow triangle & small Red dot strictly outside "HAPPY NEW YEAR" bounds */
    const flankA = k6Clamp01(phraseP * 1.8);
    if (flankA > 0.02) {
      const sideX = totalPhraseW * 0.5 + 0.048;
      const fy = textY + chH * 0.5;
      const fr = 0.016 * flankA;

      ctx.fillStyle = K6_PALETTE.yellow;
      ctx.beginPath();
      ctx.moveTo(-sideX, fy - fr);
      ctx.lineTo(-sideX - fr * 0.9, fy + fr * 0.8);
      ctx.lineTo(-sideX + fr * 0.9, fy + fr * 0.8);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = K6_PALETTE.red;
      ctx.beginPath();
      ctx.arc(sideX, fy, fr * 0.72, 0, K6_TAU);
      ctx.fill();
    }
  }

  ctx.restore(); /* end U space */
  ctx.restore(); /* end outer draw */
}

/* ==========================================================================
   KONSEP 5 — ELASTIC "HAPPYYYY" STRETCH (HAPPY NEW YEAR 2027)
   Theme: Happy New Year 2027 | Duration: 20s | Scenes: 4 | Aspect Ratio: 16:9
   Resolution: FHD / 2K / 4K (3840x2160) | Recommended Export Bitrate: 100 Mbps
   Style: Kinetic Typography — Plump Elastic Bubble Letters & Dynamic Slot Stretch
   Pure Canvas 2D API — Zero Background Glow, Zero External Assets, Seamless Loop
   ========================================================================== */

const EXPORT_CONFIG = {
  width: 3840,
  height: 2160,
  aspectRatio: '16:9',
  fps: 60,
  duration: 20,
  bitrateMbps: 100,
  minBitrateMbps: 100,
  videoBitsPerSecond: 100000000
};

const K5_PALETTE = {
  lilacTop: '#EFE6FC',
  lilacBot: '#DFCFFA',
  frameInk: '#3A235E',
  ink: '#2E1A4D',
  pink: '#FF6AA8',
  mint: '#52DFB2',
  lemon: '#FFD646',
  sky: '#6EC8FF',
  peach: '#FF9A6C',
  cream: '#FFFDF7',
  shine: 'rgba(255, 255, 255, 0.72)'
};

const K5_TAU = Math.PI * 2;

function k5Clamp01(v) {
  return v < 0 ? 0 : (v > 1 ? 1 : v);
}

function k5Lerp(a, b, t) {
  return a + (b - a) * t;
}

function k5SubRange(p, s, e) {
  return k5Clamp01((p - s) / (e - s));
}

function k5EaseInOutCubic(t) {
  const u = k5Clamp01(t);
  return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2;
}

function k5EaseOutCubic(t) {
  const u = k5Clamp01(t);
  return 1 - Math.pow(1 - u, 3);
}

function k5EaseInCubic(t) {
  const u = k5Clamp01(t);
  return u * u * u;
}

/* Smooth C1-continuous controlled elastic pop (zero initial velocity, subtle overshoot) */
function k5EaseOutElasticSoft(t) {
  const u = k5Clamp01(t);
  if (u === 0 || u === 1) return u;
  if (u < 0.48) {
    const p = u / 0.48;
    const easeInOut = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
    return easeInOut * 1.10;
  }
  const q = (u - 0.48) / 0.52;
  return 1 + 0.10 * Math.cos(q * Math.PI * 1.5) * (1 - q * q);
}

/* Balanced volume-preserving cushion pulse: peaks smoothly inside [0..1] and returns to 0 */
function k5SquashWave(p) {
  const u = k5Clamp01(p);
  return Math.sin(u * Math.PI) * Math.cos(u * Math.PI * 2.0) * (1 - 0.35 * u);
}

/* ---------- ROUNDED BUBBLY PARAMETRIC GLYPH DEFINITIONS IN [0..w] x [0..1] ---------- */
/* Centerlines inset ~0.10 from edges so thick round strokes stay inside [0..w] x [0..1] */
const K5_GLYPH_META = {
  'H': { w: 0.74 },
  'A': { w: 0.78 },
  'P': { w: 0.70 },
  'Y': { w: 0.74 },
  'N': { w: 0.76 },
  'E': { w: 0.68 },
  'W': { w: 0.92 },
  'R': { w: 0.72 },
  '2': { w: 0.72 },
  '0': { w: 0.72 },
  '7': { w: 0.70 }
};

function k5TraceGlyphStrokes(ctx, ch, stretchRatio) {
  const extra = Math.max(0, stretchRatio || 0);
  const w = K5_GLYPH_META[ch].w + extra;
  const xL = 0.10;
  const xR = w - 0.10;
  const yT = 0.10;
  const yM = 0.50;
  const yB = 0.90;

  ctx.beginPath();
  if (ch === 'H') {
    ctx.moveTo(xL, yT); ctx.lineTo(xL, yB);
    ctx.moveTo(xR, yT); ctx.lineTo(xR, yB);
    ctx.moveTo(xL, yM); ctx.lineTo(xR, yM);
  } else if (ch === 'A') {
    const xC = w * 0.5;
    ctx.moveTo(xL, yB); ctx.lineTo(xC, yT); ctx.lineTo(xR, yB);
    ctx.moveTo(k5Lerp(xL, xC, 0.34), 0.62);
    ctx.lineTo(k5Lerp(xR, xC, 0.34), 0.62);
  } else if (ch === 'P') {
    ctx.moveTo(xL, yT); ctx.lineTo(xL, yB);
    ctx.moveTo(xL, yT);
    ctx.lineTo(xR - 0.14, yT);
    ctx.bezierCurveTo(xR + 0.04, yT, xR + 0.04, 0.52, xR - 0.14, 0.52);
    ctx.lineTo(xL, 0.52);
  } else if (ch === 'Y') {
    const xC = w * 0.5;
    ctx.moveTo(xL, yT); ctx.lineTo(xC, 0.49);
    ctx.moveTo(xR, yT); ctx.lineTo(xC, 0.49);
    ctx.lineTo(xC, yB);
  } else if (ch === 'N') {
    ctx.moveTo(xL, yB); ctx.lineTo(xL, yT);
    ctx.lineTo(xR, yB);
    ctx.lineTo(xR, yT);
  } else if (ch === 'E') {
    ctx.moveTo(xL, yT); ctx.lineTo(xL, yB);
    ctx.moveTo(xL, yT); ctx.lineTo(xR, yT);
    ctx.moveTo(xL, yM); ctx.lineTo(xR - 0.06, yM);
    ctx.moveTo(xL, yB); ctx.lineTo(xR, yB);
  } else if (ch === 'W') {
    ctx.moveTo(xL, yT);
    ctx.lineTo(k5Lerp(xL, xR, 0.24), yB);
    ctx.lineTo(w * 0.5, 0.34);
    ctx.lineTo(k5Lerp(xL, xR, 0.76), yB);
    ctx.lineTo(xR, yT);
  } else if (ch === 'R') {
    ctx.moveTo(xL, yT); ctx.lineTo(xL, yB);
    ctx.moveTo(xL, yT);
    ctx.lineTo(xR - 0.14, yT);
    ctx.bezierCurveTo(xR + 0.03, yT, xR + 0.03, 0.50, xR - 0.14, 0.50);
    ctx.lineTo(xL, 0.50);
    ctx.moveTo(k5Lerp(xL, xR, 0.48), 0.50);
    ctx.lineTo(xR, yB);
  } else if (ch === '2') {
    ctx.moveTo(xL + 0.02, 0.28);
    ctx.bezierCurveTo(xL + 0.05, 0.06, xR, 0.06, xR, 0.30);
    ctx.bezierCurveTo(xR, 0.52, xL + 0.18, 0.68, xL, yB);
    ctx.lineTo(xR, yB);
  } else if (ch === '0') {
    const cx0 = w * 0.5;
    const cy0 = 0.50;
    ctx.ellipse(cx0, cy0, w * 0.5 - 0.10, 0.40, 0, 0, K5_TAU);
  } else if (ch === '7') {
    ctx.moveTo(xL, yT);
    ctx.lineTo(xR, yT);
    ctx.lineTo(k5Lerp(xL, xR, 0.28), yB);
  }
}

function k5TraceGlyphShine(ctx, ch, stretchRatio) {
  const extra = Math.max(0, stretchRatio || 0);
  const w = K5_GLYPH_META[ch].w + extra;
  const xL = 0.10;
  const xR = w - 0.10;

  ctx.beginPath();
  if (ch === 'H' || ch === 'P' || ch === 'R' || ch === 'N') {
    ctx.moveTo(xL - 0.012, 0.15);
    ctx.lineTo(xL - 0.012, 0.36);
  } else if (ch === 'A') {
    ctx.moveTo(xL + 0.15, 0.46);
    ctx.lineTo(w * 0.5 - 0.04, 0.18);
  } else if (ch === 'Y') {
    ctx.moveTo(xL + 0.01, 0.14);
    ctx.lineTo(xL + 0.12, 0.31);
  } else if (ch === 'E') {
    ctx.moveTo(xL + 0.04, 0.09);
    ctx.lineTo(xR - 0.06, 0.09);
  } else if (ch === 'W') {
    ctx.moveTo(xL + 0.02, 0.15);
    ctx.lineTo(xL + 0.09, 0.45);
  } else if (ch === '2') {
    ctx.moveTo(xL + 0.08, 0.18);
    ctx.bezierCurveTo(xL + 0.18, 0.10, xR - 0.14, 0.10, xR - 0.06, 0.22);
  } else if (ch === '0') {
    ctx.ellipse(w * 0.5, 0.50, w * 0.5 - 0.115, 0.385, 0, Math.PI * 1.12, Math.PI * 1.56);
  } else if (ch === '7') {
    ctx.moveTo(xL + 0.04, 0.09);
    ctx.lineTo(xR - 0.10, 0.09);
  }
}

/* Draw single plump elastic glyph anchored at (centerX, centerY) with box height h */
function k5DrawElasticGlyph(ctx, ch, centerX, centerY, h, sx, sy, color, stretchRatio, alpha) {
  if (alpha <= 0.01 || sx <= 0.01 || sy <= 0.01) return;
  const w = K5_GLYPH_META[ch].w + Math.max(0, stretchRatio || 0);
  const strokeW = 0.165;
  const outlineW = 0.235;

  ctx.save();
  ctx.globalAlpha *= alpha;
  ctx.translate(centerX, centerY);
  ctx.scale(h * sx, h * sy);
  ctx.translate(-w * 0.5, -0.5);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  /* Pass 1: crisp rounded ink contour */
  k5TraceGlyphStrokes(ctx, ch, stretchRatio);
  ctx.lineWidth = outlineW;
  ctx.strokeStyle = K5_PALETTE.ink;
  ctx.stroke();

  /* Pass 2: plump pastel fill */
  ctx.lineWidth = strokeW;
  ctx.strokeStyle = color;
  ctx.stroke();

  /* Pass 3: crisp flat inner highlight accent */
  k5TraceGlyphShine(ctx, ch, stretchRatio);
  ctx.lineWidth = 0.036;
  ctx.strokeStyle = K5_PALETTE.shine;
  ctx.stroke();

  ctx.restore();
}

/* Helper to render a dynamically spaced horizontal row without any adjacent glyph overlap */
function k5DrawDynamicRow(ctx, items, rowCenterY, glyphH, gap) {
  let totalW = 0;
  const itemWidths = [];
  for (let i = 0; i < items.length; i++) {
    const it = items[i];
    const slotF = it.slotFactor !== undefined ? it.slotFactor : 1;
    const w = it.ch === ' '
      ? it.spaceW * slotF
      : (K5_GLYPH_META[it.ch].w + (it.stretch || 0)) * glyphH * slotF;
    itemWidths.push(w);
    totalW += w;
    if (i < items.length - 1 && slotF > 0.001 && it.ch !== ' ' && items[i + 1].ch !== ' ') {
      totalW += gap * Math.min(slotF, items[i + 1].slotFactor !== undefined ? items[i + 1].slotFactor : 1);
    }
  }

  let cursorX = -totalW * 0.5;
  for (let i = 0; i < items.length; i++) {
    const it = items[i];
    const w = itemWidths[i];
    const slotF = it.slotFactor !== undefined ? it.slotFactor : 1;
    if (it.ch !== ' ' && slotF > 0.005) {
      const cx = cursorX + w * 0.5;
      const cy = rowCenterY + (it.dy || 0);
      k5DrawElasticGlyph(ctx, it.ch, cx, cy, glyphH, it.sx, it.sy, it.color, it.stretch || 0, it.alpha);
    }
    cursorX += w;
    if (i < items.length - 1 && slotF > 0.001 && it.ch !== ' ' && items[i + 1].ch !== ' ') {
      const nextF = items[i + 1].slotFactor !== undefined ? items[i + 1].slotFactor : 1;
      cursorX += gap * Math.min(slotF, nextF);
    }
  }
}

