  { bx: -0.22, by:  0.352, r: 0.015, type: 'bubble',   color: K5_PALETTE.pink, ph: 2.8 },
  { bx:  0.00, by:  0.360, r: 0.011, type: 'confetti', color: K5_PALETTE.mint, ph: 3.7 },
  { bx:  0.22, by:  0.352, r: 0.015, type: 'bubble',   color: K5_PALETTE.peach, ph: 4.6 },
  { bx:  0.44, by:  0.358, r: 0.010, type: 'confetti', color: K5_PALETTE.mint, ph: 5.3 },
  { bx:  0.64, by:  0.355, r: 0.013, type: 'bubble',   color: K5_PALETTE.sky, ph: 6.1 },
  /* Strictly separated far-left flank (x <= -0.64) */
  { bx: -0.68, by: -0.170, r: 0.017, type: 'bubble',   color: K5_PALETTE.mint, ph: 0.4 },
  { bx: -0.65, by:  0.000, r: 0.012, type: 'confetti', color: K5_PALETTE.pink, ph: 1.8 },
  { bx: -0.69, by:  0.170, r: 0.016, type: 'bubble',   color: K5_PALETTE.lemon, ph: 3.3 },
  /* Strictly separated far-right flank (x >= +0.64) */
  { bx:  0.68, by: -0.170, r: 0.017, type: 'bubble',   color: K5_PALETTE.peach, ph: 1.2 },
  { bx:  0.65, by:  0.000, r: 0.012, type: 'confetti', color: K5_PALETTE.lemon, ph: 2.7 },
  { bx:  0.69, by:  0.170, r: 0.016, type: 'bubble',   color: K5_PALETTE.mint, ph: 4.2 }
];

function k5DrawConfetti(ctx, cycle) {
  for (let i = 0; i < K5_CONFETTI_NODES.length; i++) {
    const n = K5_CONFETTI_NODES[i];
    const x = n.bx + Math.sin(cycle * K5_TAU * 2 + n.ph) * 0.016;
    const y = n.by + Math.cos(cycle * K5_TAU * 2 + n.ph * 1.3) * 0.014;
    const breath = 0.86 + 0.14 * Math.sin(cycle * K5_TAU * 4 + n.ph);
    const r = n.r * breath;

    ctx.beginPath();
    ctx.arc(x, y, r, 0, K5_TAU);
    if (n.type === 'confetti') {
      ctx.fillStyle = n.color;
      ctx.fill();
      ctx.lineWidth = 0.0024;
      ctx.strokeStyle = K5_PALETTE.ink;
      ctx.stroke();
    } else {
      ctx.fillStyle = K5_PALETTE.cream;
      ctx.fill();
      ctx.lineWidth = 0.0032;
      ctx.strokeStyle = n.color;
      ctx.stroke();

      /* Crisp clean highlight dot on upper-left quadrant of bubble */
      ctx.beginPath();
      ctx.arc(x - r * 0.34, y - r * 0.34, r * 0.22, 0, K5_TAU);
      ctx.fillStyle = K5_PALETTE.shine;
      ctx.fill();
    }
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const safeLoopT = loopT < 0 ? loopT + duration : loopT;
  const safeScene = currentScene < 0 ? ((currentScene % sceneCount) + sceneCount) % sceneCount : currentScene;
  const safeProgress = sceneProgress < 0 ? sceneProgress + 1 : sceneProgress;
  const cycle = safeLoopT / duration;

  const minSide = Math.min(width, height);
  const U = Math.min(minSide, width / (16 / 9));
  const cx = width * 0.5;
  const cy = height * 0.5;

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowColor = 'transparent';
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';

  /* ---------- 1. MATTE LILAC POSTER BACKDROP (ZERO BACKGROUND GLOW) ---------- */
  const bg = ctx.createLinearGradient(0, 0, 0, height);
  bg.addColorStop(0, K5_PALETTE.lilacTop);
  bg.addColorStop(1, K5_PALETTE.lilacBot);
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, width, height);

  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(U, U);

  /* Clean rounded pastel poster frame strictly outside hero composition */
  const fw = 0.805;
  const fh = 0.425;
  const fr = 0.032;
  ctx.beginPath();
  ctx.roundRect(-fw, -fh, fw * 2, fh * 2, fr);
  ctx.lineWidth = 0.0032;
  ctx.strokeStyle = 'rgba(58, 35, 94, 0.28)';
  ctx.stroke();

  /* Non-overlapping orbital bubbles & round confetti in border tracks */
  k5DrawConfetti(ctx, cycle);

  /* Global seamless exit envelope cleanly shrinking all typography back to 0 at t=20 */
  const exitCollapse = safeScene === 3 ? k5EaseInCubic(k5SubRange(safeProgress, 0.72, 0.96)) : 0;
  const exitScale = 1 - exitCollapse;

  /* ---------- 2. ROW 1: "HAPPY" -> "HAPPYYYYY" (SCENE 0, 1, 2, 3) ---------- */
  /* Smoothly moves from centered hero (y = 0) in Scene 0/1 to upper row (y = -0.195) for Scene 2/3 */
  const moveRow1ToTop = safeScene === 0
    ? 0
    : (safeScene === 1 ? k5EaseInOutCubic(k5SubRange(safeProgress, 0.72, 0.98)) : 1);
  const row1Y = k5Lerp(0.0, -0.195, moveRow1ToTop);
  const row1H = k5Lerp(0.145, 0.112, moveRow1ToTop) * exitScale;

  const happyBase = [
    { ch: 'H', color: K5_PALETTE.pink },
    { ch: 'A', color: K5_PALETTE.lemon },
    { ch: 'P', color: K5_PALETTE.mint },
    { ch: 'P', color: K5_PALETTE.sky },
    { ch: 'Y', color: K5_PALETTE.peach }
  ];
  const extraYColors = [K5_PALETTE.pink, K5_PALETTE.lemon, K5_PALETTE.mint, K5_PALETTE.sky];

  const row1Items = [];
  for (let i = 0; i < happyBase.length; i++) {
    let sx = 1;
    let sy = 1;
    let dy = 0;
    let alpha = 1;
    let slotFactor = 1;

    if (safeScene === 0) {
      const stag = i * 0.11;
      const enterP = k5SubRange(safeProgress, stag, stag + 0.42);
      const pop = k5EaseOutElasticSoft(enterP);
      const settlePulse = k5SquashWave(k5SubRange(safeProgress, stag + 0.30, stag + 0.72)) * 0.08;
      const scaleV = pop;
      const cushion = 1 + settlePulse;
      sx = scaleV * cushion;
      sy = scaleV / Math.max(0.75, cushion);
      dy = (1 - pop) * 0.095 - Math.sin(k5Clamp01(enterP) * Math.PI) * 0.032;
      alpha = k5Clamp01(enterP * 4);
      slotFactor = Math.max(0, sx);
    } else if (safeScene === 1) {
      /* Subtle sympathetic cushion wave when trailing Y's bloom out */
      const nudge = Math.sin(safeProgress * Math.PI) * 0.055;
      sx = 1 - nudge * 0.5;
      sy = 1 + nudge * 0.5;
      slotFactor = sx;
    } else if (safeScene === 2) {
      const env = Math.sin(safeProgress * Math.PI);
      const idleWave = env * Math.sin(safeProgress * K5_TAU + i * 0.45) * 0.04;
      sx = 1 + idleWave;
      sy = 1 - idleWave * 0.85;
      slotFactor = sx;
    } else if (safeScene === 3 && exitCollapse > 0) {
      const deflate = k5EaseInCubic(k5Clamp01((exitCollapse - i * 0.03) / 0.88));
      const cushion = 1 + Math.sin(deflate * Math.PI) * 0.12;
      sx = (1 - deflate) * cushion;
      sy = (1 - deflate) / Math.max(0.75, cushion);
      alpha = 1 - deflate;
      slotFactor = Math.max(0, sx);
    }

    if (row1H > 0.004 && alpha > 0.01) {
      row1Items.push({
        ch: happyBase[i].ch,
        color: happyBase[i].color,
        sx,
        sy,
        dy,
        alpha,
        slotFactor,
        stretch: 0
      });
    }
  }

  /* Scene 1: trailing 4 extra Y's sprout smoothly & retract smoothly back to "HAPPY" */
  if (safeScene === 1) {
    for (let k = 0; k < 4; k++) {
      const inP = k5SubRange(safeProgress, 0.06 + k * 0.07, 0.34 + k * 0.07);
      const outP = k5SubRange(safeProgress, 0.56 + (3 - k) * 0.045, 0.80 + (3 - k) * 0.045);
      const yGrow = k5EaseOutElasticSoft(inP) * (1 - k5EaseInOutCubic(outP));
      if (yGrow > 0.01) {
        const stretchPeak = Math.sin(k5Clamp01(safeProgress) * Math.PI) * 0.10;
        const cushion = 1 + stretchPeak * 0.6;
        const sxY = Math.max(0.02, yGrow * cushion);
        row1Items.push({
          ch: 'Y',
          color: extraYColors[k],
          sx: sxY,
          sy: Math.max(0.02, yGrow / cushion),
          dy: (1 - yGrow) * 0.025,
          alpha: k5Clamp01(yGrow * 2.5),
          slotFactor: sxY,
          stretch: 0
        });
      }
    }
  }

  if (row1Items.length > 0 && row1H > 0.004) {
    k5DrawDynamicRow(ctx, row1Items, row1Y, row1H, row1H * 0.21);
  }

  /* ---------- 3. ROW 2: "NEW YEAR" ELASTIC STRETCH ("NEEEEW YEAR") IN SCENE 2 & 3 ---------- */
  if (safeScene >= 2) {
    const isS2 = safeScene === 2;
    const row2In = isS2 ? k5SubRange(safeProgress, 0.04, 0.30) : 1;
    const row2Pop = isS2 ? k5EaseOutElasticSoft(row2In) : 1;
    const row2ShiftUp = isS2
      ? k5EaseInOutCubic(k5SubRange(safeProgress, 0.78, 0.98))
      : 1;
    const row2Y = k5Lerp(0.065, -0.018, row2ShiftUp);
    const row2H = 0.108 * exitScale;

    /* Parametric elastic width wave on E letters & rhythmic stretch/compress in Scene 2 */
    const s2Wave = isS2 ? Math.sin(k5SubRange(safeProgress, 0.18, 0.88) * Math.PI) : 0;
    const s2Compress = isS2 ? Math.sin(k5SubRange(safeProgress, 0.56, 0.92) * Math.PI) : 0;
    const eParamStretch = s2Wave * 0.18 - s2Compress * 0.06;

    const newYearSpec = [
      { ch: 'N', color: K5_PALETTE.mint, isExtraE: false },
      { ch: 'E', color: K5_PALETTE.pink, isExtraE: false },
      { ch: 'E', color: K5_PALETTE.lemon, isExtraE: true, idx: 0 },
      { ch: 'E', color: K5_PALETTE.sky, isExtraE: true, idx: 1 },
      { ch: 'E', color: K5_PALETTE.peach, isExtraE: true, idx: 2 },
      { ch: 'W', color: K5_PALETTE.lemon, isExtraE: false },
      { ch: ' ', color: K5_PALETTE.cream, isExtraE: false },
      { ch: 'Y', color: K5_PALETTE.pink, isExtraE: false },
      { ch: 'E', color: K5_PALETTE.sky, isExtraE: false },
      { ch: 'A', color: K5_PALETTE.mint, isExtraE: false },
      { ch: 'R', color: K5_PALETTE.peach, isExtraE: false }
    ];

    const row2Items = [];
    for (let i = 0; i < newYearSpec.length; i++) {
      const sp = newYearSpec[i];
      if (sp.ch === ' ') {
        row2Items.push({ ch: ' ', spaceW: row2H * 0.44, slotFactor: row2In > 0.01 && exitScale > 0.01 ? 1 : 0 });
        continue;
      }

      let gScale = row2Pop;
      let slotF = k5EaseOutCubic(k5Clamp01(row2In * 1.2));

      if (sp.isExtraE) {
        if (!isS2) {
          gScale = 0;
          slotF = 0;
        } else {
          const eIn = k5SubRange(safeProgress, 0.18 + sp.idx * 0.04, 0.42 + sp.idx * 0.04);
          const eOut = k5SubRange(safeProgress, 0.58 + (2 - sp.idx) * 0.035, 0.78 + (2 - sp.idx) * 0.035);
          const eAmt = k5EaseOutElasticSoft(eIn) * (1 - k5EaseInOutCubic(eOut));
          gScale = eAmt;
          slotF = k5Clamp01(eAmt);
        }
      } else if (!isS2 && exitCollapse > 0) {
        const d = k5EaseInCubic(k5Clamp01((exitCollapse - i * 0.025) / 0.88));
        gScale = 1 - d;
        slotF = 1 - d;
      }

      if (gScale > 0.01 && row2H > 0.004) {
        const stretchMod = (sp.ch === 'E') ? Math.max(0, eParamStretch * gScale) : 0;
        const rEnv = Math.sin(safeProgress * Math.PI);
        const rWave = isS2
          ? Math.sin(k5SubRange(safeProgress, 0.20, 0.90) * Math.PI) * Math.sin(k5SubRange(safeProgress, 0.20, 0.90) * K5_TAU + i * 0.35) * 0.065
          : rEnv * Math.sin(safeProgress * K5_TAU + i * 0.3) * 0.04 * (1 - exitCollapse);
        const cushion = 1 + rWave;
        const sxItem = gScale * cushion;
        row2Items.push({
          ch: sp.ch,
          color: sp.color,
          sx: sxItem,
          sy: gScale / Math.max(0.75, cushion),
          dy: isS2 ? (1 - row2Pop) * 0.045 : 0,
          alpha: k5Clamp01(gScale * 3),
          slotFactor: Math.max(slotF, sxItem),
          stretch: stretchMod
        });
      }
    }

    if (row2Items.length > 0 && row2H > 0.004) {
      k5DrawDynamicRow(ctx, row2Items, row2Y, row2H, row2H * 0.20);
    }
  }

  /* ---------- 4. ROW 3: BOUNCING HERO "2027" (SCENE 3) ---------- */
  if (safeScene === 3) {
    const yearChars = ['2', '0', '2', '7'];
    const yearColors = [K5_PALETTE.pink, K5_PALETTE.lemon, K5_PALETTE.mint, K5_PALETTE.sky];
    const row3H = 0.145 * exitScale;
    const row3Y = 0.172;
    const row3Items = [];

    for (let i = 0; i < 4; i++) {
      const stag = i * 0.07;
      const inP = k5SubRange(safeProgress, stag, stag + 0.34);
      const bounceP = k5EaseOutElasticSoft(inP);
      const midPulse = k5SquashWave(k5SubRange(safeProgress, 0.42 + i * 0.04, 0.72 + i * 0.04)) * 0.09;
      const outP = k5EaseInCubic(k5Clamp01((exitCollapse - i * 0.03) / 0.88));
      const sc = Math.max(0, bounceP * (1 - outP));

      if (sc > 0.01 && row3H > 0.004) {
        const cushion = 1 + midPulse + Math.sin(inP * Math.PI) * 0.08;
        const sxY = sc * cushion;
        const arcDrop = (1 - bounceP) * -0.075;
        row3Items.push({
          ch: yearChars[i],
          color: yearColors[i],
          sx: sxY,
          sy: sc / Math.max(0.75, cushion),
          dy: arcDrop,
          alpha: k5Clamp01(sc * 3),
          slotFactor: Math.max(0, sxY),
          stretch: 0
        });
      }
    }

    if (row3Items.length > 0 && row3H > 0.004) {
      k5DrawDynamicRow(ctx, row3Items, row3Y, row3H, row3H * 0.22);
    }
  }

  ctx.restore(); /* end U space */
  ctx.restore(); /* end outer draw */
}

/* ==========================================================================
   KONSEP 3 — GOLDEN RIBBON SCRIPT (HAPPY NEW YEAR 2027)
   Theme: Happy New Year 2027 | Duration: 20s | Scenes: 3 | Aspect Ratio: 16:9
   Resolution: FHD / 2K / 4K (3840x2160) | Recommended Export Bitrate: 100 Mbps
   Style: Kinetic Typography — Liquid Champagne-Gold Ribbons & Calligraphic Script
   Pure Canvas 2D API — Zero Background Glow, Zero External Assets, Seamless Loop
   ========================================================================== */

const EXPORT_CONFIG = {
  width: 3840,
  height: 2160,
  aspectRatio: '16:9',
  fps: 60,
  duration: 20,
  bitrateMbps: 100,
  minBitrateMbps: 100,
  videoBitsPerSecond: 100000000
};

const K3_PALETTE = {
  bgTop: '#1A040C',
  bgMid: '#2D0916',
  bgBot: '#150309',
  frameGold: '#7C5327',
  frameBright: '#E4BA66',
  goldDeep: '#9E661D',
  goldMid: '#E8BC62',
  goldLight: '#FBE8AC',
  ivory: '#FFF9EB',
  ribbonShadow: '#120208',
  dustGold: '#F4D17E',
  dustIvory: '#FFF6DE'
};

const K3_TAU = Math.PI * 2;
const K3_HALF_PI = Math.PI * 0.5;

function k3Clamp01(v) {
  return v < 0 ? 0 : v > 1 ? 1 : v;
}

function k3Lerp(a, b, t) {
  return a + (b - a) * t;
}

function k3EaseInOutCubic(t) {
  const x = k3Clamp01(t);
  return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}

function k3EaseOutCubic(t) {
  const x = k3Clamp01(t);
  return 1 - Math.pow(1 - x, 3);
}

function k3EaseInCubic(t) {
  const x = k3Clamp01(t);
  return x * x * x;
}

function k3EaseOutQuart(t) {
  const x = k3Clamp01(t);
  return 1 - Math.pow(1 - x, 4);
}

function k3SubRange(p, start, end) {
  return k3Clamp01((p - start) / (end - start));
}

/* ---------- ARC-LENGTH POLYLINE & BEZIER ENGINE ---------- */
function k3SampleCubic(p0, p1, p2, p3, steps) {
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const u = i / steps;
    const inv = 1 - u;
    const inv2 = inv * inv;
    const u2 = u * u;
    pts.push([
      inv2 * inv * p0[0] + 3 * inv2 * u * p1[0] + 3 * inv * u2 * p2[0] + u2 * u * p3[0],
      inv2 * inv * p0[1] + 3 * inv2 * u * p1[1] + 3 * inv * u2 * p2[1] + u2 * u * p3[1]
    ]);
  }
  return pts;
}

function k3CompilePolyline(pts) {
  const cum = [0];
  let total = 0;
  for (let i = 1; i < pts.length; i++) {
    total += Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]);
    cum.push(total);
  }
  return { pts, cum, total };
}

function k3SubdivideStroke(commands, stepsPerCurve) {
  const pts = [];
  let cur = [0, 0];
  for (let i = 0; i < commands.length; i++) {
    const cmd = commands[i];
    if (cmd.t === 'M') {
      cur = [cmd.x, cmd.y];
      pts.push(cur);
    } else if (cmd.t === 'L') {
      const next = [cmd.x, cmd.y];
      const segs = Math.max(4, Math.round(Math.hypot(next[0] - cur[0], next[1] - cur[1]) * 24));
      for (let s = 1; s <= segs; s++) {
        const f = s / segs;
        pts.push([k3Lerp(cur[0], next[0], f), k3Lerp(cur[1], next[1], f)]);
      }
      cur = next;
    } else if (cmd.t === 'C') {
      const segPts = k3SampleCubic(cur, [cmd.x1, cmd.y1], [cmd.x2, cmd.y2], [cmd.x, cmd.y], stepsPerCurve || 24);
      for (let s = 1; s < segPts.length; s++) pts.push(segPts[s]);
      cur = [cmd.x, cmd.y];
    }
  }
  return k3CompilePolyline(pts);
}

function k3PointAtLen(poly, targetLen) {
  const { pts, cum, total } = poly;
  if (targetLen <= 0) return pts[0];
  if (targetLen >= total) return pts[pts.length - 1];
  let lo = 0;
  let hi = cum.length - 1;
  while (lo < hi - 1) {
    const mid = (lo + hi) >> 1;
    if (cum[mid] <= targetLen) lo = mid;
    else hi = mid;
  }
  const segLen = cum[hi] - cum[lo];
  const f = segLen > 1e-6 ? (targetLen - cum[lo]) / segLen : 0;
  return [k3Lerp(pts[lo][0], pts[hi][0], f), k3Lerp(pts[lo][1], pts[hi][1], f)];
}

function k3SlicePolyline(poly, fStart, fEnd) {
  const s = k3Clamp01(fStart);
  const e = k3Clamp01(fEnd);
  if (e <= s + 1e-4 || poly.total <= 1e-6) return null;
  const lenStart = s * poly.total;
  const lenEnd = e * poly.total;
  const { pts, cum } = poly;
  const between = [];
  for (let i = 1; i < pts.length - 1; i++) {
    if (cum[i] > lenStart && cum[i] < lenEnd) between.push(pts[i]);
  }
  if (between.length < 6) {
    const out = [];
    const steps = 8;
    for (let k = 0; k <= steps; k++) {
      out.push(k3PointAtLen(poly, k3Lerp(lenStart, lenEnd, k / steps)));
    }
    return out;
  }
  const out = [k3PointAtLen(poly, lenStart)];
  for (let i = 0; i < between.length; i++) out.push(between[i]);
  out.push(k3PointAtLen(poly, lenEnd));
  return out;
}

/* ---------- 4 STRICTLY NON-INTERSECTING GOLDEN RIBBON TRACKS (SCENE 0) ---------- */
/* Tracks remain ordered by X/Y separation:
   Track 0 (y=-0.21) stops at x=-0.365 (above Track 1..3 across x <= -0.365)
   Track 1 (y=-0.02) stays strictly below Track 0 on x <= -0.365, curves to x=-0.115
   Track 2 (y=+0.11) stays strictly below Track 1 on x <= -0.115, curves to x=+0.085
   Track 3 (y=+0.23) stays strictly below Track 2 on x <= +0.085, curves to x=+0.305 */
const K3_FLOW_RIBBONS = [
  k3SubdivideStroke([
    { t: 'M', x: -0.76, y: -0.22 },
    { t: 'C', x1: -0.64, y1: -0.26, x2: -0.56, y2: -0.18, x: -0.46, y: -0.20 },
    { t: 'C', x1: -0.40, y1: -0.21, x2: -0.38, y2: -0.13, x: -0.365, y: -0.055 }
  ], 26),
  k3SubdivideStroke([
    { t: 'M', x: -0.76, y: -0.02 },
    { t: 'C', x1: -0.58, y1: 0.03, x2: -0.44, y2: -0.04, x: -0.28, y: -0.01 },
    { t: 'C', x1: -0.20, y1: 0.00, x2: -0.15, y2: -0.09, x: -0.110, y: -0.095 }
  ], 28),
  k3SubdivideStroke([
    { t: 'M', x: -0.76, y: 0.11 },
    { t: 'C', x1: -0.52, y1: 0.15, x2: -0.26, y2: 0.07, x: -0.02, y: 0.10 },
    { t: 'C', x1: 0.04, y1: 0.11, x2: 0.06, y2: 0.02, x: 0.082, y: -0.055 }
  ], 30),
  k3SubdivideStroke([
    { t: 'M', x: -0.76, y: 0.24 },
    { t: 'C', x1: -0.44, y1: 0.28, x2: -0.10, y2: 0.20, x: 0.14, y: 0.22 },
