function k3DrawDiamondStar(ctx, x, y, rOuter, rInner, rot) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rot || 0);
  ctx.beginPath();
  for (let i = 0; i < 8; i++) {
    const rad = i % 2 === 0 ? rOuter : rInner;
    const ang = i * (Math.PI / 4);
    const px = Math.cos(ang) * rad;
    const py = Math.sin(ang) * rad;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.fillStyle = K3_PALETTE.ivory;
  ctx.fill();
  ctx.lineWidth = 0.0014;
  ctx.strokeStyle = K3_PALETTE.goldMid;
  ctx.stroke();
  ctx.restore();
}

/* ---------- VARIABLE-WIDTH TAPERED LIQUID RIBBON RENDERER ---------- */
function k3BuildGoldGrad(ctx, x0, y0, x1, y1, sheenPhase) {
  const sheenOffset = 0.5 + 0.45 * Math.sin(sheenPhase);
  const grad = ctx.createLinearGradient(x0, y0, x1, y1);
  grad.addColorStop(0.0, K3_PALETTE.goldDeep);
  grad.addColorStop(Math.max(0.05, sheenOffset - 0.24), K3_PALETTE.goldMid);
  grad.addColorStop(sheenOffset, K3_PALETTE.ivory);
  grad.addColorStop(Math.min(0.95, sheenOffset + 0.24), K3_PALETTE.goldLight);
  grad.addColorStop(1.0, K3_PALETTE.goldDeep);
  return grad;
}

function k3DrawTaperedRibbon(ctx, pts, ox, oy, sx, sy, maxHalfW, sheenPhase, drawHeadStar, tipFloor, opts) {
  if (!pts || pts.length < 3) return;
  const cfg = opts || {};
  const pass = cfg.pass || 'both';
  const minTaper = tipFloor !== undefined ? tipFloor : 0.32;
  const startFloor = cfg.startFloor !== undefined ? cfg.startFloor : minTaper;
  const endFloor = cfg.endFloor !== undefined ? cfg.endFloor : minTaper;
  const startCornerBlend = cfg.startCornerBlend || 0;
  const endCornerBlend = cfg.endCornerBlend || 0;
  const closedFull = Boolean(cfg.closedFull);

  let n = pts.length;
  if (closedFull && n > 4) {
    const dSeam = Math.hypot(pts[n - 1][0] - pts[0][0], pts[n - 1][1] - pts[0][1]);
    if (dSeam < 0.03) n = n - 1;
  }

  const leftPts = [];
  const rightPts = [];
  const halfWs = [];

  for (let i = 0; i < n; i++) {
    const pPrev = closedFull ? pts[(i - 1 + n) % n] : pts[Math.max(0, i - 1)];
    const pNext = closedFull ? pts[(i + 1) % n] : pts[Math.min(n - 1, i + 1)];
    const tx = (pNext[0] - pPrev[0]) * sx;
    const ty = (pNext[1] - pPrev[1]) * sy;
    const tLen = Math.hypot(tx, ty) || 1;
    const ux = tx / tLen;
    const uy = ty / tLen;
    const nx = -uy;
    const ny = ux;

    let hw;
    if (closedFull) {
      const calli = 0.72 + 0.28 * Math.abs(uy);
      hw = maxHalfW * calli;
    } else {
      const u = i / (n - 1);
      const tStart = k3Lerp(startFloor, 1.0, Math.sin(k3Clamp01(u / 0.16) * K3_HALF_PI));
      const tEnd = k3Lerp(endFloor, 1.0, Math.sin(k3Clamp01((1 - u) / 0.16) * K3_HALF_PI));
      const taper = Math.min(tStart, tEnd);
      let calli = 0.72 + 0.28 * Math.abs(uy);
      if (startCornerBlend > 0 && u < 0.16) {
        calli = k3Lerp(calli, 1.0, (1 - u / 0.16) * startCornerBlend);
      }
      if (endCornerBlend > 0 && u > 0.84) {
        calli = k3Lerp(calli, 1.0, ((u - 0.84) / 0.16) * endCornerBlend);
      }
      hw = maxHalfW * taper * calli;
    }

    const px = ox + pts[i][0] * sx;
    const py = oy + pts[i][1] * sy;
    halfWs.push(hw);
    leftPts.push([px + nx * hw, py + ny * hw]);
    rightPts.push([px - nx * hw, py - ny * hw]);
  }

  const gradBox = cfg.gradBox;
  const gX0 = gradBox ? gradBox[0] : leftPts[0][0] - 0.15;
  const gY0 = gradBox ? gradBox[1] : leftPts[0][1] - 0.15;
  const gX1 = gradBox ? gradBox[2] : leftPts[n - 1][0] + 0.15;
  const gY1 = gradBox ? gradBox[3] : leftPts[n - 1][1] + 0.15;
  const grad = pass === 'shadow' ? null : k3BuildGoldGrad(ctx, gX0, gY0, gX1, gY1, sheenPhase);

  ctx.beginPath();
  if (closedFull) {
    ctx.moveTo(leftPts[0][0], leftPts[0][1]);
    for (let i = 1; i < n; i++) ctx.lineTo(leftPts[i][0], leftPts[i][1]);
    ctx.closePath();

    ctx.moveTo(rightPts[n - 1][0], rightPts[n - 1][1]);
    for (let i = n - 2; i >= 0; i--) ctx.lineTo(rightPts[i][0], rightPts[i][1]);
    ctx.closePath();
  } else {
    ctx.moveTo(leftPts[0][0], leftPts[0][1]);
    for (let i = 1; i < n; i++) ctx.lineTo(leftPts[i][0], leftPts[i][1]);
    for (let i = n - 1; i >= 0; i--) ctx.lineTo(rightPts[i][0], rightPts[i][1]);
    ctx.closePath();
  }

  const borderW = maxHalfW * 0.24;
  if (pass === 'shadow') {
    ctx.fillStyle = K3_PALETTE.ribbonShadow;
    ctx.fill(closedFull ? 'evenodd' : 'nonzero');
    ctx.lineWidth = borderW;
    ctx.strokeStyle = K3_PALETTE.ribbonShadow;
    ctx.stroke();

    if (!closedFull && cfg.roundCaps) {
      const capPad = borderW * 0.5;
      const r0 = halfWs[0] + capPad;
      const r1 = halfWs[n - 1] + capPad;
      const sx0 = ox + pts[0][0] * sx;
      const sy0 = oy + pts[0][1] * sy;
      const ex0 = ox + pts[n - 1][0] * sx;
      const ey0 = oy + pts[n - 1][1] * sy;
      ctx.beginPath();
      ctx.arc(sx0, sy0, r0, 0, K3_TAU);
      ctx.moveTo(ex0 + r1, ey0);
      ctx.arc(ex0, ey0, r1, 0, K3_TAU);
      ctx.fillStyle = K3_PALETTE.ribbonShadow;
      ctx.fill();
    }
    return;
  }

  ctx.fillStyle = grad;
  ctx.fill(closedFull ? 'evenodd' : 'nonzero');
  if (pass === 'both') {
    ctx.lineWidth = borderW;
    ctx.strokeStyle = K3_PALETTE.ribbonShadow;
    ctx.stroke();
  } else if (!closedFull && cfg.roundCaps) {
    const r0 = halfWs[0];
    const r1 = halfWs[n - 1];
    const sx0 = ox + pts[0][0] * sx;
    const sy0 = oy + pts[0][1] * sy;
    const ex0 = ox + pts[n - 1][0] * sx;
    const ey0 = oy + pts[n - 1][1] * sy;
    ctx.beginPath();
    ctx.arc(sx0, sy0, r0, 0, K3_TAU);
    ctx.moveTo(ex0 + r1, ey0);
    ctx.arc(ex0, ey0, r1, 0, K3_TAU);
    ctx.fillStyle = grad;
    ctx.fill();
  }

  if (drawHeadStar && !closedFull) {
    const tipPt = cfg.starAtStart ? pts[0] : pts[n - 1];
    k3DrawDiamondStar(ctx, ox + tipPt[0] * sx, oy + tipPt[1] * sy, maxHalfW * 1.45, maxHalfW * 0.46, sheenPhase * 0.5);
  }
}

/* ---------- LAYERED GOLD CALLIGRAPHY STROKE FOR SCRIPT (ZERO LOOP FOLDING) ---------- */
function k3DrawGoldScriptStroke(ctx, pts, ox, oy, sx, sy, baseW, sheenPhase, drawSpark) {
  if (!pts || pts.length < 2) return;
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(ox + pts[0][0] * sx, oy + pts[0][1] * sy);
  for (let i = 1; i < pts.length; i++) {
    ctx.lineTo(ox + pts[i][0] * sx, oy + pts[i][1] * sy);
  }

  const grad = ctx.createLinearGradient(ox, oy, ox + sx * 0.65, oy + sy);
  const sPos = 0.5 + 0.35 * Math.sin(sheenPhase);
  grad.addColorStop(0.0, K3_PALETTE.goldDeep);
  grad.addColorStop(Math.max(0.08, sPos - 0.22), K3_PALETTE.goldMid);
  grad.addColorStop(sPos, K3_PALETTE.ivory);
  grad.addColorStop(Math.min(0.92, sPos + 0.22), K3_PALETTE.goldLight);
  grad.addColorStop(1.0, K3_PALETTE.goldDeep);

  /* Dark velvet border separates crossing script loops cleanly */
  ctx.lineWidth = baseW * 1.38;
  ctx.strokeStyle = K3_PALETTE.ribbonShadow;
  ctx.stroke();

  /* Main sculpted champagne gold ribbon body */
  ctx.lineWidth = baseW;
  ctx.strokeStyle = grad;
  ctx.stroke();

  /* Fine ivory specular spine */
  ctx.lineWidth = baseW * 0.28;
  ctx.strokeStyle = 'rgba(255, 250, 236, 0.72)';
  ctx.stroke();

  if (drawSpark) {
    const tip = pts[pts.length - 1];
    k3DrawDiamondStar(ctx, ox + tip[0] * sx, oy + tip[1] * sy, baseW * 1.15, baseW * 0.36, sheenPhase);
  }
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const safeLoopT = loopT < 0 ? loopT + duration : loopT;
  const safeScene = currentScene < 0 ? ((currentScene % sceneCount) + sceneCount) % sceneCount : currentScene;
  const safeProgress = sceneProgress < 0 ? sceneProgress + 1 : sceneProgress;
  const cycle = safeLoopT / duration;

  const minSide = Math.min(width, height);
  const U = Math.min(minSide, width / (16 / 9));
  const cx = width * 0.5;
  const cy = height * 0.5;

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowColor = 'transparent';
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  /* ---------- 1. DEEP BURGUNDY ARCHITECTURAL BACKGROUND (ZERO GLOW) ---------- */
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0.0, K3_PALETTE.bgTop);
  bgGrad.addColorStop(0.5, K3_PALETTE.bgMid);
  bgGrad.addColorStop(1.0, K3_PALETTE.bgBot);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(U, U);

  /* ---------- 2. CLEAN DOUBLE ARCHITECTURAL FRAME & OUTER ORBITAL GOLD DUST ---------- */
  const fw = 0.785;
  const fh = 0.415;
  ctx.strokeStyle = 'rgba(228, 186, 102, 0.32)';
  ctx.lineWidth = 0.0022;
  ctx.strokeRect(-fw, -fh, fw * 2, fh * 2);

  ctx.strokeStyle = 'rgba(228, 186, 102, 0.16)';
  ctx.lineWidth = 0.0014;
  ctx.strokeRect(-(fw - 0.018), -(fh - 0.018), (fw - 0.018) * 2, (fh - 0.018) * 2);

  /* 4 symmetric corner diamond ornaments strictly in outer corners */
  for (let sx = -1; sx <= 1; sx += 2) {
    for (let sy = -1; sy <= 1; sy += 2) {
      k3DrawDiamondStar(ctx, sx * (fw - 0.018), sy * (fh - 0.018), 0.014, 0.0046, 0);
    }
  }

  /* Strictly zoned champagne dust beads gliding cleanly along top & bottom border tracks */
  /* Top track y = -0.355 U, Bottom track y = +0.355 U (well outside hero text zones!) */
  const beadCount = 10;
  for (let row = -1; row <= 1; row += 2) {
    const trackY = row * 0.352;
    const dir = row < 0 ? 1 : -1;
    for (let b = 0; b < beadCount; b++) {
      const frac = ((b / beadCount) + dir * cycle * 2) % 1;
      const cleanF = frac < 0 ? frac + 1 : frac;
      const bx = k3Lerp(-0.68, 0.68, cleanF);
      const by = trackY + Math.sin(cleanF * K3_TAU * 2 + row) * 0.008;
      const edgeFade = Math.sin(cleanF * Math.PI);
      const rad = (0.0032 + (b % 2) * 0.0022) * edgeFade;
      if (rad <= 0.0005) continue;

      ctx.beginPath();
      ctx.arc(bx, by, rad, 0, K3_TAU);
      ctx.fillStyle = (b % 3 === 0) ? K3_PALETTE.dustIvory : K3_PALETTE.dustGold;
      ctx.globalAlpha = 0.85 * edgeFade;
      ctx.fill();
    }
  }
  ctx.globalAlpha = 1;

  const sheenPhase = cycle * K3_TAU * 3;

  /* ---------- 3. SCENE 0 (0 - 6.67s): 4 PARALLEL NON-CROSSING FLOWING GOLDEN RIBBONS ---------- */
  if (safeScene === 0) {
    for (let i = 0; i < K3_FLOW_RIBBONS.length; i++) {
      const poly = K3_FLOW_RIBBONS[i];
      const stag = i * 0.065;
      const headP = k3EaseInOutCubic(k3Clamp01((safeProgress - stag) / 0.56));
      const tailP = k3EaseInOutCubic(k3Clamp01((safeProgress - (0.44 + stag * 0.65)) / 0.42));
      const endTrim = Math.min(headP, 0.999);
      const startTrim = Math.min(tailP, endTrim);

      if (endTrim > startTrim + 0.008) {
        const sl = k3SlicePolyline(poly, startTrim, endTrim);
        if (sl) {
          k3DrawTaperedRibbon(ctx, sl, 0, 0, 1, 1, 0.017, sheenPhase + i * 0.6, true, 0.06);
        }
      } else if (headP >= 0.99) {
        /* Single settling star after ribbon finishes retracting, smoothly shrinking out before Scene 1 */
        const endPt = poly.pts[poly.pts.length - 1];
        const settleStart = Math.min(0.995, 0.86 + stag * 0.65);
        const anchorS = 1 - k3EaseInCubic(k3SubRange(safeProgress, settleStart, 1.0));
        if (anchorS > 0.02) {
          k3DrawDiamondStar(ctx, endPt[0], endPt[1], 0.017 * 1.45 * anchorS, 0.017 * 0.46 * anchorS, (sheenPhase + i * 0.6) * 0.5);
        }
      }
    }

    /* Clean subtle upper caption fading gently in Scene 0 */
    const capAlpha = Math.sin(k3SubRange(safeProgress, 0.15, 0.85) * Math.PI);
    if (capAlpha > 0.02) {
      ctx.save();
      ctx.globalAlpha = capAlpha * 0.85;
      ctx.font = '600 ' + (0.026 * U).toFixed(2) + 'px "Georgia", "Times New Roman", serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.scale(1 / U, 1 / U);
      ctx.fillStyle = K3_PALETTE.goldLight;
      ctx.fillText('A NEW CHAPTER IN GOLD', 0, -0.300 * U);
      ctx.restore();
    }
  }

  /* ---------- 4. SCENE 1 & SCENE 2: SCULPTED "2027" + SCRIPT "Happy New Year" ---------- */
  if (safeScene === 1 || safeScene === 2) {
    const isS2 = safeScene === 2;
    const shiftToS2 = isS2 ? k3EaseInOutCubic(k3SubRange(safeProgress, 0.00, 0.24)) : 0;
    const retractS2 = isS2 ? k3EaseInCubic(k3SubRange(safeProgress, 0.76, 0.96)) : 0;

    const yearY = k3Lerp(0.00, 0.072, shiftToS2);
    const yearScale = k3Lerp(1.00, 0.86, shiftToS2);
    const digH = 0.215 * yearScale;
    const digW = 0.135 * yearScale;
    const digGap = 0.056 * yearScale;
    const totalW = 4 * digW + 3 * digGap;
    const startX = -totalW * 0.5;
    const chars = ['2', '0', '2', '7'];

    for (let i = 0; i < 4; i++) {
      const ch = chars[i];
      const gx = startX + i * (digW + digGap);
      const gy = yearY - digH * 0.5;
      const stag = i * 0.065;
      const dEnd = isS2 ? 1 : k3EaseInOutCubic(k3Clamp01((safeProgress - stag) / 0.42));
      const dStart = isS2 ? k3EaseInCubic(k3Clamp01((retractS2 - i * 0.04) / 0.84)) : 0;

      if (dEnd > dStart + 0.005) {
        const strokes = K3_DIGITS[ch];
        const isClosedDigit = ch === '0' && strokes.length === 1;
        let totalDigitLen = 0;
        for (let s = 0; s < strokes.length; s++) totalDigitLen += strokes[s].total;

        const cornerFrac = strokes.length === 2 ? strokes[0].total / totalDigitLen : 0;
        const cornerConn = strokes.length === 2
          ? k3Clamp01((dEnd - cornerFrac) / 0.08) * (1 - k3Clamp01((dStart - Math.max(0, cornerFrac - 0.08)) / 0.08))
          : 0;
        const tipW = 0.68;
        const jointW = k3Lerp(tipW, 0.72, cornerConn);
        const gradBox = [gx - digW * 0.06, gy - digH * 0.06, gx + digW * 1.06, gy + digH * 1.06];
        const ribW = 0.0145 * yearScale;
        const phase = sheenPhase + i * 0.45;

        const activeSlices = [];
        let accLen = 0;
        for (let s = 0; s < strokes.length; s++) {
          const poly = strokes[s];
          const f0 = accLen / totalDigitLen;
          const f1 = (accLen + poly.total) / totalDigitLen;
          accLen += poly.total;

          const localStart = k3Clamp01((dStart - f0) / (f1 - f0));
          const localEnd = k3Clamp01((dEnd - f0) / (f1 - f0));
          if (localEnd > localStart + 0.005) {
            const closedFull = isClosedDigit && localStart <= 0.004 && localEnd >= 0.996;
            const sl = closedFull ? poly.pts : k3SlicePolyline(poly, localStart, localEnd);
            if (sl) {
              const closeBlend = isClosedDigit
                ? k3SubRange(localEnd, 0.86, 0.996) * (1 - k3SubRange(localStart, 0.004, 0.10))
                : 0;
              const isHead = dEnd >= f0 && dEnd <= f1 + 0.01 && dEnd < 0.98 && !isS2;
              const isTail = dStart >= f0 && dStart <= f1 + 0.01 && dStart > 0.02 && isS2;
              activeSlices.push({
                pts: sl,
                drawStar: isHead || isTail,
                opts: {
                  pass: 'shadow',
                  closedFull,
                  roundCaps: true,
                  gradBox,
                  startFloor: isClosedDigit ? k3Lerp(tipW, 1.0, closeBlend) : (s === 1 ? jointW : tipW),
                  endFloor: isClosedDigit ? k3Lerp(tipW, 1.0, closeBlend) : (s === 0 && strokes.length === 2 ? jointW : tipW),
                  startCornerBlend: s === 1 ? cornerConn : 0,
                  endCornerBlend: s === 0 && strokes.length === 2 ? cornerConn : 0,
                  starAtStart: isTail && !isHead
                }
              });
            }
          }
        }

        for (let a = 0; a < activeSlices.length; a++) {
          const item = activeSlices[a];
          item.opts.pass = 'shadow';
          k3DrawTaperedRibbon(ctx, item.pts, gx, gy, digW, digH, ribW, phase, false, tipW, item.opts);
        }
        for (let a = 0; a < activeSlices.length; a++) {
          const item = activeSlices[a];
          item.opts.pass = 'fill';
          k3DrawTaperedRibbon(ctx, item.pts, gx, gy, digW, digH, ribW, phase, item.drawStar, tipW, item.opts);
        }
      }
    }

    /* Strictly separated Left & Right Golden Filigree Rules (|x| >= totalW*0.5 + 0.062) */
    const ruleStart = totalW * 0.5 + 0.062;
    const ruleLen = 0.145 * yearScale;
    const wingIn = isS2 ? 1 : k3EaseOutCubic(k3SubRange(safeProgress, 0.36, 0.68));
    const wingOut = isS2 ? k3EaseInCubic(k3SubRange(safeProgress, 0.74, 0.90)) : 0;
    const wingFrac = Math.max(0, wingIn - wingOut);

    if (wingFrac > 0.02) {
      for (let side = -1; side <= 1; side += 2) {
        const x0 = side * ruleStart;
        const x1 = side * (ruleStart + ruleLen * wingFrac);
        ctx.beginPath();
        ctx.moveTo(x0, yearY);
        ctx.lineTo(x1, yearY);
        ctx.lineWidth = 0.0032 * yearScale;
        ctx.strokeStyle = K3_PALETTE.goldMid;
        ctx.stroke();

        k3DrawDiamondStar(ctx, x1, yearY, 0.011 * wingFrac, 0.0035 * wingFrac, sheenPhase * 0.3);
      }
    }

    /* Scene 1 top subtle title before Scene 2 script enters */
    if (!isS2) {
      const s1TitleA = k3EaseOutCubic(k3SubRange(safeProgress, 0.20, 0.46)) * (1 - k3EaseInCubic(k3SubRange(safeProgress, 0.82, 0.98)));
      if (s1TitleA > 0.02) {
        ctx.save();
        ctx.globalAlpha = s1TitleA;
        ctx.font = '600 ' + (0.028 * U).toFixed(2) + 'px "Georgia", "Times New Roman", serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.scale(1 / U, 1 / U);
        ctx.fillStyle = K3_PALETTE.goldLight;
        ctx.fillText('GOLDEN EDITION', 0, -0.225 * U);
        ctx.restore();
      }
    }

    /* Scene 2 Upper Stage: Flowing Script "Happy New Year" (y = -0.155, >= 0.065 gap above 2027) */
    if (isS2) {
      const words = ['Happy', 'New', 'Year'];
      const glyphH = 0.132;
      const spaceW = glyphH * 0.25;
      const kern = glyphH * 0.052;

      let totalPhraseW = 0;
      let totalChars = 0;
      for (let w = 0; w < words.length; w++) {
        const wd = words[w];
        totalChars += wd.length;
        for (let i = 0; i < wd.length; i++) {
          const g = K3_SCRIPT_GLYPHS[wd[i]];
          if (g) totalPhraseW += g.w * glyphH + (i < wd.length - 1 ? kern : 0);
        }
        if (w < words.length - 1) totalPhraseW += spaceW;
      }

      const revealP = k3SubRange(safeProgress, 0.14, 0.56);
      const retractP = k3SubRange(safeProgress, 0.72, 0.92);
      const scriptAlpha = 1 - k3EaseInCubic(k3SubRange(safeProgress, 0.90, 0.98));

      let cursorX = -totalPhraseW * 0.5;
      const scriptY = -0.155 - glyphH * 0.52;
      let charIdx = 0;

      ctx.save();
      ctx.globalAlpha = scriptAlpha;
      for (let w = 0; w < words.length; w++) {
        const wd = words[w];
        for (let i = 0; i < wd.length; i++) {
          const g = K3_SCRIPT_GLYPHS[wd[i]];
          if (!g) continue;
          const off = (charIdx / Math.max(1, totalChars)) * 0.55;
          const gEnd = k3EaseInOutCubic(k3Clamp01((revealP - off) / 0.45));
          const gStart = k3EaseInCubic(k3Clamp01((retractP - off * 0.55) / 0.55));

          if (gEnd > gStart + 0.005) {
            for (let s = 0; s < g.strokes.length; s++) {
              const sl = k3SlicePolyline(g.strokes[s], gStart, gEnd);
              if (sl) {
                const isTipActive = gEnd > 0.02 && gEnd < 0.96 && s === g.strokes.length - 1;
                k3DrawGoldScriptStroke(ctx, sl, cursorX, scriptY, glyphH, glyphH, glyphH * 0.088, sheenPhase + charIdx * 0.2, isTipActive);
              }
            }
          }
          cursorX += g.w * glyphH + (i < wd.length - 1 ? kern : 0);
          charIdx++;
        }
        if (w < words.length - 1) cursorX += spaceW;
      }
      ctx.restore();

      /* Bottom celebratory tagline strictly below 2027 (y = +0.255, gap >= 0.085) */
      const botA = k3EaseOutCubic(k3SubRange(safeProgress, 0.28, 0.50)) * (1 - k3EaseInCubic(k3SubRange(safeProgress, 0.72, 0.88)));
      if (botA > 0.02) {
        ctx.save();
        ctx.globalAlpha = botA;
        ctx.font = '600 ' + (0.024 * U).toFixed(2) + 'px "Georgia", "Times New Roman", serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.scale(1 / U, 1 / U);
        ctx.fillStyle = K3_PALETTE.goldLight;
        ctx.fillText('CELEBRATE THE NEW YEAR   •   2027', 0, 0.252 * U);
        ctx.restore();
      }
    }
  }

  ctx.restore(); /* end U space */
  ctx.restore(); /* end outer draw */
}

/* ==========================================================================
   KONSEP 4 — RETRO ECHO CASCADE (HAPPY NEW YEAR 2027)
   Theme: Happy New Year 2027 | Duration: 20s | Scenes: 4 | Aspect Ratio: 16:9
   Resolution: FHD / 2K / 4K (3840x2160) | Recommended Export Bitrate: 100 Mbps
   Style: Kinetic Typography — 70s Silkscreen Layered Echo Cascade Poster
   Pure Canvas 2D API — Zero Background Glow, Zero External Assets, Seamless Loop
   ========================================================================== */

const EXPORT_CONFIG = {
  width: 3840,
  height: 2160,
  aspectRatio: '16:9',
  fps: 60,
  duration: 20,
  bitrateMbps: 100,
  minBitrateMbps: 100,
  videoBitsPerSecond: 100000000
};

const K4_PALETTE = {
  creamTop: '#FBF4E4',
  creamBot: '#F3E7CF',
  ink: '#1F1A17',
  creamKnockout: '#FBF4E4',
  layers: [
    '#1F1A17', // Layer 0 (Front Hero Face: Espresso Ink)
    '#E44643', // Layer 1 (Coral)
    '#EF6D2B', // Layer 2 (Tangerine Orange)
    '#E8AA24', // Layer 3 (Mustard)
    '#2E9699', // Layer 4 (Turquoise Teal)
    '#1C6E75'  // Layer 5 (Deep Teal)
  ],
  mutedInk: '#6B5D53'
};

const K4_TAU = Math.PI * 2;

function k4Clamp01(v) {
  return v < 0 ? 0 : v > 1 ? 1 : v;
}

function k4Lerp(a, b, t) {
  return a + (b - a) * t;
}

function k4EaseInOutCubic(t) {
  const x = k4Clamp01(t);
  return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}

function k4EaseInOutQuart(t) {
  const x = k4Clamp01(t);
  return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
}

function k4EaseOutQuart(t) {
  const x = k4Clamp01(t);
  return 1 - Math.pow(1 - x, 4);
}

function k4EaseInCubic(t) {
  const x = k4Clamp01(t);
  return x * x * x;
}

function k4SubRange(p, start, end) {
  return k4Clamp01((p - start) / (end - start));
}

function k4RoundedRect(ctx, x, y, w, h, r) {
  const rad = Math.min(r, w * 0.5, h * 0.5);
  ctx.beginPath();
  ctx.moveTo(x + rad, y);
  ctx.lineTo(x + w - rad, y);
  ctx.arcTo(x + w, y, x + w, y + rad, rad);
  ctx.lineTo(x + w, y + h - rad);
  ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
  ctx.lineTo(x + rad, y + h);
  ctx.arcTo(x, y + h, x, y + h - rad, rad);
  ctx.lineTo(x, y + rad);
  ctx.arcTo(x, y, x + rad, y, rad);
  ctx.closePath();
}

function k4DrawKnockoutText(ctx, text, xU, yU, fontPx, U, fillColor, haloPx) {
  ctx.save();
  ctx.translate(xU, yU);
  ctx.scale(1 / U, 1 / U);
  ctx.font = '900 ' + fontPx.toFixed(2) + 'px "Arial Black", "Segoe UI", "Helvetica Neue", Arial, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.lineJoin = 'round';
  ctx.miterLimit = 2;

  if (haloPx > 0) {
    ctx.lineWidth = haloPx;
    ctx.strokeStyle = K4_PALETTE.creamKnockout;
    ctx.strokeText(text, 0, 0);
  }
  ctx.fillStyle = fillColor;
  ctx.fillText(text, 0, 0);
  ctx.restore();
}

function k4DrawTrackedKnockoutText(ctx, text, xU, yU, fontPx, U, trackU, fillColor, haloPx) {
  ctx.save();
  ctx.font = '900 ' + fontPx.toFixed(2) + 'px "Arial Black", "Segoe UI", "Helvetica Neue", Arial, sans-serif';
  const chars = text.split('');
  const widths = chars.map(c => ctx.measureText(c).width / U);
  let totalW = 0;
  for (let i = 0; i < widths.length; i++) {
    totalW += widths[i] + (i < widths.length - 1 ? trackU : 0);
  }
  let curX = xU - totalW * 0.5;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.lineJoin = 'round';
  ctx.miterLimit = 2;

  for (let i = 0; i < chars.length; i++) {
    if (chars[i] !== ' ') {
      ctx.save();
      ctx.translate(curX, yU);
      ctx.scale(1 / U, 1 / U);
      if (haloPx > 0) {
        ctx.lineWidth = haloPx;
        ctx.strokeStyle = K4_PALETTE.creamKnockout;
        ctx.strokeText(chars[i], 0, 0);
      }
      ctx.fillStyle = fillColor;
      ctx.fillText(chars[i], 0, 0);
      ctx.restore();
    }
    curX += widths[i] + trackU;
  }
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const safeLoopT = loopT < 0 ? loopT + duration : loopT;
  const safeScene = currentScene < 0 ? ((currentScene % sceneCount) + sceneCount) % sceneCount : currentScene;
  const safeProgress = sceneProgress < 0 ? sceneProgress + 1 : sceneProgress;
  const cycle = safeLoopT / duration;

  const minSide = Math.min(width, height);
  const U = Math.min(minSide, width / (16 / 9));
  const cx = width * 0.5;
  const cy = height * 0.5;

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowColor = 'transparent';
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  /* ---------- 1. WARM RETRO CREAM BACKGROUND (ZERO GLOW) ---------- */
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0.0, K4_PALETTE.creamTop);
  bgGrad.addColorStop(1.0, K4_PALETTE.creamBot);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(U, U);

  /* ---------- 2. CLEAN RETRO POSTER FRAME & CORNER ARCS (OUTER MARGIN ONLY) ---------- */
  const fw = 0.795;
  const fh = 0.422;
  ctx.strokeStyle = K4_PALETTE.ink;
  ctx.lineWidth = 0.0034;
  ctx.strokeRect(-fw, -fh, fw * 2, fh * 2);

  ctx.lineWidth = 0.0016;
  ctx.strokeRect(-(fw - 0.015), -(fh - 0.015), (fw - 0.015) * 2, (fh - 0.015) * 2);

  /* 4 retro quarter-circle layered corner motifs strictly confined to outer corners */
  const cornerColors = [K4_PALETTE.layers[1], K4_PALETTE.layers[2], K4_PALETTE.layers[3]];
  for (let sx = -1; sx <= 1; sx += 2) {
    for (let sy = -1; sy <= 1; sy += 2) {
      const ox = sx * (fw - 0.015);
      const oy = sy * (fh - 0.015);
      const a0 = sx > 0 ? (sy > 0 ? Math.PI : Math.PI * 0.5) : (sy > 0 ? Math.PI * 1.5 : 0);
      const a1 = a0 + Math.PI * 0.5;
      for (let c = 0; c < 3; c++) {
        ctx.beginPath();
        ctx.arc(ox, oy, 0.044 - c * 0.012, a0, a1);
        ctx.lineWidth = 0.0042;
        ctx.strokeStyle = cornerColors[c];
        ctx.stroke();
      }
    }
  }

  /* Continuous top/bottom margin retro runner dots (2 integer loops = 100% seamless) */
  for (let row = -1; row <= 1; row += 2) {
    const ry = row * (fh - 0.0075);
    const dir = row < 0 ? 1 : -1;
    const tileSpan = 0.24;
    const shift = ((dir * 4 * tileSpan * cycle) % tileSpan + tileSpan) % tileSpan;
    for (let rx = -0.64 + shift; rx <= 0.64; rx += tileSpan) {
      const idx = Math.abs(Math.round((rx - shift) / tileSpan)) % 4;
      ctx.beginPath();
      ctx.arc(rx, ry, 0.0042, 0, K4_TAU);
      ctx.fillStyle = K4_PALETTE.layers[1 + idx];
      ctx.fill();
    }
  }

  /* ---------- 3. COMPUTE SMOOTH CASCADE OFFSETS ACROSS ALL 4 SCENES ---------- */
  /* Base diagonal angle = 135 deg (down-left: cos = -0.707, sin = +0.707) */
  const baseAngle = Math.PI * 0.75;
  let angle = baseAngle;
  const layerFracs = [0, 0, 0, 0, 0, 0];
  const waveX = [0, 0, 0, 0, 0, 0];
  const waveY = [0, 0, 0, 0, 0, 0];
  const digitWaveY = [0, 0, 0, 0];

  if (safeScene === 0) {
    /* Scene 0 (0-5s): Staggered outward cascade from center plate */
    for (let k = 1; k <= 5; k++) {
      const stag = (k - 1) * 0.11;
      layerFracs[k] = k4EaseOutQuart(k4Clamp01((safeProgress - stag) / 0.42));
    }
  } else if (safeScene === 1) {
    /* Scene 1 (5-10s): Smooth harmonic wave cascade across plates & digits */
    for (let k = 1; k <= 5; k++) layerFracs[k] = 1;
    const bell = Math.sin(safeProgress * Math.PI);
    for (let k = 0; k <= 5; k++) {
      const ph = safeProgress * K4_TAU * 2 - k * 0.55;
      waveX[k] = Math.cos(ph) * 0.009 * bell;
      waveY[k] = Math.sin(ph) * 0.011 * bell;
    }
    for (let d = 0; d < 4; d++) {
      digitWaveY[d] = Math.sin(safeProgress * K4_TAU * 2 - d * 0.65) * 0.011 * bell;
    }
  } else if (safeScene === 2) {
    /* Scene 2 (10-15s): Smooth 360-degree orbital sweep of echo direction */
    for (let k = 1; k <= 5; k++) layerFracs[k] = 1;
    angle = baseAngle + K4_TAU * k4EaseInOutCubic(safeProgress);
  } else if (safeScene === 3) {
    /* Scene 3 (15-20s): Hold accent showcase -> smooth reverse accordion fold to t=0 */
    for (let k = 1; k <= 5; k++) {
      const stag = (5 - k) * 0.055;
      const foldP = k4EaseInOutQuart(k4Clamp01((safeProgress - (0.58 + stag)) / 0.22));
      layerFracs[k] = 1 - foldP;
    }
  }

  const dirX = Math.cos(angle);
  const dirY = Math.sin(angle);

  /* ---------- 4. ZONE 1 (y = -0.250): RETRO ECHO BANNER "HAPPY NEW YEAR" ---------- */
  const topFontPx = 0.060 * U;
  const topY = -0.250;
  const topHaloPx = 0.0072 * U;
  const topStep = 0.0098;
  const topTrackU = 0.0075;

  /* Draw 4 echo plates back-to-front (k = 4..1) then Layer 0 front face */
  for (let k = 4; k >= 1; k--) {
    const frac = layerFracs[k];
    if (frac <= 0.008) continue;
    const ox = dirX * topStep * k * frac + waveX[k] * 0.65;
    const oy = dirY * topStep * k * frac + waveY[k] * 0.65;
    k4DrawTrackedKnockoutText(ctx, 'HAPPY NEW YEAR', ox, topY + oy, topFontPx, U, topTrackU, K4_PALETTE.layers[k], topHaloPx);
  }
  k4DrawTrackedKnockoutText(ctx, 'HAPPY NEW YEAR', waveX[0] * 0.65, topY + waveY[0] * 0.65, topFontPx, U, topTrackU, K4_PALETTE.layers[0], topHaloPx);

  /* ---------- 5. ZONE 2 (y = +0.038): HERO ECHO CASCADE "2027" ---------- */
  const heroFontPx = 0.210 * U;
  const heroStep = 0.0142;
  const heroHaloPx = 0.0115 * U;
  const heroChars = ['2', '0', '2', '7'];

  ctx.save();
  ctx.font = '900 ' + heroFontPx.toFixed(2) + 'px "Arial Black", "Segoe UI", "Helvetica Neue", Arial, sans-serif';
  const charWidths = heroChars.map(c => ctx.measureText(c).width / U);
  ctx.restore();

  const charGap = 0.034;
  let totalHeroW = 0;
  for (let i = 0; i < charWidths.length; i++) {
    totalHeroW += charWidths[i] + (i < charWidths.length - 1 ? charGap : 0);
  }

  const charCentersX = [];
  let cursorX = -totalHeroW * 0.5;
  for (let i = 0; i < 4; i++) {
    charCentersX.push(cursorX + charWidths[i] * 0.5);
    cursorX += charWidths[i] + charGap;
  }

  const heroBaseY = 0.038;
  /* Draw back-to-front across all 4 digits per layer k so front plates cleanly overlap back plates */
  for (let k = 5; k >= 1; k--) {
    const frac = layerFracs[k];
    if (frac <= 0.008) continue;
    const ox = dirX * heroStep * k * frac + waveX[k];
    const oy = dirY * heroStep * k * frac + waveY[k];
    for (let d = 0; d < 4; d++) {
      k4DrawKnockoutText(
        ctx,
        heroChars[d],
        charCentersX[d] + ox,
        heroBaseY + oy + digitWaveY[d],
        heroFontPx,
        U,
        K4_PALETTE.layers[k],
        heroHaloPx
      );
    }
  }
  for (let d = 0; d < 4; d++) {
    k4DrawKnockoutText(
      ctx,
      heroChars[d],
      charCentersX[d] + waveX[0],
      heroBaseY + waveY[0] + digitWaveY[d],
      heroFontPx,
      U,
      K4_PALETTE.layers[0],
      heroHaloPx
    );
  }

  /* ---------- 6. SCENE 3 SIDE RETRO STRIPE RIBBONS & BOTTOM TAGLINE ---------- */
  if (safeScene === 3) {
    const wingIn = k4EaseOutQuart(k4SubRange(safeProgress, 0.00, 0.30));
    const wingOut = k4EaseInCubic(k4SubRange(safeProgress, 0.56, 0.80));
    const wingSpan = Math.max(0, wingIn - wingOut);

    if (wingSpan > 0.01) {
      /* Strictly separated flanking retro stripes (|x| in [0.515, 0.685]) */
      const innerX = 0.515;
      const maxLen = 0.170;
      const stripeCols = [K4_PALETTE.layers[1], K4_PALETTE.layers[3], K4_PALETTE.layers[4]];
      const stripeYs = [-0.040, 0.000, 0.040];

      for (let side = -1; side <= 1; side += 2) {
        for (let s = 0; s < 3; s++) {
          const sx0 = side * innerX;
          const sx1 = side * (innerX + maxLen * wingSpan * (s === 1 ? 1.0 : 0.76));
          const sy = heroBaseY + stripeYs[s];
          const barX = Math.min(sx0, sx1);
          const barW = Math.abs(sx1 - sx0);
          const barH = 0.018;
          k4RoundedRect(ctx, barX, sy - barH * 0.5, barW, barH, barH * 0.5);
          ctx.fillStyle = stripeCols[s];
          ctx.fill();
        }
      }
    }

    /* Zone 3 Bottom Tagline strictly masked below y = +0.255 */
    const tagIn = k4EaseOutQuart(k4SubRange(safeProgress, 0.08, 0.34));
    const tagOut = k4EaseInCubic(k4SubRange(safeProgress, 0.54, 0.78));
    const tagShift = (1 - tagIn) * 0.055 + tagOut * 0.055;

    ctx.save();
    ctx.beginPath();
    ctx.rect(-0.72, 0.248, 1.44, 0.072);
    ctx.clip();

    ctx.translate(0, 0.285 + tagShift);
    ctx.scale(1 / U, 1 / U);
    ctx.font = '800 ' + (0.026 * U).toFixed(2) + 'px "Segoe UI", "Helvetica Neue", Arial, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = K4_PALETTE.mutedInk;
    ctx.fillText('NEW HORIZONS   •   RETRO EDITION 2027', 0, 0);
    ctx.restore();
  }

  ctx.restore(); /* end U space */
  ctx.restore(); /* end outer draw */
}

/* ==========================================================================
   KONSEP 2 — KINETIC MARQUEE WALL (HAPPY NEW YEAR 2027)
   Theme: Happy New Year 2027 | Duration: 20s | Scenes: 4 | Aspect Ratio: 16:9
   Resolution: FHD / 2K / 4K (3840x2160) | Recommended Export Bitrate: 100 Mbps
   Style: Kinetic Typography — Precision Parallel Marquee Grid & Clip Lenses
   Pure Canvas 2D API — Zero Background Glow, Zero External Assets, Seamless Loop
   ========================================================================== */

const EXPORT_CONFIG = {
  width: 3840,
  height: 2160,
  aspectRatio: '16:9',
  fps: 60,
  duration: 20,
  bitrateMbps: 100,
  minBitrateMbps: 100,
  videoBitsPerSecond: 100000000
};

const K2_PALETTE = {
  bgBlack: '#0B0D10',
  laneDark: '#12151B',
  laneAlt: '#0E1116',
  divider: '#242B36',
  lime: '#C6FF2E',
  limeSoft: '#D9FF6E',
  white: '#F5F7FA',
  mutedText: '#8C96A8',
  inkOnLime: '#0B0D10'
};

const K2_TAU = Math.PI * 2;
const K2_HALF_PI = Math.PI * 0.5;

function k2Clamp01(v) {
  return v < 0 ? 0 : v > 1 ? 1 : v;
}

function k2Lerp(a, b, t) {
  return a + (b - a) * t;
}

function k2EaseInOutCubic(t) {
  const x = k2Clamp01(t);
  return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}

function k2EaseInOutQuart(t) {
  const x = k2Clamp01(t);
  return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
}

function k2EaseOutQuart(t) {
  const x = k2Clamp01(t);
  return 1 - Math.pow(1 - x, 4);
}

function k2EaseInCubic(t) {
  const x = k2Clamp01(t);
  return x * x * x;
}

function k2SubRange(p, start, end) {
  return k2Clamp01((p - start) / (end - start));
}

function k2RoundedRectPath(ctx, x, y, w, h, r) {
  const rad = Math.min(r, w * 0.5, h * 0.5);
  ctx.beginPath();
  ctx.moveTo(x + rad, y);
  ctx.lineTo(x + w - rad, y);
  ctx.arcTo(x + w, y, x + w, y + rad, rad);
  ctx.lineTo(x + w, y + h - rad);
  ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
  ctx.lineTo(x + rad, y + h);
  ctx.arcTo(x, y + h, x, y + h - rad, rad);
  ctx.lineTo(x, y + rad);
  ctx.arcTo(x, y, x + rad, y, rad);
  ctx.closePath();
}

const K2_LANE_PHRASES = [
  ['2027', 'HAPPY NEW YEAR', 'CHEERS'],
  ['NEW YEAR', '2027', 'CELEBRATE'],
  ['HAPPY 2027', 'NEW HORIZONS', 'JOY']
];

/* Measure repeating token tile width in normalized U units (100% font-independent spacing) */
function k2MeasureLaneTile(ctx, tokens, fontPx, U, padScale) {
  ctx.font = '900 ' + fontPx.toFixed(2) + 'px "Arial Black", "Segoe UI", "Helvetica Neue", Arial, sans-serif';
  const pillPadX = 0.036 * padScale;
  const gapAfterToken = 0.034;
  const dotR = 0.0085;
  const gapAfterDot = 0.034;

  const items = [];
  let totalW = 0;
  for (let i = 0; i < tokens.length; i++) {
    const label = tokens[i];
    const textW = ctx.measureText(label).width / U;
    const isBadge = label.indexOf('2027') !== -1;
    const itemW = isBadge ? textW + pillPadX * 2 : textW;
    items.push({ label, textW, itemW, isBadge, xOff: totalW });
    totalW += itemW + gapAfterToken + dotR * 2 + gapAfterDot;
  }
  return { items, totalW, pillPadX, gapAfterToken, dotR };
}

/* Draw all parallel marquee lanes (shared helper for normal layer & inverted clip lenses) */
function k2RenderMarqueeWall(ctx, U, cycle, rotAngle, inverted, lanePulseArr, pillScaleArr, middleAlpha) {
  const lanePitch = 0.142;
  const bandH = 0.122;
  const halfGrid = 1.28;
  const fontSizeU = 0.068;
  const fontPx = fontSizeU * U;

  ctx.save();
  ctx.rotate(rotAngle);

  if (inverted) {
    ctx.fillStyle = K2_PALETTE.lime;
    ctx.fillRect(-1.5, -1.5, 3.0, 3.0);
  }

  ctx.textBaseline = 'middle';
  ctx.textAlign = 'left';

  for (let r = -7; r <= 7; r++) {
    const isMiddle = Math.abs(r) <= 2;
    const laneAlpha = isMiddle && middleAlpha !== undefined ? middleAlpha : 1;
    if (laneAlpha <= 0.005) continue;

    ctx.save();
    if (laneAlpha < 0.999) ctx.globalAlpha = laneAlpha;

    const laneIdx = r + 7;
    const yCenter = r * lanePitch;
    const isAlt = (Math.abs(r) % 2) === 1;
    const phraseSet = K2_LANE_PHRASES[Math.abs(r) % K2_LANE_PHRASES.length];
    const pulseAmt = lanePulseArr ? lanePulseArr[laneIdx] : 0;
    const pScale = pillScaleArr ? pillScaleArr[laneIdx] : 1;

    /* Dedicated lane background band (strictly 0.122 inside 0.142 pitch -> 0.020 clear gutter) */
    ctx.fillStyle = inverted
      ? (isAlt ? '#B5F01E' : K2_PALETTE.lime)
      : (isAlt ? K2_PALETTE.laneDark : K2_PALETTE.laneAlt);
    ctx.fillRect(-halfGrid, yCenter - bandH * 0.5, halfGrid * 2, bandH);

    /* Crisp lane divider rule centered in gutter between bands (omitted on shutter seam) */
    const divY = yCenter + lanePitch * 0.5;
    const hideSeam = middleAlpha !== undefined && middleAlpha < 0.99 && (r === -3 || r === 2);
    if (!hideSeam) {
      ctx.beginPath();
      ctx.moveTo(-halfGrid, divY);
      ctx.lineTo(halfGrid, divY);
      ctx.lineWidth = 0.0022;
      ctx.strokeStyle = inverted ? 'rgba(11, 13, 16, 0.25)' : K2_PALETTE.divider;
      ctx.stroke();

      /* Subtle calibrated diamond marker gliding along divider gutter (integer loops = seamless) */
      const dirDiv = r % 2 === 0 ? 1 : -1;
      const markerTile = 0.42;
      const markerLoops = 4;
      const markerShift = ((dirDiv * markerLoops * markerTile * cycle) % markerTile + markerTile) % markerTile;
      ctx.fillStyle = inverted ? K2_PALETTE.inkOnLime : (isAlt ? K2_PALETTE.lime : K2_PALETTE.divider);
      for (let mx = -halfGrid + markerShift; mx <= halfGrid; mx += markerTile) {
        const mr = 0.0042;
        ctx.beginPath();
        ctx.moveTo(mx, divY - mr);
        ctx.lineTo(mx + mr * 1.4, divY);
        ctx.lineTo(mx, divY + mr);
        ctx.lineTo(mx - mr * 1.4, divY);
        ctx.closePath();
        ctx.fill();
      }
    }

    const dir = r % 2 === 0 ? 1 : -1;

    /* Measure tile & compute exact integer-cycle seamless offset */
    const tile = k2MeasureLaneTile(ctx, phraseSet, fontPx, U, pScale);
    const tileW = tile.totalW;
    const cyclesPerLoop = 3 + (Math.abs(r) % 2);
    const rawShift = dir * cyclesPerLoop * tileW * cycle;
    const modShift = ((rawShift % tileW) + tileW) % tileW;
    const startX = -halfGrid - tileW + modShift;

    /* Clip tightly inside the current lane band so no glyph can ever bleed into gutter */
    ctx.save();
    ctx.beginPath();
    ctx.rect(-halfGrid, yCenter - bandH * 0.5, halfGrid * 2, bandH);
    ctx.clip();

    const pillH = bandH * 0.72;
    const pillR = pillH * 0.5;
    const textScaleFactor = 1 / U;

    for (let tx = startX; tx < halfGrid + tileW; tx += tileW) {
      for (let k = 0; k < tile.items.length; k++) {
        const it = tile.items[k];
        const ix = tx + it.xOff;
        if (ix + it.itemW < -halfGrid || ix > halfGrid) continue;

        if (it.isBadge) {
          /* Crisp rounded badge pill framing "2027" tokens */
          const pillFill = inverted
            ? K2_PALETTE.inkOnLime
            : (pulseAmt > 0.05 || !isAlt ? K2_PALETTE.lime : K2_PALETTE.white);
          k2RoundedRectPath(ctx, ix, yCenter - pillH * 0.5, it.itemW, pillH, pillR);
          ctx.fillStyle = pillFill;
          ctx.fill();

          ctx.save();
          ctx.translate(ix + tile.pillPadX, yCenter + 0.003);
          ctx.scale(textScaleFactor, textScaleFactor);
          ctx.font = '900 ' + fontPx.toFixed(2) + 'px "Arial Black", "Segoe UI", "Helvetica Neue", Arial, sans-serif';
          ctx.fillStyle = inverted ? K2_PALETTE.lime : K2_PALETTE.inkOnLime;
          ctx.fillText(it.label, 0, 0);
          ctx.restore();
        } else {
          ctx.save();
          ctx.translate(ix, yCenter + 0.003);
          ctx.scale(textScaleFactor, textScaleFactor);
          ctx.font = '900 ' + fontPx.toFixed(2) + 'px "Arial Black", "Segoe UI", "Helvetica Neue", Arial, sans-serif';
          ctx.fillStyle = inverted
            ? K2_PALETTE.inkOnLime
            : (pulseAmt > 0.25 ? K2_PALETTE.lime : (isAlt ? K2_PALETTE.white : '#D8DEE9'));
          ctx.fillText(it.label, 0, 0);
          ctx.restore();
        }

        /* Crisp circular separator bullet strictly spaced in gap */
        const dotX = ix + it.itemW + tile.gapAfterToken + tile.dotR;
        ctx.beginPath();
        ctx.arc(dotX, yCenter, tile.dotR, 0, K2_TAU);
        ctx.fillStyle = inverted
          ? K2_PALETTE.inkOnLime
          : (isAlt ? K2_PALETTE.lime : K2_PALETTE.white);
        ctx.fill();
      }
    }
    ctx.restore();
    ctx.restore();
  }
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const safeLoopT = loopT < 0 ? loopT + duration : loopT;
  const safeScene = currentScene < 0 ? ((currentScene % sceneCount) + sceneCount) % sceneCount : currentScene;
  const safeProgress = sceneProgress < 0 ? sceneProgress + 1 : sceneProgress;
  const cycle = safeLoopT / duration;

  const minSide = Math.min(width, height);
  const U = Math.min(minSide, width / (16 / 9));
  const cx = width * 0.5;
  const cy = height * 0.5;

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowColor = 'transparent';
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  /* ---------- 1. SOLID OBSIDIAN BACKGROUND (ZERO GLOW) ---------- */
  ctx.fillStyle = K2_PALETTE.bgBlack;
  ctx.fillRect(0, 0, width, height);

  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(U, U);

  /* ---------- 2. COMPUTE SCENE TRANSFORM & LANE WAVE PARAMETERS ---------- */
  let rotAngle = 0;
  const lanePulses = new Array(15).fill(0);
  const pillScales = new Array(15).fill(1);

  if (safeScene === 0) {
    /* Scene 0 (0-5s): Staggered outward highlight & tracking wave across horizontal lanes */
    rotAngle = 0;
    for (let r = -7; r <= 7; r++) {
      const idx = r + 7;
      const dist = Math.abs(r);
      const waveStart = dist * 0.06;
      const localP = k2Clamp01((safeProgress - waveStart) / 0.52);
      const wave = Math.sin(localP * Math.PI);
      lanePulses[idx] = wave;
      pillScales[idx] = 1 + 0.22 * k2EaseInOutCubic(wave);
    }
  } else if (safeScene === 1) {
    /* Scene 1 (5-10s): Smooth weighted 90 deg pivot -> crisp alternating vertical marquee */
    rotAngle = -K2_HALF_PI * k2EaseInOutQuart(k2SubRange(safeProgress, 0.00, 0.36));
    const colWave = Math.sin(k2SubRange(safeProgress, 0.42, 0.96) * Math.PI);
    for (let r = -7; r <= 7; r++) {
      const idx = r + 7;
      const odd = (Math.abs(r) % 2) === 1;
      lanePulses[idx] = odd ? colWave * 0.85 : colWave * 0.45;
      pillScales[idx] = 1 + (odd ? 0.16 : 0.08) * colWave;
    }
  } else if (safeScene === 2) {
    /* Scene 2 (10-15s): Vertical grid with 3 circular lenses -> smooth return pivot to 0 deg */
    const returnP = k2EaseInOutQuart(k2SubRange(safeProgress, 0.68, 1.00));
    rotAngle = -K2_HALF_PI * (1 - returnP);
  } else if (safeScene === 3) {
    /* Scene 3 (15-20s): Horizontal outer lanes + precision symmetric shutter hero stage */
    rotAngle = 0;
  }

  /* Shutter open amount & middle lane fade in Scene 3 (strictly avoids clipped lane peeking) */
  let shutterHalfH = 0;
  let middleLaneAlpha = 1;
  if (safeScene === 3) {
    const fadeOut = 1 - k2EaseInOutCubic(k2SubRange(safeProgress, 0.00, 0.05));
    const fadeIn = k2EaseInOutCubic(k2SubRange(safeProgress, 0.94, 1.00));
    middleLaneAlpha = Math.max(fadeOut, fadeIn);

    const openP = k2EaseOutQuart(k2SubRange(safeProgress, 0.05, 0.21));
    const closeP = k2EaseInOutQuart(k2SubRange(safeProgress, 0.81, 0.94));
    shutterHalfH = 0.352 * Math.min(openP, 1 - closeP);
  }

  /* ---------- 3. BASE PARALLEL MARQUEE WALL ---------- */
  k2RenderMarqueeWall(ctx, U, cycle, rotAngle, false, lanePulses, pillScales, middleLaneAlpha);

  /* ---------- 4. SCENE 2 TRIPLE NON-OVERLAPPING CIRCULAR INVERSION LENSES ---------- */
  if (safeScene === 2) {
    const sweepP = k2SubRange(safeProgress, 0.00, 0.68);
    if (sweepP > 0.001 && sweepP < 0.999) {
      const lensTracks = [
        { y: -0.285, r: 0.112, dir: 1, delay: 0.00 },
        { y: 0.000, r: 0.135, dir: -1, delay: 0.04 },
        { y: 0.285, r: 0.112, dir: 1, delay: 0.00 }
      ];

      for (let l = 0; l < lensTracks.length; l++) {
        const tr = lensTracks[l];
        const lp = k2EaseInOutCubic(k2Clamp01((sweepP - tr.delay) / (1 - tr.delay * 2)));
        const lx = tr.dir * k2Lerp(-1.06, 1.06, lp);
        const ly = tr.y;
        const lr = tr.r;

        if (Math.abs(lx) > 1.04) continue;

        /* Strictly clipped circular lens showing inverted Acid Lime / Obsidian marquee */
        ctx.save();
        ctx.beginPath();
        ctx.arc(lx, ly, lr, 0, K2_TAU);
        ctx.clip();
        k2RenderMarqueeWall(ctx, U, cycle, rotAngle, true, lanePulses, pillScales, 1);
        ctx.restore();

        /* Crisp double-stroke architectural lens bezel ring */
        ctx.beginPath();
        ctx.arc(lx, ly, lr, 0, K2_TAU);
        ctx.lineWidth = 0.0052;
        ctx.strokeStyle = K2_PALETTE.white;
        ctx.stroke();

        ctx.beginPath();
        ctx.arc(lx, ly, lr - 0.007, 0, K2_TAU);
        ctx.lineWidth = 0.0020;
        ctx.strokeStyle = K2_PALETTE.inkOnLime;
        ctx.stroke();
      }
    }
  }

  /* ---------- 5. SCENE 3 PRECISION SHUTTER VIEWPORT & HERO "HAPPY NEW YEAR 2027" ---------- */
  if (safeScene === 3 && shutterHalfH > 0.002) {
    /* Solid clean obsidian shutter stage (completely separates hero from outer marquee lanes) */
    ctx.save();
    ctx.beginPath();
    ctx.rect(-0.92, -shutterHalfH, 1.84, shutterHalfH * 2);
    ctx.clip();

    ctx.fillStyle = K2_PALETTE.bgBlack;
    ctx.fillRect(-0.92, -shutterHalfH, 1.84, shutterHalfH * 2);

    /* Corner precision brackets inside hero stage (|x| = 0.78, |y| = 0.280) */
    const brArm = 0.042;
    const brX = 0.78;
    const brY = 0.280;
    ctx.strokeStyle = K2_PALETTE.lime;
    ctx.lineWidth = 0.0036;
    ctx.globalAlpha = k2Clamp01((shutterHalfH - 0.28) / 0.072);
    ctx.beginPath();
    for (let sx = -1; sx <= 1; sx += 2) {
      for (let sy = -1; sy <= 1; sy += 2) {
        ctx.moveTo(sx * (brX - brArm), sy * brY);
        ctx.lineTo(sx * brX, sy * brY);
        ctx.lineTo(sx * brX, sy * (brY - brArm));
      }
    }
    ctx.stroke();
    ctx.globalAlpha = 1;

    /* --- SUB-BAND 1 (y = -0.172): "HAPPY" + [NEW YEAR] Capsule Pill --- */
    const topIn = k2EaseOutQuart(k2SubRange(safeProgress, 0.21, 0.41));
    const topOut = k2EaseInCubic(k2SubRange(safeProgress, 0.68, 0.80));
    const topSlide = (1 - topIn) * 0.120 + topOut * 0.120;

    ctx.save();
    ctx.beginPath();
    ctx.rect(-0.76, -0.225, 1.52, 0.105);
    ctx.clip();

    const subFontPx = 0.056 * U;
    ctx.font = '900 ' + subFontPx.toFixed(2) + 'px "Arial Black", "Segoe UI", "Helvetica Neue", Arial, sans-serif';
    const wHappy = ctx.measureText('HAPPY').width / U;
    const wNewYear = ctx.measureText('NEW YEAR').width / U;
    const pillPad = 0.030;
    const wordGap = 0.028;
    const pillW = wNewYear + pillPad * 2;
    const totalTopW = wHappy + wordGap + pillW;
    const topStartX = -totalTopW * 0.5;
    const subY = -0.172 + topSlide;

    ctx.textBaseline = 'middle';
    ctx.textAlign = 'left';

    /* "HAPPY" in crisp white */
    ctx.save();
    ctx.translate(topStartX, subY + 0.002);
    ctx.scale(1 / U, 1 / U);
    ctx.fillStyle = K2_PALETTE.white;
    ctx.fillText('HAPPY', 0, 0);
    ctx.restore();

    /* "NEW YEAR" inside Acid Lime capsule pill */
    const nyPillX = topStartX + wHappy + wordGap;
    const nyPillH = 0.078;
    k2RoundedRectPath(ctx, nyPillX, subY - nyPillH * 0.5, pillW, nyPillH, nyPillH * 0.5);
    ctx.fillStyle = K2_PALETTE.lime;
    ctx.fill();

    ctx.save();
    ctx.translate(nyPillX + pillPad, subY + 0.002);
    ctx.scale(1 / U, 1 / U);
    ctx.fillStyle = K2_PALETTE.inkOnLime;
    ctx.fillText('NEW YEAR', 0, 0);
    ctx.restore();
    ctx.restore();

    /* --- SUB-BAND 2 (y = -0.095): Precision Horizontal Divider Rule --- */
    const divIn = k2EaseOutQuart(k2SubRange(safeProgress, 0.20, 0.42));
    const divOut = k2EaseInCubic(k2SubRange(safeProgress, 0.68, 0.80));
    const divSpan = 0.56 * Math.min(divIn, 1 - divOut);
    if (divSpan > 0.005) {
      ctx.beginPath();
      ctx.moveTo(-divSpan, -0.095);
      ctx.lineTo(divSpan, -0.095);
      ctx.lineWidth = 0.0024;
      ctx.strokeStyle = K2_PALETTE.divider;
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(-divSpan * 0.38, -0.095);
      ctx.lineTo(divSpan * 0.38, -0.095);
      ctx.lineWidth = 0.0036;
      ctx.strokeStyle = K2_PALETTE.lime;
      ctx.stroke();
    }

    /* --- SUB-BAND 3 (y = +0.055): Monumental Staggered Masked "2027" --- */
    const heroFontPx = 0.215 * U;
    ctx.font = '900 ' + heroFontPx.toFixed(2) + 'px "Arial Black", "Segoe UI", "Helvetica Neue", Arial, sans-serif';
    const heroChars = ['2', '0', '2', '7'];
    const charWidths = heroChars.map(c => ctx.measureText(c).width / U);
    const charGap = 0.036;
    let totalHeroW = 0;
    for (let i = 0; i < charWidths.length; i++) {
      totalHeroW += charWidths[i] + (i < charWidths.length - 1 ? charGap : 0);
    }

    let heroCursorX = -totalHeroW * 0.5;
    const heroCenterY = 0.055;
    const slotTop = -0.068;
    const slotH = 0.246;

    for (let i = 0; i < heroChars.length; i++) {
      const cw = charWidths[i];
      const stag = i * 0.04;
      const cIn = k2EaseOutQuart(k2Clamp01((safeProgress - (0.22 + stag)) / 0.20));
      const cOut = k2EaseInCubic(k2Clamp01((safeProgress - (0.64 + i * 0.02)) / 0.10));
      const yOffset = (1 - cIn) * 0.295 + cOut * 0.295;

      ctx.save();
      ctx.beginPath();
      ctx.rect(heroCursorX - 0.015, slotTop, cw + 0.030, slotH);
      ctx.clip();

      ctx.save();
      ctx.translate(heroCursorX, heroCenterY + yOffset + 0.008);
