function k1Lerp(a, b, t) {
  return a + (b - a) * t;
}

function k1EaseInOutCubic(t) {
  const x = k1Clamp01(t);
  return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}

function k1EaseOutCubic(t) {
  const x = k1Clamp01(t);
  return 1 - Math.pow(1 - x, 3);
}

function k1EaseInCubic(t) {
  const x = k1Clamp01(t);
