/* ---------- VECTOR STROKE SAMPLING & ARC-LENGTH ENGINE ---------- */
function k1SampleCubic(p0, p1, p2, p3, steps) {
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const u = i / steps;
    const inv = 1 - u;
    const inv2 = inv * inv;
    const u2 = u * u;
    const x = inv2 * inv * p0[0] + 3 * inv2 * u * p1[0] + 3 * inv * u2 * p2[0] + u2 * u * p3[0];
    const y = inv2 * inv * p0[1] + 3 * inv2 * u * p1[1] + 3 * inv * u2 * p2[1] + u2 * u * p3[1];
    pts.push([x, y]);
  }
  return pts;
}

function k1CompilePolyline(pts) {
  const cum = [0];
  let total = 0;
  for (let i = 1; i < pts.length; i++) {
    const dx = pts[i][0] - pts[i - 1][0];
    const dy = pts[i][1] - pts[i - 1][1];
    total += Math.hypot(dx, dy);
    cum.push(total);
  }
  return { pts, cum, total };
}

function k1SubdivideStroke(commands, stepsPerCurve) {
  const pts = [];
  let cur = [0, 0];
  for (let i = 0; i < commands.length; i++) {
    const cmd = commands[i];
    if (cmd.t === 'M') {
      cur = [cmd.x, cmd.y];
      pts.push(cur);
    } else if (cmd.t === 'L') {
      const next = [cmd.x, cmd.y];
      const segs = Math.max(2, Math.round(Math.hypot(next[0] - cur[0], next[1] - cur[1]) * 16));
      for (let s = 1; s <= segs; s++) {
        const f = s / segs;
        pts.push([k1Lerp(cur[0], next[0], f), k1Lerp(cur[1], next[1], f)]);
      }
      cur = next;
    } else if (cmd.t === 'C') {
      const segPts = k1SampleCubic(cur, [cmd.x1, cmd.y1], [cmd.x2, cmd.y2], [cmd.x, cmd.y], stepsPerCurve || 22);
      for (let s = 1; s < segPts.length; s++) {
        pts.push(segPts[s]);
      }
      cur = [cmd.x, cmd.y];
    }
  }
  return k1CompilePolyline(pts);
}

function k1PointAtLen(poly, targetLen) {
  const { pts, cum, total } = poly;
  if (targetLen <= 0) return pts[0];
  if (targetLen >= total) return pts[pts.length - 1];
  let lo = 0;
  let hi = cum.length - 1;
  while (lo < hi - 1) {
    const mid = (lo + hi) >> 1;
    if (cum[mid] <= targetLen) lo = mid;
    else hi = mid;
  }
  const segLen = cum[hi] - cum[lo];
  const f = segLen > 1e-6 ? (targetLen - cum[lo]) / segLen : 0;
  return [k1Lerp(pts[lo][0], pts[hi][0], f), k1Lerp(pts[lo][1], pts[hi][1], f)];
}

function k1SlicePolyline(poly, fStart, fEnd) {
  const s = k1Clamp01(fStart);
  const e = k1Clamp01(fEnd);
  if (e <= s + 1e-4 || poly.total <= 1e-6) return null;
  const lenStart = s * poly.total;
  const lenEnd = e * poly.total;
  const out = [k1PointAtLen(poly, lenStart)];
  const { pts, cum } = poly;
  for (let i = 1; i < pts.length - 1; i++) {
    if (cum[i] > lenStart && cum[i] < lenEnd) {
      out.push(pts[i]);
    }
  }
  out.push(k1PointAtLen(poly, lenEnd));
  return out;
}

function k1TracePoints(ctx, pts, ox, oy, sx, sy) {
  if (!pts || pts.length < 2) return;
  ctx.moveTo(ox + pts[0][0] * sx, oy + pts[0][1] * sy);
  for (let i = 1; i < pts.length; i++) {
    ctx.lineTo(ox + pts[i][0] * sx, oy + pts[i][1] * sy);
  }
}

