        { t: 'C', x1: 0.59, y1: 0.66, x2: 0.62, y2: 0.52, x: 0.63, y: 0.40 }
      ], 16)
    ]
  },
  'Y': {
    w: 0.60,
    strokes: [
      k1SubdivideStroke([
        { t: 'M', x: 0.08, y: 0.10 },
        { t: 'C', x1: 0.14, y1: 0.34, x2: 0.24, y2: 0.46, x: 0.34, y: 0.46 },
        { t: 'C', x1: 0.44, y1: 0.46, x2: 0.52, y2: 0.28, x: 0.54, y: 0.10 }
      ], 14),
      k1SubdivideStroke([
        { t: 'M', x: 0.54, y: 0.10 },
        { t: 'C', x1: 0.46, y1: 0.46, x2: 0.38, y2: 0.80, x: 0.26, y: 0.94 },
        { t: 'C', x1: 0.20, y1: 0.99, x2: 0.12, y2: 0.94, x: 0.14, y: 0.85 }
      ], 16)
    ]
  },
  'r': {
    w: 0.42,
    strokes: [
      k1SubdivideStroke([
        { t: 'M', x: 0.13, y: 0.72 },
        { t: 'C', x1: 0.14, y1: 0.58, x2: 0.15, y2: 0.46, x: 0.16, y: 0.38 }
      ], 10),
      k1SubdivideStroke([
        { t: 'M', x: 0.15, y: 0.52 },
        { t: 'C', x1: 0.21, y1: 0.39, x2: 0.32, y2: 0.37, x: 0.38, y: 0.43 }
      ], 12)
    ]
  }
};

/* ---------- PRECISION MULTI-PASS VECTOR NEON RENDERER (ZERO SHADOWBLUR) ---------- */
function k1DrawNeonPaths(ctx, polys, ox, oy, sx, sy, baseW, tubeColors, intensity, drawStart, drawEnd, drawChannel) {
  if (polys.length === 0) return;

  if (drawChannel) {
    ctx.beginPath();
    for (let i = 0; i < polys.length; i++) {
      k1TracePoints(ctx, polys[i].pts, ox, oy, sx, sy);
    }
    ctx.lineWidth = baseW * 1.48;
    ctx.strokeStyle = K1_PALETTE.tubeBed;
    ctx.stroke();

    ctx.lineWidth = baseW * 0.92;
    ctx.strokeStyle = 'rgba(28, 42, 74, 0.42)';
    ctx.stroke();
  }

  const s = k1Clamp01(drawStart);
  const e = k1Clamp01(drawEnd);
  if (e <= s + 1e-4 || intensity <= 0.01) return;

  const activeSlices = [];
  let tipPt = null;
  for (let i = 0; i < polys.length; i++) {
    const sl = k1SlicePolyline(polys[i], s, e);
    if (sl) {
      activeSlices.push(sl);
      tipPt = sl[sl.length - 1];
    }
  }
  if (activeSlices.length === 0) return;

  ctx.save();
  ctx.beginPath();
  for (let i = 0; i < activeSlices.length; i++) {
    k1TracePoints(ctx, activeSlices[i], ox, oy, sx, sy);
  }

  /* Pass 1: Tight outer colored glass sheath */
  ctx.globalAlpha = intensity * 0.36;
  ctx.lineWidth = baseW * 1.62;
  ctx.strokeStyle = tubeColors.outer;
  ctx.stroke();

  /* Pass 2: Saturated main glass neon tube */
  ctx.globalAlpha = intensity * 0.92;
  ctx.lineWidth = baseW * 0.96;
  ctx.strokeStyle = tubeColors.mid;
  ctx.stroke();

  /* Pass 3: Razor-sharp bright inner filament core */
  ctx.globalAlpha = intensity;
  ctx.lineWidth = baseW * 0.34;
  ctx.strokeStyle = tubeColors.core;
  ctx.stroke();

  /* Traveling electrode spark while drawing in or out */
  if (e > 0.02 && e < 0.98 && tipPt) {
    const tx = ox + tipPt[0] * sx;
    const ty = oy + tipPt[1] * sy;
    ctx.beginPath();
    ctx.arc(tx, ty, baseW * 0.56, 0, TAU);
    ctx.fillStyle = tubeColors.core;
    ctx.globalAlpha = intensity * 0.95;
    ctx.fill();
  }
  ctx.restore();
}

/* ---------- ARCHITECTURAL BOARD & FRAME GEOMETRY ---------- */
function k1RoundedRectPts(hw, hh, r, segs) {
  const pts = [];
  const corners = [
    { cx: hw - r, cy: -hh + r, a0: -HALF_PI, a1: 0 },
    { cx: hw - r, cy: hh - r, a0: 0, a1: HALF_PI },
    { cx: -hw + r, cy: hh - r, a0: HALF_PI, a1: Math.PI },
    { cx: -hw + r, cy: -hh + r, a0: Math.PI, a1: Math.PI * 1.5 }
  ];
  for (let c = 0; c < 4; c++) {
    const cn = corners[c];
    for (let i = 0; i <= segs; i++) {
      const a = k1Lerp(cn.a0, cn.a1, i / segs);
      pts.push([cn.cx + Math.cos(a) * r, cn.cy + Math.sin(a) * r]);
    }
  }
  pts.push(pts[0]);
  return k1CompilePolyline(pts);
}

const K1_OUTER_FRAME_TOP = k1CompilePolyline(
  (function () {
    const pts = [];
    const hw = 0.715;
    const hh = 0.385;
    const r = 0.042;
    pts.push([0, -hh]);
    for (let i = 0; i <= 10; i++) {
      const a = k1Lerp(-HALF_PI, 0, i / 10);
      pts.push([hw - r + Math.cos(a) * r, -hh + r + Math.sin(a) * r]);
    }
    pts.push([hw, 0]);
    return pts;
  })()
);

function k1MirrorPoly(poly, mx, my) {
  return k1CompilePolyline(poly.pts.map(p => [p[0] * mx, p[1] * my]));
}

const K1_FRAME_QUADS = [
  K1_OUTER_FRAME_TOP,
  k1MirrorPoly(K1_OUTER_FRAME_TOP, -1, 1),
  k1MirrorPoly(K1_OUTER_FRAME_TOP, 1, -1),
  k1MirrorPoly(K1_OUTER_FRAME_TOP, -1, -1)
];

const K1_CORNER_BRACKETS = (function () {
  const hw = 0.672;
  const hh = 0.342;
  const arm = 0.095;
  const r = 0.022;
  const base = k1SubdivideStroke([
    { t: 'M', x: hw - arm, y: -hh },
    { t: 'L', x: hw - r, y: -hh },
    { t: 'C', x1: hw, y1: -hh, x2: hw, y2: -hh, x: hw, y: -hh + r },
    { t: 'L', x: hw, y: -hh + arm }
  ], 10);
  return [
    base,
    k1MirrorPoly(base, -1, 1),
    k1MirrorPoly(base, 1, -1),
    k1MirrorPoly(base, -1, -1)
  ];
})();

const K1_BOARD_POLY = k1RoundedRectPts(0.752, 0.418, 0.052, 10);

function k1DrawCapLine(ctx, text, cx, cy, charH, gapFactor, tubeColors, intensity, lineProgress, drawChannel) {
  const chars = text.split('');
  const charW = charH * 0.62;
  const stepX = charH * (0.62 + gapFactor);
  const totalW = (chars.length - 1) * stepX + charW;
  const startX = cx - totalW * 0.5;
  const baseW = charH * 0.145;

  for (let i = 0; i < chars.length; i++) {
    const ch = chars[i];
    if (ch === ' ') continue;
    const gx = startX + i * stepX;
    const gy = cy - charH * 0.5;

    if (ch === '•') {
      const dotP = k1Clamp01((lineProgress - i * 0.03) * 2.2);
      if (drawChannel) {
        ctx.beginPath();
        ctx.arc(gx + charW * 0.5, cy, baseW * 0.72, 0, TAU);
        ctx.fillStyle = K1_PALETTE.tubeBed;
        ctx.fill();
      }
      if (dotP > 0.02 && intensity > 0.01) {
        ctx.beginPath();
        ctx.arc(gx + charW * 0.5, cy, baseW * 0.52 * k1EaseOutCubic(dotP), 0, TAU);
        ctx.fillStyle = tubeColors.core;
        ctx.globalAlpha = intensity;
        ctx.fill();
        ctx.globalAlpha = 1;
      }
      continue;
    }

    const polys = K1_CAPS[ch];
    if (!polys) continue;
    const staggerStart = (i / Math.max(1, chars.length)) * 0.42;
    const charP = k1EaseInOutCubic(k1Clamp01((lineProgress - staggerStart) / 0.58));
    k1DrawNeonPaths(ctx, polys, gx, gy, charW, charH, baseW, tubeColors, intensity, 0, charP, drawChannel);
  }
}

function k1DrawScriptPhrase(ctx, words, cx, cy, glyphH, tubeColors, intensity, revealP, retractP) {
  const spaceW = glyphH * 0.24;
  const kerning = glyphH * 0.055;
  let totalW = 0;
  for (let w = 0; w < words.length; w++) {
    const word = words[w];
    for (let i = 0; i < word.length; i++) {
      const g = K1_SCRIPT_GLYPHS[word[i]];
      if (g) totalW += g.w * glyphH + (i < word.length - 1 ? kerning : 0);
    }
    if (w < words.length - 1) totalW += spaceW;
  }

  let cursorX = cx - totalW * 0.5;
  const gy = cy - glyphH * 0.52;
  const baseW = glyphH * 0.095;
  let totalGlyphs = 0;
  for (let w = 0; w < words.length; w++) totalGlyphs += words[w].length;

  let gIdx = 0;
  for (let w = 0; w < words.length; w++) {
    const word = words[w];
    for (let i = 0; i < word.length; i++) {
      const g = K1_SCRIPT_GLYPHS[word[i]];
      if (!g) continue;
      const startOff = (gIdx / Math.max(1, totalGlyphs)) * 0.55;
      const gEnd = k1EaseInOutCubic(k1Clamp01((revealP - startOff) / 0.45));
      const gStart = k1EaseInCubic(k1Clamp01((retractP - startOff * 0.6) / 0.55));
      k1DrawNeonPaths(ctx, g.strokes, cursorX, gy, glyphH, glyphH, baseW, tubeColors, intensity, gStart, gEnd, true);
      cursorX += g.w * glyphH + (i < word.length - 1 ? kerning : 0);
      gIdx++;
    }
    if (w < words.length - 1) cursorX += spaceW;
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const safeLoopT = loopT < 0 ? loopT + duration : loopT;
  const safeScene = currentScene < 0 ? ((currentScene % sceneCount) + sceneCount) % sceneCount : currentScene;
  const safeProgress = sceneProgress < 0 ? sceneProgress + 1 : sceneProgress;
  const cycle = safeLoopT / duration;

  const minSide = Math.min(width, height);
  const U = Math.min(minSide, width / (16 / 9));
  const cx = width * 0.5;
  const cy = height * 0.5;

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowColor = 'transparent';
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  /* ---------- 1. CLEAN ARCHITECTURAL MIDNIGHT BACKGROUND (ZERO GLOW) ---------- */
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0.0, K1_PALETTE.bgTop);
  bgGrad.addColorStop(0.5, K1_PALETTE.bgMid);
  bgGrad.addColorStop(1.0, K1_PALETTE.bgBot);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  /* Crisp drafting blueprint grid lines (zero glow) */
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(U, U);

  const gridStep = 0.08;
  ctx.lineWidth = 0.0014;
  ctx.strokeStyle = K1_PALETTE.gridStroke;
  ctx.beginPath();
  for (let gx = -0.88; gx <= 0.881; gx += gridStep) {
    ctx.moveTo(gx, -0.50);
    ctx.lineTo(gx, 0.50);
  }
  for (let gy = -0.48; gy <= 0.481; gy += gridStep) {
    ctx.moveTo(-0.90, gy);
    ctx.lineTo(0.90, gy);
  }
  ctx.stroke();

  /* ---------- 2. MOUNTING BACKBOARD & CORNER STANDOFFS (ALWAYS PRESENT) ---------- */
  ctx.beginPath();
  k1TracePoints(ctx, K1_BOARD_POLY.pts, 0, 0, 1, 1);
  ctx.closePath();
  ctx.fillStyle = K1_PALETTE.boardFill;
  ctx.fill();
  ctx.lineWidth = 0.0032;
  ctx.strokeStyle = K1_PALETTE.boardBorder;
  ctx.stroke();

  /* 4 corner physical mounting pins cleanly outside inner frame corners */
  const pinOffX = 0.716;
  const pinOffY = 0.386;
  for (let sx = -1; sx <= 1; sx += 2) {
    for (let sy = -1; sy <= 1; sy += 2) {
      const px = sx * pinOffX;
      const py = sy * pinOffY;
      ctx.beginPath();
      ctx.arc(px, py, 0.0115, 0, TAU);
      ctx.fillStyle = K1_PALETTE.standoffFill;
      ctx.fill();
      ctx.lineWidth = 0.0022;
      ctx.strokeStyle = K1_PALETTE.standoffRing;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(px, py, 0.0040, 0, TAU);
      ctx.fillStyle = K1_PALETTE.cyanMid;
      ctx.fill();
    }
  }

  /* ---------- 3. OUTER NEON ARCHITECTURAL FRAME & HARMONIC PULSE ---------- */
  /* Harmonic breath keeps animation alive cleanly without harsh jitter */
  const breath = 0.88 + 0.12 * Math.sin(TAU * 4 * cycle);

  let outerDrawEnd = 1;
  let outerDrawStart = 0;
  let outerInt = breath;
  let cornerEnd = 1;
  let cornerStart = 0;

  if (safeScene === 0) {
    outerDrawEnd = k1EaseInOutCubic(k1SubRange(safeProgress, 0.00, 0.48));
    cornerEnd = k1EaseInOutCubic(k1SubRange(safeProgress, 0.16, 0.62));
    outerInt = k1Lerp(0.45, breath, k1EaseOutCubic(k1SubRange(safeProgress, 0.00, 0.40)));
  } else if (safeScene === 3) {
    const outP = k1EaseInCubic(k1SubRange(safeProgress, 0.84, 1.00));
    outerDrawStart = outP;
    cornerStart = k1EaseInCubic(k1SubRange(safeProgress, 0.80, 0.96));
    outerInt = breath * (1 - outP * 0.75);
  }

  const cyanTube = { outer: K1_PALETTE.cyanOuter, mid: K1_PALETTE.cyanMid, core: K1_PALETTE.cyanCore };
  const pinkTube = { outer: K1_PALETTE.pinkOuter, mid: K1_PALETTE.pinkMid, core: K1_PALETTE.pinkCore };
  const goldTube = { outer: K1_PALETTE.goldOuter, mid: K1_PALETTE.goldMid, core: K1_PALETTE.goldCore };

  k1DrawNeonPaths(ctx, K1_FRAME_QUADS, 0, 0, 1, 1, 0.0078, cyanTube, outerInt, outerDrawStart, outerDrawEnd, true);
  k1DrawNeonPaths(ctx, K1_CORNER_BRACKETS, 0, 0, 1, 1, 0.0064, pinkTube, outerInt, cornerStart, cornerEnd, true);

  /* ---------- 4. SIDE MARGIN VERTICAL TELEMETRY RAILS (STRICTLY |x| >= 0.785) ---------- */
  for (let side = -1; side <= 1; side += 2) {
    const rx = side * 0.805;
    const railH = 0.28;

    /* Background rail track */
    ctx.beginPath();
    ctx.moveTo(rx, -railH);
    ctx.lineTo(rx, railH);
    ctx.lineWidth = 0.0032;
    ctx.strokeStyle = K1_PALETTE.mutedRail;
    ctx.stroke();

    /* 9 calibrated tick marks strictly separated from rail slider */
    ctx.beginPath();
    for (let k = -4; k <= 4; k++) {
      const ty = (k / 4) * railH;
      ctx.moveTo(rx - side * 0.012, ty);
      ctx.lineTo(rx - side * 0.024, ty);
    }
    ctx.lineWidth = 0.0022;
    ctx.strokeStyle = K1_PALETTE.standoffRing;
    ctx.stroke();

    /* Smooth harmonic diamond indicator gliding seamlessly along rail */
    const glideY = Math.sin(TAU * 2 * cycle + (side > 0 ? Math.PI : 0)) * (railH * 0.82);
    const dR = 0.0125;
    ctx.beginPath();
    ctx.moveTo(rx, glideY - dR);
    ctx.lineTo(rx + dR * 0.78, glideY);
    ctx.lineTo(rx, glideY + dR);
    ctx.lineTo(rx - dR * 0.78, glideY);
    ctx.closePath();
    ctx.fillStyle = side < 0 ? K1_PALETTE.cyanMid : K1_PALETTE.pinkMid;
    ctx.fill();
    ctx.lineWidth = 0.0022;
    ctx.strokeStyle = K1_PALETTE.tubeBed;
    ctx.stroke();
  }

  /* ---------- 5. BAND 3 BOTTOM STEP TRACKER (STRICTLY y = +0.285) ---------- */
  /* 4 phase nodes cleanly spaced horizontally, never overlapping footer text */
  const stepY = 0.308;
  const stepSpacing = 0.068;
  for (let sIdx = 0; sIdx < 4; sIdx++) {
    const sx = (sIdx - 1.5) * stepSpacing;
    const active = sIdx === safeScene;
    const passed = sIdx < safeScene;

    if (sIdx < 3) {
      ctx.beginPath();
      ctx.moveTo(sx + 0.014, stepY);
      ctx.lineTo(sx + stepSpacing - 0.014, stepY);
      ctx.lineWidth = 0.0024;
      ctx.strokeStyle = passed ? K1_PALETTE.cyanMid : K1_PALETTE.mutedRail;
      ctx.stroke();
    }

    ctx.beginPath();
    ctx.arc(sx, stepY, active ? 0.0082 : 0.0056, 0, TAU);
    ctx.fillStyle = active ? K1_PALETTE.pinkMid : passed ? K1_PALETTE.cyanMid : K1_PALETTE.mutedRail;
    ctx.fill();
    if (active) {
      ctx.beginPath();
      ctx.arc(sx, stepY, 0.0034, 0, TAU);
      ctx.fillStyle = K1_PALETTE.pinkCore;
      ctx.fill();
    }
  }

  /* ---------- 6. BAND 1 TOP HEADER & BAND 3 FOOTER LABELS ---------- */
  /* Strictly zoned: Top y = -0.255 (height 0.044 -> [-0.277, -0.233]), Bottom y = +0.250 (height 0.038 -> [0.231, 0.269]) */
  if (safeScene === 0) {
    const hIn = k1EaseOutCubic(k1SubRange(safeProgress, 0.14, 0.56));
    const hFade = 1 - k1EaseInCubic(k1SubRange(safeProgress, 0.86, 1.00));
    k1DrawCapLine(ctx, 'MIDNIGHT COUNTDOWN', 0, -0.255, 0.042, 0.26, cyanTube, breath * hFade, hIn, true);
    const fIn = k1EaseOutCubic(k1SubRange(safeProgress, 0.24, 0.64));
    k1DrawCapLine(ctx, 'SYSTEM INITIALIZED • 2027', 0, 0.248, 0.034, 0.24, pinkTube, breath * 0.9 * hFade, fIn, true);
  } else if (safeScene === 1) {
    const hIn = k1EaseOutCubic(k1SubRange(safeProgress, 0.00, 0.18));
    const hFade = 1 - k1EaseInCubic(k1SubRange(safeProgress, 0.88, 1.00));
    k1DrawCapLine(ctx, 'FINAL COUNTDOWN', 0, -0.255, 0.042, 0.28, cyanTube, breath * hFade, hIn, true);
    k1DrawCapLine(ctx, 'GET READY FOR 2027', 0, 0.248, 0.034, 0.24, goldTube, breath * 0.9 * hFade, hIn, true);
  } else if (safeScene === 2) {
    const hIn = k1EaseOutCubic(k1SubRange(safeProgress, 0.00, 0.24));
    const hFade = 1 - k1EaseInCubic(k1SubRange(safeProgress, 0.86, 1.00));
    k1DrawCapLine(ctx, 'WELCOME TO THE NEW YEAR', 0, -0.255, 0.042, 0.24, cyanTube, breath * hFade, hIn, true);
    const fIn = k1EaseOutCubic(k1SubRange(safeProgress, 0.26, 0.58));
    k1DrawCapLine(ctx, 'NEW HORIZONS • CELEBRATION', 0, 0.248, 0.034, 0.24, goldTube, breath * 0.9 * hFade, fIn, true);
  } else if (safeScene === 3) {
    /* Scene 3 uses Band 1 & Upper Stage for Script "Happy New Year", Band 3 Footer stays clean below */
    const fIn = k1EaseOutCubic(k1SubRange(safeProgress, 0.18, 0.45));
    const fFade = 1 - k1EaseInCubic(k1SubRange(safeProgress, 0.78, 0.94));
    k1DrawCapLine(ctx, 'CHEERS TO 2027', 0, 0.248, 0.034, 0.28, cyanTube, breath * 0.92 * fFade, fIn, true);
  }

  /* ---------- 7. BAND 2 CENTRAL HERO STAGE ---------- */
  if (safeScene === 0) {
    /* Precision Geometric Calibration Ring & Center 4-Point Midnight Star (y = -0.005, r <= 0.155) */
    const dialIn = k1EaseInOutCubic(k1SubRange(safeProgress, 0.18, 0.65));
    const dialOut = k1EaseInCubic(k1SubRange(safeProgress, 0.82, 1.00));
    const dialR = 0.148;
    const sweepEnd = dialIn;
    const sweepStart = dialOut;

    /* Recessed dial circle track */
    ctx.beginPath();
    ctx.arc(0, -0.005, dialR, 0, TAU);
    ctx.lineWidth = 0.011;
    ctx.strokeStyle = K1_PALETTE.tubeBed;
    ctx.stroke();

    if (sweepEnd > sweepStart + 0.005) {
      const a0 = -HALF_PI + sweepStart * TAU;
      const a1 = -HALF_PI + sweepEnd * TAU;
      ctx.beginPath();
      ctx.arc(0, -0.005, dialR, a0, a1);
      ctx.lineWidth = 0.011;
      ctx.strokeStyle = K1_PALETTE.cyanOuter;
      ctx.globalAlpha = 0.35 * breath;
      ctx.stroke();

      ctx.lineWidth = 0.0065;
      ctx.strokeStyle = K1_PALETTE.cyanMid;
      ctx.globalAlpha = 0.92 * breath;
      ctx.stroke();

      ctx.lineWidth = 0.0024;
      ctx.strokeStyle = K1_PALETTE.cyanCore;
      ctx.globalAlpha = breath;
      ctx.stroke();
      ctx.globalAlpha = 1;
    }

    /* 12 crisp radial calibration ticks strictly inside [0.108..0.128] */
    const ticksVis = k1EaseOutCubic(k1SubRange(safeProgress, 0.30, 0.65)) * (1 - dialOut);
    if (ticksVis > 0.01) {
      ctx.save();
      ctx.globalAlpha = ticksVis;
      for (let tIdx = 0; tIdx < 12; tIdx++) {
        const ang = -HALF_PI + tIdx * (TAU / 12);
        const rIn = tIdx % 3 === 0 ? 0.104 : 0.114;
        const rOut = 0.128;
        ctx.beginPath();
        ctx.moveTo(Math.cos(ang) * rIn, -0.005 + Math.sin(ang) * rIn);
        ctx.lineTo(Math.cos(ang) * rOut, -0.005 + Math.sin(ang) * rOut);
        ctx.lineWidth = tIdx % 3 === 0 ? 0.0042 : 0.0024;
        ctx.strokeStyle = tIdx % 3 === 0 ? K1_PALETTE.pinkMid : K1_PALETTE.cyanMid;
        ctx.stroke();
      }
      ctx.restore();
    }

    /* Smooth rotating midnight star/compass core (r <= 0.068, well inside 0.104) */
    const starScale = k1EaseOutQuart(k1SubRange(safeProgress, 0.25, 0.60)) * (1 - dialOut);
    if (starScale > 0.01) {
      ctx.save();
      ctx.translate(0, -0.005);
      ctx.rotate(k1EaseInOutCubic(safeProgress) * HALF_PI);
      const rLong = 0.066 * starScale;
      const rShort = 0.018 * starScale;
      ctx.beginPath();
      for (let p = 0; p < 8; p++) {
        const rad = p % 2 === 0 ? rLong : rShort;
        const ang = p * (Math.PI / 4);
        const px = Math.cos(ang) * rad;
        const py = Math.sin(ang) * rad;
        if (p === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.closePath();
      ctx.fillStyle = K1_PALETTE.tubeBed;
      ctx.fill();
      ctx.lineWidth = 0.0052;
      ctx.strokeStyle = K1_PALETTE.pinkMid;
      ctx.stroke();
      ctx.lineWidth = 0.0020;
      ctx.strokeStyle = K1_PALETTE.pinkCore;
      ctx.stroke();
      ctx.restore();
    }
  } else if (safeScene === 1) {
    /* Sequential Neon Countdown 3 -> 2 -> 1 (1.667s each, strictly non-overlapping!) */
    const subIdx = Math.min(2, Math.floor(safeProgress * 3));
    const subP = (safeProgress * 3) - subIdx;
    const digits = ['3', '2', '1'];
    const digitCols = [pinkTube, cyanTube, goldTube];
    const activeChar = digits[subIdx];
    const activeCol = digitCols[subIdx];

    const dIn = k1EaseInOutCubic(k1SubRange(subP, 0.00, 0.36));
    const dOut = k1EaseInCubic(k1SubRange(subP, 0.74, 0.98));
    const dScale = k1Lerp(0.95, 1.02, k1EaseOutCubic(k1SubRange(subP, 0.00, 0.45))) * (1 - 0.05 * dOut);
    const dAlpha = 1 - k1EaseInCubic(k1SubRange(subP, 0.86, 1.00));

    /* Outer circular timing ring around digit (r = 0.165, digit strictly inside r <= 0.11) */
    const ringR = 0.165;
    ctx.beginPath();
    ctx.arc(0, -0.005, ringR, 0, TAU);
    ctx.lineWidth = 0.0085;
    ctx.strokeStyle = K1_PALETTE.tubeBed;
    ctx.stroke();

    const ringEnd = k1EaseOutCubic(k1SubRange(subP, 0.00, 0.78));
    const ringStart = k1EaseInCubic(k1SubRange(subP, 0.76, 1.00));
    if (ringEnd > ringStart + 0.005) {
      ctx.beginPath();
      ctx.arc(0, -0.005, ringR, -HALF_PI + ringStart * TAU, -HALF_PI + ringEnd * TAU);
      ctx.lineWidth = 0.0095;
      ctx.strokeStyle = activeCol.outer;
      ctx.globalAlpha = 0.35 * breath;
      ctx.stroke();

      ctx.lineWidth = 0.0052;
      ctx.strokeStyle = activeCol.mid;
      ctx.globalAlpha = 0.92 * breath;
      ctx.stroke();

      ctx.lineWidth = 0.0018;
      ctx.strokeStyle = activeCol.core;
      ctx.globalAlpha = breath;
      ctx.stroke();
      ctx.globalAlpha = 1;
    }

    /* Crisp centered neon countdown digit */
    const digH = 0.195 * dScale;
    const digW = 0.125 * dScale;
    const polys = K1_HERO_DIGITS[activeChar];
    k1DrawNeonPaths(ctx, polys, -digW * 0.5, -0.005 - digH * 0.5, digW, digH, 0.0115, activeCol, breath * dAlpha, dOut, dIn, true);
  } else {
    /* Scene 2 (10-15s) & Scene 3 (15-20s): Hero "2027" + Flanking Wing Bars + Scene 3 "Happy New Year" Script */
    const isS3 = safeScene === 3;
    const glideToS3 = isS3 ? k1EaseInOutCubic(k1SubRange(safeProgress, 0.00, 0.24)) : 0;

    const yearY = k1Lerp(-0.005, 0.055, glideToS3);
    const yearScale = k1Lerp(1.00, 0.88, glideToS3);
    const digH = 0.210 * yearScale;
    const digW = 0.132 * yearScale;
    const digGap = 0.052 * yearScale;
    const totalYearW = 4 * digW + 3 * digGap;
    const yearStartX = -totalYearW * 0.5;

    const yearChars = ['2', '0', '2', '7'];
    const yearCols = [pinkTube, cyanTube, pinkTube, cyanTube];

    const retractGlobal = isS3 ? k1EaseInCubic(k1SubRange(safeProgress, 0.78, 0.94)) : 0;
    const yearAlpha = 1 - k1EaseInCubic(k1SubRange(retractGlobal, 0.75, 1.0));

    for (let i = 0; i < 4; i++) {
      const ch = yearChars[i];
      const gx = yearStartX + i * (digW + digGap);
      const gy = yearY - digH * 0.5;
      const stag = i * 0.085;
      const dEnd = isS3 ? 1 : k1EaseInOutCubic(k1SubRange(safeProgress, 0.04 + stag, 0.44 + stag));
      const dStart = isS3 ? k1EaseInCubic(k1Clamp01((safeProgress - (0.76 + i * 0.02)) / 0.16)) : 0;

      k1DrawNeonPaths(ctx, K1_HERO_DIGITS[ch], gx, gy, digW, digH, 0.0128 * yearScale, yearCols[i], breath * yearAlpha, dStart, dEnd, true);
    }

    /* Strictly separated Left & Right Flanking Neon Wing Bars (|x| >= totalYearW*0.5 + 0.065) */
    const wingInnerX = totalYearW * 0.5 + 0.065;
    const wingOuterX = wingInnerX + 0.135 * yearScale;
    const wingIn = isS3 ? 1 : k1EaseInOutCubic(k1SubRange(safeProgress, 0.24, 0.58));
    const wingOut = isS3 ? k1EaseInCubic(k1SubRange(safeProgress, 0.76, 0.92)) : 0;

    if (wingIn > wingOut + 0.01) {
      const barOffsets = [-0.046 * yearScale, 0, 0.046 * yearScale];
      const barLens = [0.72, 1.00, 0.72];
      for (let side = -1; side <= 1; side += 2) {
        for (let b = 0; b < 3; b++) {
          const by = yearY + barOffsets[b];
          const x0 = side * wingInnerX;
          const x1 = side * k1Lerp(wingInnerX, wingOuterX, barLens[b]);
          const sx0 = k1Lerp(x0, x1, wingOut);
          const sx1 = k1Lerp(x0, x1, wingIn);

          ctx.beginPath();
          ctx.moveTo(x0, by);
          ctx.lineTo(x1, by);
          ctx.lineWidth = 0.0082 * yearScale;
          ctx.strokeStyle = K1_PALETTE.tubeBed;
          ctx.stroke();

          if (Math.abs(sx1 - sx0) > 0.002) {
            const col = b === 1 ? goldTube : (side < 0 ? pinkTube : cyanTube);
            ctx.beginPath();
            ctx.moveTo(sx0, by);
            ctx.lineTo(sx1, by);
            ctx.lineWidth = 0.0094 * yearScale;
            ctx.strokeStyle = col.outer;
            ctx.globalAlpha = 0.34 * breath * yearAlpha;
            ctx.stroke();

            ctx.lineWidth = 0.0052 * yearScale;
            ctx.strokeStyle = col.mid;
            ctx.globalAlpha = 0.92 * breath * yearAlpha;
            ctx.stroke();

            ctx.lineWidth = 0.0018 * yearScale;
            ctx.strokeStyle = col.core;
            ctx.globalAlpha = breath * yearAlpha;
            ctx.stroke();
            ctx.globalAlpha = 1;
          }
        }
      }
    }

    /* Scene 3 Upper Hero Band: Script "Happy New Year" strictly above "2027" (y = -0.155, gap >= 0.065) */
    if (isS3) {
      const scriptReveal = k1SubRange(safeProgress, 0.12, 0.56);
      const scriptRetract = k1SubRange(safeProgress, 0.74, 0.92);
      const scriptAlpha = 1 - k1EaseInCubic(k1SubRange(safeProgress, 0.88, 0.96));
      k1DrawScriptPhrase(ctx, ['Happy', 'New', 'Year'], 0, -0.155, 0.128, goldTube, breath * scriptAlpha, scriptReveal, scriptRetract);
    }
  }

  ctx.restore(); /* end U space */
  ctx.restore(); /* end outer draw */
}
